// BUILD MARKER: V4.7.50 — RESTORE INDEX PORTFOLIO API + V4.7.49 BASELINE
// --- [CONFIG ADMINISTRACYJNY] ---
const SPREADSHEET_ID = "1z6DfA3e6cfL3uw21TRewF7JhThMV8Y1alc5sXpM1wZI"; // TEST DATABASE ONLY
const PORTFOLIO_FOLDER_ID = "1oUW1-wgM3Q7DoC4wljPWVy2FGC5PYeii"; // INDEX gallery, READ ONLY

const SHEET_DRAFT = "Szkic";
const SHEET_PUBLIC = "Cennik";
const SHEET_SETTINGS = "Ustawienia";
const SHEET_BOOKINGS = "Wizyty";
const SHEET_CUSTOMERS = "Klienci";
const SHEET_TEST_REPORTS = "Testy CRM";
const SHEET_VISIT_HISTORY = "Historia wizyt";
const SHEET_CLIENT_RESTRICTIONS = "Ograniczenia klientów";
const SHEET_FAMILY_SCHEDULE = "Grafik rodzinny";
const SHEET_SCHEDULE_IMPORTS = "Importy grafiku";
const SHEET_SCHEDULE_HISTORY = "Historia grafiku";
const SCHEDULE_DRIVE_FOLDER_ID = "1FGUTsK9t9N_hTlMiC7BC8LbjX_Nsi4kM"; // TEST schedule folder only
const SCHEDULE_EMPLOYEE_NAME = "Oleksandr Strelnikov";
const SCHEDULE_FILE_PATTERN = /^\d{4}-\d{2}(?:\.[a-z0-9]+)?$/i;
const WORK_SCHEDULE_CALENDAR_MARKER = "CRM_WORK_SHIFT";
const SHEET_CALENDAR_SYNC_LOG = "Historia synchronizacji";
const SHEET_ADMIN_BACKUPS = "Backup ADMIN";

function getSpreadsheet() {
  return SpreadsheetApp.openById(SPREADSHEET_ID);
}

// Pobieranie ustawień z bazy - kolory są trwałą listą kategorii
function normalizeTimeValue(value, ss) {
  if (value === undefined || value === null || value === "") {
    return "";
  }

  if (value instanceof Date) {
    return Utilities.formatDate(
      value,
      ss.getSpreadsheetTimeZone(),
      "HH:mm"
    );
  }

  if (typeof value === "number") {
    const totalMinutes = Math.round(value * 24 * 60);
    const hours = Math.floor(totalMinutes / 60) % 24;
    const minutes = totalMinutes % 60;

    return (
      String(hours).padStart(2, "0") +
      ":" +
      String(minutes).padStart(2, "0")
    );
  }

  const text = value.toString().trim();

  if (text.includes(":")) {
    return text.substring(0, 5);
  }

  const num = Number(text);

  if (!isNaN(num) && num >= 0 && num < 1) {
    const totalMinutes = Math.round(num * 24 * 60);
    const hours = Math.floor(totalMinutes / 60) % 24;
    const minutes = totalMinutes % 60;

    return (
      String(hours).padStart(2, "0") +
      ":" +
      String(minutes).padStart(2, "0")
    );
  }

  return text.substring(0, 5);
}
function getDynamicSettings(ss) {
  const settings = {
    work_start_hour: "09:00",
    work_end_hour: "18:00",
    buffer_hours: 1,
    safety_range_hours: 5,
    slot_interval_minutes: 45,
    start_offset_minutes: 0,
    cleanup_buffer_minutes: 0,
    schedule_cycle: "4x4",
    calendar_id: "",
    wife_calendar_id: "",
    work_schedule_calendar_id: "",
    test_mode: false,
    schedule_source_sheet_id: "",
    colors: {},
    all_categories: [] // Trwała lista kategorii wyciągnięta z zapisanych kolorów
  };
  if (!ss) ss = getSpreadsheet();
  const settingsSheet = ss.getSheetByName(SHEET_SETTINGS);
  if (settingsSheet && settingsSheet.getLastRow() > 1) {
    const rows = settingsSheet.getRange(2, 1, settingsSheet.getLastRow() - 1, 3).getValues();
    rows.forEach(r => {
      const key = r[0] ? r[0].toString().trim() : "";
      let val = r[1];
      if (key && val !== undefined && val !== "") {
        if (val instanceof Date) {
          val = Utilities.formatDate(val, ss.getSpreadsheetTimeZone(), "HH:mm");
        } else {
          val = val.toString().trim();
        }
        if (key.startsWith("color_")) {
          const catName = key.replace("color_", "");
          settings.colors[catName] = val;
          if (!settings.all_categories.includes(catName)) {
            settings.all_categories.push(catName);
          }
       } else if (key === "work_start_hour") {
  settings.work_start_hour = normalizeTimeValue(r[1], ss) || "09:00";
} else if (key === "work_end_hour") {
  settings.work_end_hour = normalizeTimeValue(r[1], ss) || "18:00";
        } else if (key === "buffer_hours") {
          settings.buffer_hours = Math.max(0, parseInt(val, 10) || 0);
        } else if (key === "slot_interval_minutes") {
          settings.slot_interval_minutes = Math.max(5, parseInt(val, 10) || 45);
        } else if (key === "start_offset_minutes") {
          settings.start_offset_minutes = Math.max(0, parseInt(val, 10) || 0);
        } else if (key === "cleanup_buffer_minutes") {
          settings.cleanup_buffer_minutes = Math.max(0, parseInt(val, 10) || 0);
        } else if (key === "schedule_cycle") {
          settings.schedule_cycle = val || "4x4";
        } else if (key === "calendar_id") {
          settings.calendar_id = val;
        } else if (key === "wife_calendar_id") {
          settings.wife_calendar_id = val;
        } else if (key === "work_schedule_calendar_id") {
          settings.work_schedule_calendar_id = val;
        } else if (key === "test_mode") {
          settings.test_mode = String(val).toUpperCase() === "TRUE";
        } else if (key === "schedule_source_sheet_id") {
          settings.schedule_source_sheet_id = val;
        }
      }
    });
  }
  return settings;
}

// ==========================================================================
// ADMIN SOURCE V1 2026-08-12
// Trwale zrodlo wizyty. Kody techniczne sa niewidoczne dla uzytkownika.
// ==========================================================================
function crmNormalizeBookingSourceCode(value) {
  const raw = String(value || "").trim().toUpperCase().replace(/[\s-]+/g, "_");
  if (raw.indexOf("FORM") !== -1) return "FORM_FIRST";
  if (raw === "INDEX_REQUEST" || raw.indexOf("REQUEST") !== -1) return "INDEX_REQUEST";
  if (raw === "INDEX" || raw === "SITE" || raw === "ONLINE" || raw === "CLIENT" || raw === "KLIENT") return "INDEX";
  if (raw === "GOOGLE" || raw === "GOOGLE_CALENDAR") return "GOOGLE";
  if (raw === "ADMIN" || raw === "MISTRZYNI" || raw === "MASTER") return "ADMIN";
  if (raw === "LEGACY") return "LEGACY";
  return raw || "";
}

function crmInferBookingSourceFromRow(row) {
  const saved = crmNormalizeBookingSourceCode(row && row[12]);
  if (saved) return saved;

  const rodo = String(row && row[4] || "").trim().toUpperCase();
  const phone = String(row && row[1] || "").trim().toUpperCase();

  if (phone === "GOOGLE CALENDAR") return "GOOGLE";
  if (rodo.indexOf("CRM") !== -1 || rodo.indexOf("ADMIN") !== -1) return "ADMIN";
  if (rodo === "TAK" || rodo === "YES") return "INDEX";

  return "LEGACY";
}

function crmBookingSourceLabel(value) {
  const code = crmNormalizeBookingSourceCode(value);
  if (code === "FORM_FIRST") return "Pierwsza wizyta - zapytanie online";
  if (code === "INDEX_REQUEST") return "Prosba o termin przez strone";
  if (code === "INDEX") return "Rezerwacja przez strone";
  if (code === "ADMIN") return "Dodana przeze mnie";
  if (code === "GOOGLE") return "Google Kalendarz";
  if (String(code || "").indexOf("BOOKSY") !== -1) return "Booksy";
  return "Starsza wizyta";
}
// KONIEC ADMIN SOURCE V1

function normalizeActiveAppointmentStatus(value) {
  return (value || "")
    .toString()
    .trim()
    .toUpperCase()
    .replace(/[\s-]+/g, "_");
}

function isInactiveAppointmentStatus(value) {
  const status = normalizeActiveAppointmentStatus(value);
  return new Set([
    "ANULOWANA",
    "ANULOWANA_KLIENT",
    "ANULOWANA_SALON",
    "CANCELLED",
    "CANCELLED_CLIENT",
    "CANCELLED_SALON",
    "ODRZUCONA",
    "REJECTED",
    "PRZENIESIONA",
    "NIEOBECNOSC",
    "NIEOBECNOŚĆ",
    "NO_SHOW"
  ]).has(status);
}

function getAllBusyIntervals(ss, settings, requestedStart, requestedEnd) {
  const intervals = [];
  let servicesSheet = ss.getSheetByName(SHEET_PUBLIC) || ss.getSheetByName(SHEET_DRAFT);
  const serviceDuration = {};
  if (servicesSheet && servicesSheet.getLastRow() > 1) {
    const sVals = servicesSheet.getRange(2, 1, servicesSheet.getLastRow() - 1, 4).getValues();
    sVals.forEach(row => {
      const name = row[1] ? row[1].toString().trim() : "";
      const dur = row[3] ? parseInt(row[3], 10) : 45;
      if (name) serviceDuration[name] = dur;
    });
  }

  const knownSheetEventIds = new Set();
  const knownSheetTimes = new Set();

  let bookingsSheet = ss.getSheetByName(SHEET_BOOKINGS);
  if (bookingsSheet && bookingsSheet.getLastRow() > 1) {
    const bookingColumnCount = Math.max(9, bookingsSheet.getLastColumn());
    const values = bookingsSheet.getRange(2, 1, bookingsSheet.getLastRow() - 1, bookingColumnCount).getValues();
    values.forEach(row => {
      let startDate = null;
      if (row[0] instanceof Date) startDate = row[0];
      else if (row[0]) startDate = new Date(row[0].toString().trim());

      if (startDate && !isNaN(startDate.getTime())) {
        const clientPhone = row[1] ? row[1].toString().trim() : "";
        const clientName = row[2] ? row[2].toString().trim() : "";
        const serviceName = row[3] ? row[3].toString().trim() : "";
        const eventId = row[6] ? row[6].toString().trim() : "";
        const status = row[8] ? row[8].toString().trim() : "POTWIERDZONA";
        const bookingSource = crmInferBookingSourceFromRow(row);
        const sourceRequestId = row[13] ? row[13].toString().trim() : "";
        const firstVisit = String(row[14] || "").trim().toUpperCase() === "TAK";
        const appointmentId = row[9] ? row[9].toString().trim() : "";

        /*
         * Event ID i termin zapamiętujemy również dla anulowanych rekordów.
         * Dzięki temu ewentualne stare wydarzenie Google nie wróci jako
         * neutralne wydarzenie zewnętrzne.
         */
        if (eventId) knownSheetEventIds.add(eventId);
        knownSheetTimes.add(startDate.getTime() + "_" + clientName);

        /* Historia pozostaje w arkuszu, ale rekord nie wraca do aktywnego kalendarza. */
        if (isInactiveAppointmentStatus(status)) return;

        const savedDuration = row[7] !== undefined && row[7] !== ""
          ? parseInt(row[7], 10)
          : 0;
        const dur = savedDuration || serviceDuration[serviceName] || settings.slot_interval_minutes || 45;
        const endDate = new Date(startDate.getTime() + dur * 60000);

        intervals.push({
          start: startDate, end: endDate, source: "sheet",
          name: clientName, phone: clientPhone, service: serviceName,
          eventId: eventId, duration: dur, status: status,
          bookingSource: bookingSource,
          sourceRequestId: sourceRequestId,
          appointmentId: appointmentId,
          firstVisit: firstVisit
        });
      }
    });
  }

  try {

  const now = new Date();

  const startRange = requestedStart instanceof Date && !isNaN(requestedStart.getTime())
    ? new Date(requestedStart)
    : new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 0, 0, 0);

  const endRange = requestedEnd instanceof Date && !isNaN(requestedEnd.getTime())
    ? new Date(requestedEnd)
    : new Date(now.getTime() + 95 * 24 * 60 * 60 * 1000);

  startRange.setHours(0, 0, 0, 0);
  endRange.setHours(23, 59, 59, 999);

  const calendar =
    CalendarApp.getCalendarById(
      settings.calendar_id
    );

  if (calendar) {

    const events =
      calendar.getEvents(
        startRange,
        endRange
      );

    events.forEach(event => {

      const evId =
        event.getId();

      const evStart =
        event.getStartTime();

      const evTitle =
        event.getTitle() ||
        "Zablokowane";
      const evDescription = event.getDescription() || "";
      const isWorkShift = evDescription.indexOf(WORK_SCHEDULE_CALENDAR_MARKER) === 0;
      const isCRMBlock = evDescription.indexOf("CRM_BLOCK_TIME") !== -1 || evDescription.indexOf("Blokada czasu dodana z CRM") !== -1;

      if (
        knownSheetEventIds.has(evId)
      ) return;

      let isDuplicateByTime =
        false;

      knownSheetTimes.forEach(
        sheetTimeKey => {

          const [
            timeStr,
            clientName
          ] =
          sheetTimeKey.split("_");

          if (
            Number(timeStr) === evStart.getTime()
            &&
            clientName
            &&
            evTitle.includes(clientName)
          ) {
            isDuplicateByTime = true;
          }

        }
      );

      if (
        isDuplicateByTime
      ) return;

      intervals.push({

        start: evStart,

        end:
          event.getEndTime(),

        source:
          isWorkShift ? "work_shift" : (isCRMBlock ? "block" : "calendar"),

        title:
          evTitle,

        description:
          evDescription,

        eventId:
          evId

      });

    });

  }

  // V4.7.11: grafik "Brak/BRAK" jest w osobnym kalendarzu technicznym.
  // Dodajemy go WYŁĄCZNIE do widoku ADMIN jako work_shift.
  // Nie jest to blokada rezerwacji i nie zapisujemy nic do kalendarza źródłowego.
  const workScheduleCalendarId = String(settings.work_schedule_calendar_id || "").trim();
  if (workScheduleCalendarId && workScheduleCalendarId !== String(settings.calendar_id || "").trim()) {
    const workScheduleCalendar = CalendarApp.getCalendarById(workScheduleCalendarId);
    if (workScheduleCalendar) {
      workScheduleCalendar.getEvents(startRange, endRange).forEach(function(event) {
        const description = String(event.getDescription() || "");
        if (description.indexOf(WORK_SCHEDULE_CALENDAR_MARKER) !== 0) return;

        const title = String(event.getTitle() || "Brak").trim() || "Brak";
        if (["Brak", "BRAK"].indexOf(title) === -1) return;

        intervals.push({
          start: event.getStartTime(),
          end: event.getEndTime(),
          source: "work_shift",
          title: title,
          description: description,
          eventId: event.getId()
        });
      });
    }
  }

} catch (e) {}

return intervals;

}

function formatDateToISOString(date, timeZone) {
  if (!(date instanceof Date) || isNaN(date.getTime())) return "";
  const zone = timeZone || getSpreadsheet().getSpreadsheetTimeZone() || "Europe/Warsaw";
  return Utilities.formatDate(date, zone, "yyyy-MM-dd'T'HH:mm");
}

// ==========================================================================
// ADMIN RELIABILITY V1 2026-08-12
// Idempotentny zapis wizyty + lekki stan zakladek.
// ==========================================================================
function crmFindBookingByOperationId(ss, operationId) {
  const wanted = String(operationId || "").trim();
  if (!wanted) return null;

  const sheet = ss.getSheetByName(SHEET_BOOKINGS);
  if (!sheet || sheet.getLastRow() < 2 || sheet.getLastColumn() < 16) return null;

  const values = sheet.getRange(2, 1, sheet.getLastRow() - 1, 16).getValues();
  for (let i = values.length - 1; i >= 0; i--) {
    if (String(values[i][15] || "").trim() !== wanted) continue;
    return {
      row: i + 2,
      date: values[i][0],
      phone: String(values[i][1] || ""),
      name: String(values[i][2] || ""),
      service: String(values[i][3] || ""),
      eventId: String(values[i][6] || ""),
      duration: Number(values[i][7]) || 45,
      status: String(values[i][8] || "POTWIERDZONA"),
      appointmentId: String(values[i][9] || ""),
      bookingSource: String(values[i][12] || ""),
      sourceRequestId: String(values[i][13] || ""),
      firstVisit: String(values[i][14] || "").toUpperCase() === "TAK",
      operationId: wanted
    };
  }
  return null;
}

function crmBookingOperationStatusData(ss, operationId) {
  const found = crmFindBookingByOperationId(ss, operationId);
  if (!found) return { success:true, found:false, operationId:String(operationId || "") };

  const tz = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
  return {
    success:true,
    found:true,
    operationId:found.operationId,
    eventId:found.eventId,
    appointmentId:found.appointmentId,
    bookingSource:found.bookingSource,
    sourceRequestId:found.sourceRequestId,
    firstVisit:found.firstVisit,
    date:found.date instanceof Date ? Utilities.formatDate(found.date, tz, "yyyy-MM-dd'T'HH:mm") : String(found.date || ""),
    phone:found.phone,
    name:found.name,
    service:found.service,
    duration:found.duration,
    status:found.status
  };
}

function crmFastSheetToken(sheet, columns) {
  if (!sheet) return "0:0";

  const lastRow = sheet.getLastRow();
  const lastCol = sheet.getLastColumn();
  if (lastRow <= 0) return "0:" + lastCol;

  const width = Math.max(
    1,
    Math.min(Number(columns) || lastCol || 1, lastCol || 1)
  );

  // Stan kontrolny ma być bardzo lekki: numer ostatniego wiersza +
  // jego najważniejsze wartości. Kalendarz i tak ma osobny checkBusy.
  const row = sheet
    .getRange(lastRow, 1, 1, width)
    .getDisplayValues()[0];

  return lastRow + ":" + row.join("¦").substring(0, 500);
}

// V4.7.14 — stan Cennika DOM dla badge ADMINA.
// Porównujemy szkic i publikację bez kolumny Status (G), bo ta technicznie
// różni się między "Szkic" i "Opublikowany" mimo identycznej treści usługi.
function crmDomPriceCanonicalRowsV4713(sheet){
  if(!sheet || sheet.getLastRow()<2) return [];
  crmEnsurePriceFirstVisitHeadersV267(sheet);
  const rows=sheet.getRange(2,1,sheet.getLastRow()-1,14).getDisplayValues();
  return rows
    .filter(function(r){ return String(r[0]||'').trim() || String(r[1]||'').trim(); })
    .map(function(r){
      return [r[0],r[1],r[2],r[3],r[4],r[5],r[7],r[8],r[9],r[10],r[11],r[12],r[13]]
        .map(function(v){ return String(v==null?'':v).trim(); });
    });
}

function crmDomPriceStateV4713(ss){
  const draft=ss.getSheetByName(SHEET_DRAFT);
  const published=ss.getSheetByName(SHEET_PUBLIC);
  const draftRows=crmDomPriceCanonicalRowsV4713(draft);
  const publicRows=crmDomPriceCanonicalRowsV4713(published);
  return {
    success:true,
    draftCount:draftRows.length,
    publicCount:publicRows.length,
    hasDraft:draftRows.length>0,
    hasPublished:publicRows.length>0,
    isPublished:JSON.stringify(draftRows)===JSON.stringify(publicRows)
  };
}

function buildAdminStateV1(ss) {
  return {
    success:true,
    calendar:
      crmFastSheetToken(ss.getSheetByName(SHEET_BOOKINGS), 16) + "|" +
      crmFastSheetToken(ss.getSheetByName(SHEET_SETTINGS), 4),
    clients: crmFastSheetToken(ss.getSheetByName(SHEET_CUSTOMERS), 9),
    services:
      crmFastSheetToken(ss.getSheetByName(SHEET_PUBLIC), 14) + "|" +
      crmFastSheetToken(ss.getSheetByName(SHEET_DRAFT), 14),
    inbox:
      crmFastSheetToken(ss.getSheetByName("Prośby o wizytę"), 26) + "|" +
      crmFastSheetToken(ss.getSheetByName(SHEET_CONTACT_REQUESTS), 8)
  };
}
// KONIEC ADMIN RELIABILITY V1

function crmFinalizeFirstVisitRequestV8(ss, requestId, chosenDate, eventId) {
  const wanted = String(requestId || "").trim();
  if (!wanted) return false;
  const requestSheet = bookingRequestsSheet(ss);
  if (!requestSheet || requestSheet.getLastRow() < 2) return false;
  const rows = requestSheet.getRange(2,1,requestSheet.getLastRow()-1,Math.max(19,requestSheet.getLastColumn())).getValues();
  for (let i=0;i<rows.length;i++) {
    if (String(rows[i][0]||"").trim() !== wanted) continue;
    const rowNumber=i+2;
    requestSheet.getRange(rowNumber,10).setValue("POTWIERDZONA");
    if (chosenDate) requestSheet.getRange(rowNumber,11).setValue(chosenDate instanceof Date ? chosenDate : new Date(chosenDate));
    if (eventId) requestSheet.getRange(rowNumber,12).setValue(String(eventId));
    requestSheet.getRange(rowNumber,13).setValue(new Date());
    requestSheet.getRange(rowNumber,14).setValue("OBSŁUŻONE");
    return true;
  }
  return false;
}

// ==========================================================================
// ADMIN GET TRANSPORT V10 2026-08-12
// JSON oraz JSONP dla lekkich endpointów ADMIN.
// ==========================================================================

// ==========================================================================
// ADMIN CLEAN BOOT V12 2026-08-12
// Jeden bootstrap + czysty odczyt klientów bez synchronizacji/zapisów.
// ==========================================================================
function getServicesDataFastV12(ss) {
  const sheet = ss.getSheetByName(SHEET_PUBLIC) || ss.getSheetByName(SHEET_DRAFT);
  if (!sheet || sheet.getLastRow() < 2) return [];

  const values = sheet.getRange(2, 1, sheet.getLastRow() - 1, 14).getValues();
  const services = [];

  values.forEach(function(row) {
    const category = row[0] ? row[0].toString().trim() : "";
    const name = row[1] ? row[1].toString().trim() : "";
    if (!category || !name) return;

    services.push({
      category: category,
      name: name,
      price: row[2] !== "" ? Number(row[2]) : 0,
      duration: row[3] !== "" ? Number(row[3]) : 45,
      showPrice: row[4] !== "" ? row[4].toString().trim() : "Tak",
      showDuration: row[5] !== "" ? row[5].toString().trim() : "Tak",
      status: row[6] || "Szkic",
      categoryId: row[7] || "",
      categoryOrder: row[8] !== "" ? Number(row[8]) : 0,
      serviceId: row[9] || "",
      serviceOrder: row[10] !== "" ? Number(row[10]) : 0,
      categoryColor: row[11] || "#b05c75",
      firstVisitMode:
        String(row[12] || "AUTO").trim().toUpperCase() === "MANUAL"
          ? "MANUAL"
          : "AUTO",
      firstVisitManualMinutes:
        row[13] !== "" ? Math.max(0, Number(row[13]) || 0) : 0
    });
  });

  return services;
}

function getClientsDataFastV12(ss) {
  const sheet = ss.getSheetByName(SHEET_CUSTOMERS);
  if (!sheet || sheet.getLastRow() < 2) return [];

  const width = Math.max(9, sheet.getLastColumn());
  const values = sheet.getRange(2, 1, sheet.getLastRow() - 1, width).getValues();
  const timeZone = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";

  return values.map(function(row) {
    const visits = typeof row[2] === "number" && !(row[2] instanceof Date)
      ? Math.max(0, Math.trunc(row[2]))
      : 0;
    const cancelled = typeof row[3] === "number" && !(row[3] instanceof Date)
      ? Math.max(0, Math.trunc(row[3]))
      : 0;
    const lastVisitDate = row[4] instanceof Date
      ? row[4]
      : (row[4] ? new Date(row[4]) : null);

    return {
      phone: normalizeCRMPhone(row[0]),
      name: row[1] || "",
      visits: visits,
      cancelled: cancelled,
      lastVisit: lastVisitDate && !isNaN(lastVisitDate.getTime())
        ? Utilities.formatDate(lastVisitDate, timeZone, "yyyy-MM-dd HH:mm")
        : "",
      source: String(row[6] || "").trim(),
      sourceKey: String(row[7] || "").trim(),
      bookingMode: String(row[8] || "").trim()
    };
  });
}

// ==========================================================================
// V4.7.14 — pełny kontekst blokad/review z WIFE_CALENDAR w ADMINIE.
// Źródłowy kalendarz żony pozostaje bezwzględnie READ_ONLY.
// ==========================================================================
function crmV4713NormSourceId(value){
  return String(value||"").trim().replace(/@google\.com$/i,"").toLowerCase();
}

function crmV4713CalendarMeta(description){
  const text=String(description||"");
  const get=function(label){
    const re=new RegExp("(?:"+label+")\\s*:\\s*([^\\n]+)","i");
    const m=text.match(re);return m?String(m[1]||"").trim():"";
  };
  return {
    sourceType:get("Źródło|Zrodlo"),
    sourceId:get("SourceId"),
    originalTitle:get("Oryginalny tytuł|Oryginalny tytul")
  };
}

function crmV4713ReviewMap(ss){
  const map={};
  const sh=ss.getSheetByName("Do weryfikacji TEST");
  if(!sh||sh.getLastRow()<2)return map;
  const rows=sh.getRange(2,1,sh.getLastRow()-1,Math.max(9,sh.getLastColumn())).getValues();
  rows.forEach(function(r){
    const sourceId=String(r[2]||"").trim();
    const key=crmV4713NormSourceId(sourceId);
    if(!key)return;
    map[key]={
      sourceType:String(r[1]||"").trim(), sourceId:sourceId,
      reason:String(r[3]||"").trim(), client:String(r[4]||"").trim(),
      phone:String(r[5]||"").trim(), service:String(r[6]||"").trim(),
      start:r[7]||"", raw:String(r[8]||"").trim(), rowNumber:0
    };
  });
  return map;
}

function crmV4713MeaningfulExternalName(title,meta,review){
  if(review&&review.client)return review.client;
  const original=String((review&&review.raw)||meta.originalTitle||title||"").split(/\r?\n/)[0].trim();
  const cleaned=original
    .replace(/^\s*\d{1,2}:\d{2}\s*/,'')
    .replace(/^[^0-9A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż\u0400-\u04FF]+/,'')
    .replace(/^(?:może być na rano|moze byc na rano)\s+/i,'')
    .trim();
  if(cleaned && !/^zaj[eę]te(?:\s*[—-].*)?$/i.test(cleaned))return cleaned;
  return "Blokada czasu";
}

function crmV4714HardBlockLabel(rawValue){
  let clean=String(rawValue||"").split(/\r?\n/)[0].trim();
  clean=clean.replace(/^\d{1,2}:\d{2}\s*/,"")
    .replace(/^[^0-9A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż\u0400-\u04FF]+/,"")
    .replace(/^(?:może być na rano|moze byc na rano|może być rano|moze byc rano)\s+/i,"")
    .trim();
  const m=clean.match(/^(blokada|wolne|urlop|przerwa|prywatne|nieczynne|stomatolog|dentysta|lekarz|szkolenie|kurs|warsztat)\b/i);
  return m?String(m[1]||"").toUpperCase():"";
}

function buildCalendarDataV13(ss, params) {
  params=params||{};
  const settings=getDynamicSettings(ss);
  const timeZone=ss.getSpreadsheetTimeZone()||"Europe/Warsaw";
  let requestedStart=null,requestedEnd=null;
  try{
    if(params.rangeStart)requestedStart=Utilities.parseDate(String(params.rangeStart)+" 00:00",timeZone,"yyyy-MM-dd HH:mm");
    if(params.rangeEnd)requestedEnd=Utilities.parseDate(String(params.rangeEnd)+" 23:59",timeZone,"yyyy-MM-dd HH:mm");
  }catch(ignore){requestedStart=null;requestedEnd=null;}

  const reviewMap=crmV4713ReviewMap(ss);
  const busyIntervals=getAllBusyIntervals(ss,settings,requestedStart,requestedEnd);
  const appointments=busyIntervals.map(function(busy){
    const isCalendar=busy.source==="calendar";
    const meta=isCalendar?crmV4713CalendarMeta(busy.description||""):{sourceType:"",sourceId:"",originalTitle:""};
    const review=isCalendar?reviewMap[crmV4713NormSourceId(meta.sourceId)]:null;
    const wifeBlock=isCalendar&&String(meta.sourceType||"").toUpperCase()==="WIFE_CALENDAR_BLOCK";
    const warningTitle=/^\s*⚠️/.test(String(busy.title||""));
    const rawText=String((review&&review.raw)||meta.originalTitle||busy.title||"").trim();
    const hardBlockLabel=isCalendar?crmV4714HardBlockLabel(rawText):"";
    // V4.7.14: znane twarde blokady (np. STOMATOLOG) nie trafiają do review,
    // nawet jeśli po starym imporcie istnieje jeszcze wiersz w Do weryfikacji TEST.
    const reviewRequired=Boolean(!hardBlockLabel&&(review||warningTitle));
    const meaningfulName=hardBlockLabel|| (isCalendar?crmV4713MeaningfulExternalName(busy.title,meta,review):(busy.name||"Klient"));
    const reviewService=review&&review.service?review.service:"";

    return {
      date:formatDateToISOString(busy.start,timeZone),
      endDate:formatDateToISOString(busy.end,timeZone),
      phone:isCalendar?(review&&review.phone?review.phone:""):((busy.source==="block"||busy.source==="work_shift")?"":(busy.phone||"")),
      name:(isCalendar||busy.source==="block"||busy.source==="work_shift")?(isCalendar?meaningfulName:(busy.title||"Rezerwacja")):(busy.name||"Klient"),
      service:isCalendar?(hardBlockLabel?"Blokada czasu":(reviewService|| (reviewRequired?"Do sprawdzenia":"Rezerwacja zewnętrzna"))):(busy.source==="block"?"Blokada czasu":(busy.source==="work_shift"?"Grafik pracy":(busy.service||"Zabieg"))),
      category:hardBlockLabel?"BLOKADA":(reviewRequired?"DO_WERYFIKACJI":"Inne"),
      duration:Math.round((busy.end.getTime()-busy.start.getTime())/60000),
      eventId:busy.eventId||"", status:busy.status||"", crmStatus:busy.status||"",
      bookingSource:isCalendar?"GOOGLE":(busy.bookingSource||""),
      source:isCalendar?"GOOGLE":(busy.bookingSource||""),
      requestId:busy.sourceRequestId||"", appointmentId:busy.appointmentId||"", firstVisit:Boolean(busy.firstVisit),
      eventType:busy.source==="work_shift"?"work_shift":(busy.source==="block"?"block":(isCalendar?"external":"appointment")),
      displayOnly:busy.source==="work_shift",
      sourceType:isCalendar?(meta.sourceType|| (wifeBlock?"WIFE_CALENDAR_BLOCK":"GOOGLE_CALENDAR")):"",
      sourceId:isCalendar?(meta.sourceId||""):"",
      originalTitle:isCalendar?(meta.originalTitle||busy.title||""):"",
      rawText:isCalendar?rawText:"",
      reviewRequired:reviewRequired,
      reviewReason:hardBlockLabel?"":(review?review.reason:""),
      reviewClient:hardBlockLabel?"":(review?review.client:""),
      reviewService:hardBlockLabel?"":(review?review.service:""),
      reviewPhone:hardBlockLabel?"":(review?review.phone:""),
      knownHardBlock:Boolean(hardBlockLabel),
      blockLabel:hardBlockLabel,
      sourceReadOnly:wifeBlock,
      canEditReview:Boolean(wifeBlock&&reviewRequired),
      externalDescription:isCalendar?String(busy.description||""):""
    };
  });
  return {settings:settings,appointments:appointments};
}

function buildCalendarDataV12(ss, params) {
  params = params || {};
  const settings = getDynamicSettings(ss);
  const timeZone = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
  let requestedStart = null;
  let requestedEnd = null;

  try {
    if (params.rangeStart) {
      requestedStart = Utilities.parseDate(
        String(params.rangeStart) + " 00:00",
        timeZone,
        "yyyy-MM-dd HH:mm"
      );
    }
    if (params.rangeEnd) {
      requestedEnd = Utilities.parseDate(
        String(params.rangeEnd) + " 23:59",
        timeZone,
        "yyyy-MM-dd HH:mm"
      );
    }
  } catch (rangeError) {
    requestedStart = null;
    requestedEnd = null;
  }

  const busyIntervals = getAllBusyIntervals(
    ss,
    settings,
    requestedStart,
    requestedEnd
  );

  const appointments = busyIntervals.map(function(busy) {
    return {
      date: formatDateToISOString(busy.start, timeZone),
      endDate: formatDateToISOString(busy.end, timeZone),
      phone: busy.source === "calendar"
        ? "Google Calendar"
        : ((busy.source === "block" || busy.source === "work_shift") ? "" : (busy.phone || "")),
      name: (busy.source === "calendar" || busy.source === "block" || busy.source === "work_shift")
        ? (busy.title || "Rezerwacja")
        : (busy.name || "Klient"),
      service: busy.source === "calendar"
        ? "Rezerwacja zewnętrzna"
        : (busy.source === "block"
            ? "Blokada czasu"
            : (busy.source === "work_shift" ? "Grafik pracy" : (busy.service || "Zabieg"))),
      category: "Inne",
      duration: Math.round((busy.end.getTime() - busy.start.getTime()) / 60000),
      eventId: busy.eventId || "",
      status: busy.status || "",
      crmStatus: busy.status || "",
      bookingSource: busy.source === "calendar" ? "GOOGLE" : (busy.bookingSource || ""),
      source: busy.source === "calendar" ? "GOOGLE" : (busy.bookingSource || ""),
      requestId: busy.sourceRequestId || "",
      firstVisit: Boolean(busy.firstVisit),
      eventType: busy.source === "work_shift"
        ? "work_shift"
        : (busy.source === "block"
            ? "block"
            : (busy.source === "calendar" ? "external" : "appointment")),
      displayOnly: busy.source === "work_shift"
    };
  });

  return { settings: settings, appointments: appointments };
}

function buildAdminBootstrapV12(ss, params) {
  const t0 = Date.now();

  const tCalendar0 = Date.now();
  const calendar = buildCalendarDataV13(ss, params || {});
  const calendarMs = Date.now() - tCalendar0;

  const tServices0 = Date.now();
  const services = getServicesDataFastV12(ss);
  const servicesMs = Date.now() - tServices0;

  const tClients0 = Date.now();
  const clients = getClientsDataFastV12(ss);
  const clientsMs = Date.now() - tClients0;

  const tInbox0 = Date.now();
  const inboxPing = buildAdminInboxPingV1(ss);
  const inboxMs = Date.now() - tInbox0;

  return {
    success: true,
    settings: calendar.settings || {},
    appointments: calendar.appointments || [],
    services: services,
    clients: clients,
    inboxPing: inboxPing,
    generatedAt: new Date().toISOString(),
    perf: {
      calendarMs: calendarMs,
      servicesMs: servicesMs,
      clientsMs: clientsMs,
      inboxMs: inboxMs,
      totalMs: Date.now() - t0
    }
  };
}
