// ==========================================================================
// ADMIN V26.9 — HISTORIA OSÓB OCZEKUJĄCYCH
//
// Osobny endpoint wyłącznie dla zakładki:
// Klienci -> Historia.
//
// NIE jest częścią bootstrapu, pingu ani zwykłej Skrzynki.
// Dzięki temu pełna historia nie wydłuża aktualnych sprawdzeń ADMIN.
// ==========================================================================
function buildAdminClientRequestHistoryV269(ss, rawLimit) {
  const tz =
    ss.getSpreadsheetTimeZone() ||
    "Europe/Warsaw";

  const limit =
    Math.max(
      1,
      Math.min(
        200,
        Number(rawLimit) || 100
      )
    );

  const items = [];

  const bookingSheet =
    ss.getSheetByName(
      "Prośby o wizytę"
    );

  if (
    bookingSheet &&
    bookingSheet.getLastRow() > 1
  ) {
    const lastRow =
      bookingSheet.getLastRow();

    /*
     * Czytamy od końca maksymalnie 500 rekordów.
     * Historia jest lazy i ograniczona, więc nie obciąża startu.
     */
    const firstRow =
      Math.max(
        2,
        lastRow - 499
      );

    const rows =
      bookingSheet
        .getRange(
          firstRow,
          1,
          lastRow - firstRow + 1,
          Math.max(
            22,
            bookingSheet.getLastColumn()
          )
        )
        .getValues();

    for (
      let i = rows.length - 1;
      i >= 0 && items.length < limit;
      i--
    ) {
      const row = rows[i];

      const requestType =
        String(row[14] || "STANDARD")
          .trim()
          .toUpperCase();

      /*
       * Historia w Klientach dotyczy osób,
       * które przyszły przez FIRST_VISIT.
       * Standardowe prośby istniejących klientów
       * pozostają historią rezerwacji, nie oczekujących.
       */
      if (requestType !== "FIRST_VISIT") {
        continue;
      }

      const requestStatus =
        String(row[9] || "OCZEKUJE")
          .trim()
          .toUpperCase();

      const readState =
        crmInboxReadState(row[13]);

      const handled =
        requestStatus !== "OCZEKUJE" ||
        readState === "OBSŁUŻONE" ||
        readState === "OBSLUZONE";

      if (!handled) continue;

      let proposals = [];

      try {
        proposals =
          JSON.parse(
            String(row[16] || "[]")
          );

        if (!Array.isArray(proposals)) {
          proposals = [];
        }
      } catch (ignore) {
        proposals = [];
      }

      const created =
        row[1] instanceof Date
          ? Utilities.formatDate(
              row[1],
              tz,
              "dd.MM.yyyy HH:mm"
            )
          : String(row[1] || "");

      const handledAt =
        row[12] instanceof Date
          ? Utilities.formatDate(
              row[12],
              tz,
              "dd.MM.yyyy HH:mm"
            )
          : String(row[12] || created);

      items.push({
        type: "BOOKING_REQUEST",
        requestType: "FIRST_VISIT",
        id: String(row[0] || ""),
        createdAt: created,
        handledAt: handledAt,
        timestamp:
          row[12] instanceof Date
            ? row[12].getTime()
            : (
                row[1] instanceof Date
                  ? row[1].getTime()
                  : 0
              ),
        name: String(row[3] || ""),
        phone: String(row[2] || ""),
        email: String(row[15] || ""),
        service: String(row[4] || ""),
        category:
          String(
            row[19] ||
            row[4] ||
            ""
          ),
        preferredWindow:
          String(row[20] || ""),
        contactMethod:
          String(row[21] || "")
            .trim()
            .toUpperCase(),
        duration:
          Number(row[5]) || 45,
        proposals: proposals,
        message:
          String(row[18] || ""),
        status: requestStatus,
        businessStatus: requestStatus,
        readState: "OBSŁUŻONE"
      });
    }
  }

  const contactSheet =
    ss.getSheetByName(
      SHEET_CONTACT_REQUESTS
    );

  if (
    contactSheet &&
    contactSheet.getLastRow() > 1 &&
    items.length < limit
  ) {
    const lastRow =
      contactSheet.getLastRow();

    const firstRow =
      Math.max(
        2,
        lastRow - 299
      );

    const rows =
      contactSheet
        .getRange(
          firstRow,
          1,
          lastRow - firstRow + 1,
          8
        )
        .getValues();

    for (
      let i = rows.length - 1;
      i >= 0 && items.length < limit;
      i--
    ) {
      const row = rows[i];

      const status =
        String(row[5] || "NOWE")
          .trim()
          .toUpperCase();

      if (
        status === "NOWE" ||
        status === "PRZECZYTANE"
      ) {
        continue;
      }

      const created =
        row[1] instanceof Date
          ? Utilities.formatDate(
              row[1],
              tz,
              "dd.MM.yyyy HH:mm"
            )
          : String(row[1] || "");

      const handledAt =
        row[6] instanceof Date
          ? Utilities.formatDate(
              row[6],
              tz,
              "dd.MM.yyyy HH:mm"
            )
          : String(row[6] || created);

      items.push({
        type: "CONTACT_FORM",
        requestType: "CONTACT_FORM",
        id: String(row[0] || ""),
        createdAt: created,
        handledAt: handledAt,
        timestamp:
          row[6] instanceof Date
            ? row[6].getTime()
            : (
                row[1] instanceof Date
                  ? row[1].getTime()
                  : 0
              ),
        name: String(row[2] || ""),
        phone: String(row[3] || ""),
        email: "",
        service: "Pierwsza wizyta",
        category: "",
        preferredWindow: "",
        contactMethod: "PHONE",
        duration: 0,
        proposals: [],
        message: String(row[4] || ""),
        status: status,
        businessStatus: status,
        readState: "OBSŁUŻONE"
      });
    }
  }

  items.sort(function(a, b) {
    return (
      Number(b.timestamp || 0) -
      Number(a.timestamp || 0)
    );
  });

  return {
    success: true,
    items: items.slice(0, limit),
    count: Math.min(
      items.length,
      limit
    )
  };
}
