// ==========================================================================
// CRM V4 — źródło klienta + twarde reguły rezerwacji online
// ==========================================================================
function crmSourceHasV4(source, token) {
  const parts = String(source || "")
    .toUpperCase()
    .split(/[+|,;]/)
    .map(function(v){ return v.trim(); })
    .filter(Boolean);
  return parts.indexOf(String(token || "").toUpperCase()) !== -1;
}

function crmSourceLabelV4(sourceType) {
  const raw = String(sourceType || "").toUpperCase();
  if (raw === "BOOKSY_GMAIL" || raw === "BOOKSY") return "BOOKSY";
  if (raw === "WIFE_CALENDAR" || raw === "DOM") return "DOM";
  return raw || "CRM";
}

function crmSourceKeyV4(sourceType, sourceId) {
  const source = crmSourceLabelV4(sourceType);
  const id = String(sourceId || "").trim();
  return id ? source + ":" + id : "";
}

function crmSettingValueV4(ss, key) {
  const sh = ss.getSheetByName(SHEET_SETTINGS);
  if (!sh || sh.getLastRow() < 2) return "";
  const rows = sh.getRange(2, 1, sh.getLastRow() - 1, 2).getValues();
  for (let i = rows.length - 1; i >= 0; i--) {
    if (String(rows[i][0] || "").trim() === String(key || "").trim()) {
      return rows[i][1];
    }
  }
  return "";
}

function crmFindCustomerByPhoneV4(ss, phone) {
  const normalized = normalizeCRMPhone(phone || "");
  if (!normalized) return null;
  const sheet = ensureCustomerSheet(ss);
  if (sheet.getLastRow() < 2) return null;
  const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, Math.max(9, sheet.getLastColumn())).getValues();
  for (let i = 0; i < rows.length; i++) {
    if (normalizeCRMPhone(rows[i][0]) !== normalized) continue;
    return {
      row: i + 2,
      phone: normalized,
      name: String(rows[i][1] || "").trim(),
      visits: Number(rows[i][2]) || 0,
      cancelled: Number(rows[i][3]) || 0,
      lastVisit: rows[i][4] || "",
      source: String(rows[i][6] || "").trim(),
      sourceKey: String(rows[i][7] || "").trim(),
      bookingMode: String(rows[i][8] || "").trim()
    };
  }
  return null;
}

function crmRestrictionForPhoneV4(ss, phone) {
  const normalized = normalizeCRMPhone(phone || "");
  if (!normalized) return null;
  const sheet = ss.getSheetByName(SHEET_CLIENT_RESTRICTIONS);
  if (!sheet || sheet.getLastRow() < 2) return null;
  const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, Math.max(4, Math.min(12, sheet.getLastColumn()))).getValues();
  for (let i = rows.length - 1; i >= 0; i--) {
    if (normalizeCRMPhone(rows[i][0]) !== normalized) continue;
    return {
      mode: String(rows[i][1] || "STANDARDOWY").trim().toUpperCase(),
      level: String(rows[i][2] || "STANDARDOWY").trim().toUpperCase(),
      reason: String(rows[i][3] || "").trim()
    };
  }
  return null;
}

function crmEffectiveBookingModeV4(ss, customer) {
  if (!customer) return { mode: "", reason: "" };

  const restriction = crmRestrictionForPhoneV4(ss, customer.phone);

  // Twarda blokada zawsze ma najwyższy priorytet, także dla klienta Booksy.
  if (restriction && String(restriction.mode || "").toUpperCase() === "ZABLOKOWANY") {
    return {
      mode: "ZABLOKOWANY",
      reason: restriction.reason || "Rezerwacja online dla tego klienta jest zablokowana."
    };
  }

  // Klient pozyskany z Booksy nie może samodzielnie rezerwować przez CRM.
  if (crmSourceHasV4(customer.source, "BOOKSY")) {
    return {
      mode: "TYLKO_KONTAKT",
      reason: "Klient Booksy — rezerwacja online przez CRM jest wyłączona."
    };
  }

  if (restriction) {
    return { mode: restriction.mode || "STANDARDOWY", reason: restriction.reason || "" };
  }

  const storedMode = String(customer.bookingMode || "").trim().toUpperCase();
  return { mode: storedMode || "WYMAGA_POTWIERDZENIA", reason: "" };
}

function crmClientLookupV4(ss, phone) {
  const customer = crmFindCustomerByPhoneV4(ss, phone);
  if (!customer) {
    return { success: true, found: false, name: "", bookingMode: "", restrictionReason: "" };
  }
  const effective = crmEffectiveBookingModeV4(ss, customer);
  return {
    success: true,
    found: true,
    name: customer.name,
    phone: customer.phone,
    source: customer.source,
    sourceKey: customer.sourceKey,
    bookingMode: effective.mode,
    restrictionReason: effective.reason
  };
}

function crmPublicBookingGuardV4(ss, postData, requestKind) {
  const source = crmNormalizeBookingSourceCode(postData && postData.bookingSource || "INDEX") || "INDEX";
  if (source === "ADMIN" || source === "FORM_FIRST" || source === "GOOGLE") {
    return { success: true, bypass: true };
  }

  const phone = normalizeCRMPhone(postData && postData.phone || "");
  const customer = crmFindCustomerByPhoneV4(ss, phone);
  if (!customer) {
    return {
      success: false,
      code: "CLIENT_NOT_FOUND",
      error: "Klient nie został znaleziony w bazie CRM."
    };
  }

  const effective = crmEffectiveBookingModeV4(ss, customer);
  const mode = String(effective.mode || "STANDARDOWY").toUpperCase();
  const kind = String(requestKind || "BOOKING").toUpperCase();

  if (mode === "ZABLOKOWANY") {
    return {
      success: false,
      code: "CLIENT_BLOCKED",
      error: effective.reason || "Rezerwacja online dla tego klienta jest zablokowana."
    };
  }

  if (kind === "BOOKING" && mode === "TYLKO_KONTAKT") {
    return {
      success: false,
      code: "CONTACT_ONLY",
      error: effective.reason || "Rezerwacja wymaga kontaktu z salonem."
    };
  }

  if (kind === "BOOKING" && mode === "WYMAGA_POTWIERDZENIA") {
    return {
      success: false,
      code: "CONFIRMATION_REQUIRED",
      error: "Ta rezerwacja wymaga potwierdzenia przez salon."
    };
  }

  return { success: true, mode: mode, customer: customer };
}

function createBookingRequestActionV4(ss, postData) {
  try {
    const guard = crmPublicBookingGuardV4(ss, postData, "REQUEST");
    if (!guard.success) return createJsonResponse(guard);

    const sheet = bookingRequestsSheet(ss);
