const CRM_BOOKSY_ADMIN_HEADERS_V477 = [
  "Kategoria","Usługa","Cena (zł)","Czas (min)","Obowiązuje od","Obowiązuje do",
  "Status","Źródło","Data źródła","SourceId","Uwagi",
