function crmBooksyNormV477(value) {
  return String(value || "").trim().toLowerCase().normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ");
}

function crmBooksyHexV477(bytes) {
  return bytes.map(function(b) {
    const n = b < 0 ? b + 256 : b;
    return ("0" + n.toString(16)).slice(-2);
  }).join("");
}

function crmBooksyAdminIdV477(category, name) {
  const key = crmBooksyNormV477(category) + "|" + crmBooksyNormV477(name);
  const digest = Utilities.computeDigest(
    Utilities.DigestAlgorithm.MD5, key, Utilities.Charset.UTF_8
  );
  return "BKS-" + crmBooksyHexV477(digest).slice(0, 16);
}

function crmEnsureBooksyAdminHeadersV477(sheet) {
  if (!sheet) return;
  const current=sheet.getRange(1,1,1,CRM_BOOKSY_ADMIN_HEADERS_V477.length).getValues()[0];
  let needs=false;
  for(let i=0;i<CRM_BOOKSY_ADMIN_HEADERS_V477.length;i++){
    if(String(current[i]||"")!==String(CRM_BOOKSY_ADMIN_HEADERS_V477[i]||"")){needs=true;break;}
  }
  if(needs){
    sheet.getRange(1,1,1,CRM_BOOKSY_ADMIN_HEADERS_V477.length)
      .setValues([CRM_BOOKSY_ADMIN_HEADERS_V477]);
  }
}

