}

function crmBooksyIsActiveRowV477(row) {
  const status = String(row[6] || "").trim().toUpperCase();
  if (status && status !== "AKTYWNY") return false;
  const until = row[5];
  if (until instanceof Date && !isNaN(until.getTime())) {
    const end = new Date(until);
    end.setHours(23,59,59,999);
    if (end.getTime() < Date.now()) return false;
  }
  return true;
}

function crmBooksyReadActiveV477(ss) {
  const sheet = testBooksyPriceSheetV44(ss);
  crmEnsureBooksyAdminHeadersV477(sheet);

  if (sheet.getLastRow() < 2) {
    return { sheet:sheet, items:[], rows:[], activeRowsById:{} };
  }

  const values = sheet.getRange(
    2, 1, sheet.getLastRow() - 1, CRM_BOOKSY_ADMIN_HEADERS_V477.length
  ).getValues();

  const categoryOrderFallback = {};
  const categoryServiceCount = {};
  let nextCategoryOrder = 1;
  const byId = {};
  const activeRowsById = {};

  values.forEach(function(row, index) {
    if (!crmBooksyIsActiveRowV477(row)) return;

    const category = String(row[0] || "").trim();
    const name = String(row[1] || "").trim();
    if (!category || !name) return;

    const id = String(row[11] || "").trim() || crmBooksyAdminIdV477(category, name);
    const sheetRow = index + 2;

    if (!categoryOrderFallback[category]) {
      categoryOrderFallback[category] = Number(row[12]) || nextCategoryOrder++;
    }
    categoryServiceCount[category] = (categoryServiceCount[category] || 0) + 1;

    if (!activeRowsById[id]) activeRowsById[id] = [];
    activeRowsById[id].push(sheetRow);

    const item = {
      adminId:id,
      category:category,
      name:name,
      price:row[2] === "" ? "" : (Number(row[2]) || 0),
      duration:Math.max(0, Number(row[3]) || 0),
      categoryOrder:Number(row[12]) || categoryOrderFallback[category],
      serviceOrder:Number(row[13]) || categoryServiceCount[category],
      icon:String(row[14] || "universal").trim() || "universal",
      color:String(row[15] || "#b05c75").trim() || "#b05c75",
      iconClientVisible:String(row[16] || "").trim().toLowerCase() === "false" ? false : true,
      source:String(row[7] || ""),
      sheetRow:sheetRow
    };

    if (!byId[id]) {
      byId[id] = item;
    } else {
      const current = byId[id];
      const currentRow = values[current.sheetRow - 2] || [];
      const itemHasAdminMeta = Boolean(row[11] || row[12] || row[13] || row[14] || row[15] || row[16]);
      const currentHasAdminMeta = Boolean(currentRow[11] || currentRow[12] || currentRow[13] || currentRow[14] || currentRow[15] || currentRow[16]);
      if (itemHasAdminMeta && !currentHasAdminMeta) byId[id] = item;
    }
  });

  const items = Object.keys(byId).map(function(id){ return byId[id]; });
  items.sort(function(a,b){
    return (a.categoryOrder-b.categoryOrder) ||
           (a.serviceOrder-b.serviceOrder) ||
           a.name.localeCompare(b.name);
  });

  return { sheet:sheet, items:items, rows:values, activeRowsById:activeRowsById };
}

