function saveBooksyPricesAdminV478(ss, postData) {
  try {
    const desiredRaw = Array.isArray(postData.prices) ? postData.prices : [];
    if (desiredRaw.length > 500) {
      return createJsonResponse({ success:false, error:"Za dużo pozycji Cennika Booksy." });
    }

    const desired = [];
    const seen = {};
    desiredRaw.forEach(function(raw, index){
      const category = String(raw.category || "").trim();
      const name = String(raw.name || "").trim();
      if (!category || !name) return;

      const adminId = String(raw.adminId || "").trim() ||
        crmBooksyAdminIdV477(category, name);

      if (seen[adminId]) throw new Error("Duplikat AdminId: " + adminId);
      seen[adminId] = true;

      desired.push({
        adminId:adminId,
        category:category,
        name:name,
        price:raw.price === "" ? "" : (Number(raw.price) || 0),
        duration:Math.max(0, Number(raw.duration) || 0),
        categoryOrder:Math.max(1, Number(raw.categoryOrder) || 1),
        serviceOrder:Math.max(1, Number(raw.serviceOrder) || (index + 1)),
        icon:String(raw.icon || "universal").trim() || "universal",
        color:String(raw.color || "#b05c75").trim() || "#b05c75",
        iconClientVisible:raw.iconClientVisible === false ? false : true
      });
    });

    const current = crmBooksyReadActiveV477(ss);
    const sheet = current.sheet;
    const currentById = {};
    current.items.forEach(function(item){ currentById[item.adminId] = item; });
    const desiredById = {};
    desired.forEach(function(item){ desiredById[item.adminId] = item; });

    let archived = 0;
    let appended = 0;
    let orderUpdated = 0;

    Object.keys(currentById).forEach(function(id){
      if (!desiredById[id]) {
        archived += crmBooksyArchiveRowsV477(
          sheet, current.activeRowsById[id] || [],
          "Usunięto w edytorze Booksy " + crmBooksyDateOnlyV477(new Date())
        );
      }
    });

    desired.forEach(function(item){
      const old = currentById[item.adminId];

      if (!old) {
        crmBooksyAppendActiveV477(sheet, item, "Dodano w edytorze Booksy");
        appended++;
        return;
      }

      const changed =
        crmBooksyNormV477(old.category) !== crmBooksyNormV477(item.category) ||
        String(old.name || "") !== String(item.name || "") ||
        String(old.price === "" ? "" : Number(old.price)) !== String(item.price === "" ? "" : Number(item.price)) ||
        Number(old.duration || 0) !== Number(item.duration || 0);

      if (changed) {
        archived += crmBooksyArchiveRowsV477(
          sheet, current.activeRowsById[item.adminId] || [],
          "Zmieniono w edytorze Booksy " + crmBooksyDateOnlyV477(new Date())
        );
        crmBooksyAppendActiveV477(sheet, item, "Nowa wersja po edycji w CRM");
        appended++;
        return;
      }

      (current.activeRowsById[item.adminId] || []).forEach(function(rowNo){
        sheet.getRange(rowNo, 12, 1, 6).setValues([[
          item.adminId,
          item.categoryOrder,
          item.serviceOrder,
          item.icon,
          item.color,
          item.iconClientVisible === false ? "false" : "true"
        ]]);
        orderUpdated++;
      });
    });

    const refreshed = crmBooksyReadActiveV477(ss);
    return createJsonResponse({
      success:true,
      sheet:TEST_BOOKSY_PRICE_SHEET,
      activeCount:refreshed.items.length,
      archived:archived,
      appended:appended,
      orderUpdated:orderUpdated
    });
  } catch (error) {
    return createJsonResponse({ success:false, error:error.toString() });
  }
}
