function parseTimeToMinutes(value, fallback) {
  const text = (value || fallback || "00:00").toString();
  const parts = text.split(":");
  if (parts.length !== 2) return 0;
  return (parseInt(parts[0], 10) || 0) * 60 + (parseInt(parts[1], 10) || 0);
}

/**
 * Rozpoznaje techniczne, informacyjne wydarzenie grafiku Oleksandra.
 * Takie wydarzenie ma być widoczne w ADMIN, ale nie może blokować
 * ręcznego dodawania wizyty przez mistrzynię.
 */
function isInformationalWorkScheduleEvent(event) {
  if (!event) return false;

  /* PUNKT 4 PLANU: nazwa „Brak/BRAK” sama w sobie nie jest dowodem,
     że wydarzenie należy do grafiku Oleksandra. Chronimy prywatne i
     zewnętrzne eventy Google Calendar. Jedynym źródłem prawdy jest
     techniczny marker utworzony przez synchronizację grafiku. */
  const description = (event.getDescription() || "").toString();
  return description.indexOf(WORK_SCHEDULE_CALENDAR_MARKER) === 0;
}

function validateBookingCandidate(ss, settings, candidate) {
  const start = candidate.start;
  const duration = Math.max(1, parseInt(candidate.duration, 10) || 45);
  const source = (candidate.source || "INDEX").toString().toUpperCase();
  const isAdmin = source === "ADMIN" || source === "FORM_FIRST";
  const configuredCleanup = Math.max(0, parseInt(settings.cleanup_buffer_minutes, 10) || 0);
  const cleanup = isAdmin ? 0 : configuredCleanup;
  const end = new Date(start.getTime() + duration * 60000);
  const occupiedEnd = new Date(end.getTime() + cleanup * 60000);

  if (!start || isNaN(start.getTime())) {
    return { success: false, code: "INVALID_DATE", error: "Nieprawidłowa data wizyty" };
  }

  const dayStart = new Date(start);
  dayStart.setHours(0, 0, 0, 0);
  const workStartMinutes = parseTimeToMinutes(settings.work_start_hour, "09:00");
  const workEndMinutes = parseTimeToMinutes(settings.work_end_hour, "18:00");
  const candidateStartMinutes = start.getHours() * 60 + start.getMinutes();
  const candidateEndMinutes = end.getHours() * 60 + end.getMinutes();

  if (!isAdmin && (candidateStartMinutes < workStartMinutes || candidateEndMinutes > workEndMinutes)) {
    return {
      success: false,
      code: "OUTSIDE_WORK_HOURS",
      error: "Termin znajduje się poza godzinami pracy " + settings.work_start_hour + "–" + settings.work_end_hour
    };
  }

  const interval = isAdmin ? 5 : Math.max(5, parseInt(settings.slot_interval_minutes, 10) || 15);
  const offset = isAdmin ? 0 : Math.max(0, parseInt(settings.start_offset_minutes, 10) || 0);
  const firstSlotMinutes = isAdmin ? 0 : workStartMinutes + offset;
  if (candidateStartMinutes < firstSlotMinutes || (candidateStartMinutes - firstSlotMinutes) % interval !== 0) {
    return {
      success: false,
      code: "INVALID_SLOT",
      error: "Godzina rozpoczęcia nie pasuje do ustawionych slotów co " + interval + " min"
    };
  }

  const excludeEventId = (candidate.excludeEventId || "").toString().trim();
  const bookingsSheet = ss.getSheetByName(SHEET_BOOKINGS);
  const knownSheetEventIds = new Set();

  if (bookingsSheet && bookingsSheet.getLastRow() > 1) {
    const columnCount = Math.max(8, bookingsSheet.getLastColumn());
    const rows = bookingsSheet.getRange(2, 1, bookingsSheet.getLastRow() - 1, columnCount).getValues();
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const rowStart = row[0] instanceof Date ? row[0] : new Date(row[0]);
      if (!rowStart || isNaN(rowStart.getTime())) continue;
      const rowEventId = row[6] ? row[6].toString().trim() : "";
      if (rowEventId) knownSheetEventIds.add(rowEventId);
      if (excludeEventId && rowEventId === excludeEventId) continue;
      const rowDuration = parseInt(row[7], 10) || settings.slot_interval_minutes || 45;
      const rowCleanup = isAdmin ? 0 : configuredCleanup;
      const rowEndWithCleanup = new Date(rowStart.getTime() + (rowDuration + rowCleanup) * 60000);
      if (start < rowEndWithCleanup && occupiedEnd > rowStart) {
        return {
          success: false,
          code: "TIME_CONFLICT",
          error: isAdmin
            ? "Wybrany termin koliduje z istniejącą wizytą"
            : "Wybrany termin koliduje z istniejącą wizytą lub jej buforem sprzątania"
        };
      }
    }
  }

  const calendar = CalendarApp.getCalendarById(settings.calendar_id || "");
  if (calendar) {
    const searchStart = new Date(start.getTime() - 24 * 60 * 60 * 1000);
    const searchEnd = new Date(occupiedEnd.getTime() + 24 * 60 * 60 * 1000);
    const events = calendar.getEvents(searchStart, searchEnd);
    for (let i = 0; i < events.length; i++) {
      const event = events[i];
      const eventId = event.getId();
      if (excludeEventId && eventId === excludeEventId) continue;
      if (knownSheetEventIds.has(eventId)) continue;

      // Brak/BRAK to wyłącznie informacyjny wpis grafiku.
      // Nie blokuje ręcznej wizyty ADMIN i nie jest traktowany jak prywatne wydarzenie.
      if (isInformationalWorkScheduleEvent(event)) continue;

      const eventStart = event.getStartTime();
      const eventEnd = event.getEndTime();
      if (start < eventEnd && occupiedEnd > eventStart) {
        return {
          success: false,
          code: "TIME_CONFLICT",
          error: "Wybrany termin koliduje z blokadą lub wydarzeniem w Google Calendar"
        };
      }
    }
  }

  return { success: true, start: start, end: end, occupiedEnd: occupiedEnd };
}

