function crmV4746BooksyServiceForDate(ss, serviceName, visitDate) {
  const wanted = crmV4737Fold(serviceName);
  if (!wanted) return null;
  const sh = ss.getSheetByName(TEST_BOOKSY_PRICE_SHEET);
  if (!sh || sh.getLastRow() < 2) return null;
  const width = Math.max(17, sh.getLastColumn());
  const rows = sh.getRange(2, 1, sh.getLastRow() - 1, width).getValues();
  const tz = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
  const dateKey = Utilities.formatDate(visitDate, tz, "yyyy-MM-dd");
  const dateOnly = function(value) {
    if (!value) return "";
    if (value instanceof Date && !isNaN(value.getTime())) return Utilities.formatDate(value, tz, "yyyy-MM-dd");
    const text = String(value || "").trim();
    const m = text.match(/^(\d{4}-\d{2}-\d{2})/);
    return m ? m[1] : "";
  };
  const candidates = [];
  rows.forEach(function(row, index) {
    const name = String(row[1] || "").trim();
    if (crmV4737Fold(name) !== wanted) return;
    const status = String(row[6] || "").trim().toUpperCase();
    if (status === "WYKRYTA_Z_MAILA") return;
    const priceRaw = row[2];
    if (priceRaw === "" || priceRaw === null || priceRaw === undefined || isNaN(Number(priceRaw))) return;
    candidates.push({
      row:index + 2,
      category:String(row[0] || "").trim(),
      name:name,
      price:Number(priceRaw) || 0,
      duration:Math.max(0, Number(row[3]) || 0),
      from:dateOnly(row[4]),
      to:dateOnly(row[5]),
      status:status,
      source:String(row[7] || "").trim()
    });
  });
  const historical = candidates.filter(function(item) {
    return (!item.from || item.from <= dateKey) && (!item.to || item.to >= dateKey);
  }).sort(function(a, b) {
    return String(b.from || "0000-00-00").localeCompare(String(a.from || "0000-00-00"));
  });
  if (historical.length) return Object.assign({priceSource:"CENNIK_BOOKSY_HIST"}, historical[0]);
  const active = candidates.filter(function(item) {
    return !item.status || item.status === "AKTYWNY";
  }).sort(function(a, b) { return b.row - a.row; });
  if (active.length) return Object.assign({priceSource:"CENNIK_BOOKSY"}, active[0]);
  return null;
}

