function crmV4746FamilyScheduleMapReadOnly(ss) {
  const cache = crmV4738RuntimeCache(ss);
  if (cache.familyScheduleMapV4746) return cache.familyScheduleMapV4746;
  const map = {};
  const sh = ss.getSheetByName(SHEET_FAMILY_SCHEDULE);
  if (sh && sh.getLastRow() > 1) {
    const rows = sh.getRange(2, 1, sh.getLastRow() - 1, Math.min(18, Math.max(16, sh.getLastColumn()))).getValues();
    const tz = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
    rows.forEach(function(row) {
      if (String(row[15] || "TAK").trim().toUpperCase() === "NIE") return;
      const date = row[0] instanceof Date ? row[0] : new Date(row[0]);
      if (!date || isNaN(date.getTime())) return;
      const key = Utilities.formatDate(date, tz, "yyyy-MM-dd");
      map[key] = legacyShiftToCode(row[2] || row[1] || "W");
    });
  }
  cache.familyScheduleMapV4746 = map;
  return map;
}

function crmV4746FamilyStateForDate(ss, date) {
  const tz = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
  const map = crmV4746FamilyScheduleMapReadOnly(ss);
  const keyFor = function(delta) {
    const d = new Date(date);
    d.setDate(d.getDate() + delta);
    return Utilities.formatDate(d, tz, "yyyy-MM-dd");
  };
  const current = map[keyFor(0)] || "W";
  const previous = map[keyFor(-1)] || "W";
  const beforePrevious = map[keyFor(-2)] || "W";
  if (current === "1") return {state:"DAY_SHIFT", label:"zmiana dzienna", capEnd:"16:30"};
  if (current === "2" && previous === "2") return {state:"SECOND_NIGHT", label:"druga nocna", capEnd:"16:30"};
  if (current === "2") return {state:"FIRST_NIGHT", label:"pierwsza nocna", capEnd:""};
  if (current !== "2" && previous === "2" && beforePrevious === "2") return {state:"AFTER_LAST_NIGHT", label:"dzień po ostatniej nocnej", capEnd:""};
  return {state:"HOME_OR_OFF", label:"Oleksandr w domu / wolne", capEnd:""};
}

function crmV4746AutoPostLastMinutes(ss, lastVisit, configuredMinutes) {
  const configured = Math.max(0, Number(configuredMinutes) || 0);
  const family = crmV4746FamilyStateForDate(ss, lastVisit.start);
  if (!family.capEnd) return {minutes:configured, family:family, adjusted:false};
  const tz = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
  const parts = Utilities.formatDate(lastVisit.end, tz, "HH:mm").split(":").map(Number);
  const endMinutes = (parts[0] || 0) * 60 + (parts[1] || 0);
  const capParts = family.capEnd.split(":").map(Number);
  const capMinutes = (capParts[0] || 0) * 60 + (capParts[1] || 0);
  const available = Math.max(0, capMinutes - endMinutes);
  const minutes = Math.min(configured, available);
  return {minutes:minutes, family:family, adjusted:minutes !== configured};
}
