if (postData.action === "blockTime") {

  const settings =
    getDynamicSettings(
      ss
    );

  const calendar =
    CalendarApp.getCalendarById(
      settings.calendar_id || ""
    );

  if (!calendar) {
    return createJsonResponse({
      success: false,
      error: "Nie znaleziono kalendarza"
    });
  }

  const blockType =
    postData.blockType || "hours";

  const dateString =
    postData.date || "";

  const startTime =
    postData.startTime || "09:00";

  const endTime =
    postData.endTime || "18:00";

  const title =
    postData.title || "Zablokowane";

  if (!dateString) {
    return createJsonResponse({
      success: false,
      error: "Brak daty blokady"
    });
  }

  const parts =
    dateString.split("-");

  if (parts.length !== 3) {
    return createJsonResponse({
      success: false,
      error: "Nieprawidłowa data blokady"
    });
  }

  const year =
    parseInt(
      parts[0],
      10
    );

  const month =
    parseInt(
      parts[1],
      10
    ) - 1;

  const day =
    parseInt(
      parts[2],
      10
    );

  let startDate;
  let endDate;

  if (
    blockType === "full_day"
  ) {

    startDate =
      new Date(
        year,
        month,
        day,
        0,
        0,
        0
      );

    endDate =
      new Date(
        year,
        month,
        day + 1,
        0,
        0,
        0
      );

  } else {

    const startParts =
      startTime.split(":");

    const endParts =
      endTime.split(":");

    if (
      startParts.length !== 2 ||
      endParts.length !== 2
    ) {
      return createJsonResponse({
        success: false,
        error: "Nieprawidłowe godziny blokady"
      });
    }

    startDate =
      new Date(
        year,
        month,
        day,
        parseInt(
          startParts[0],
          10
        ),
        parseInt(
          startParts[1],
          10
        ),
        0
      );

    endDate =
      new Date(
        year,
        month,
        day,
        parseInt(
          endParts[0],
          10
        ),
        parseInt(
          endParts[1],
          10
        ),
        0
      );

    if (
      !startDate ||
      !endDate ||
      isNaN(
        startDate.getTime()
      ) ||
      isNaN(
        endDate.getTime()
      ) ||
      endDate.getTime() <= startDate.getTime()
    ) {
      return createJsonResponse({
        success: false,
        error: "Godzina zakończenia musi być późniejsza niż rozpoczęcia"
      });
    }

  }

  const description =
    "CRM_BLOCK_TIME\nBlokada czasu dodana z CRM";

  const event =
    calendar.createEvent(
      title,
      startDate,
      endDate,
      {
        description:
        description
      }
    );

  const createdEventId = event ? event.getId() : "";

  if (createdEventId) {
    try {
      CacheService.getScriptCache().put(
        "CRM_BLOCK_EVENT_V20_" + createdEventId,
        "1",
        21600
      );
    } catch (cacheError) {}
  }

  return createJsonResponse({
    success: true,
    eventId: createdEventId
  });

}
