  const startDate = new Date(dateString + "T" + startTime + ":00");
  const endDate = new Date(dateString + "T" + endTime + ":00");
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime()) || endDate <= startDate) return createJsonResponse({success:false,error:"Nieprawidłowy zakres blokady"});

  event.setTitle(title);
  event.setTime(startDate, endDate);
  event.setDescription("CRM_BLOCK_TIME|Blokada czasu dodana z CRM");

  const updatedEventId = event.getId();

  try {
