// USUWANIE BLOKADY CZASU: EVENT ID LUB DOKLADNY FALLBACK
if (postData.action === "deleteBlockTime") {
  const settings = getDynamicSettings(ss);
  const calendar = CalendarApp.getCalendarById(settings.calendar_id || "");
  if (!calendar) return createJsonResponse({success:false,error:"Nie znaleziono kalendarza"});
  const eventId = postData.eventId ? postData.eventId.toString().trim() : "";
  const title = postData.title ? postData.title.toString().trim() : "";
  const start = postData.start ? new Date(postData.start) : null;
  const end = postData.end ? new Date(postData.end) : null;
  const blockCache = CacheService.getScriptCache();

  function isBlock(ev, id) {
    const cacheKey = id ? "CRM_BLOCK_EVENT_V20_" + id : "";

    if (cacheKey && blockCache.get(cacheKey)) {
      return true;
    }

    const d = ev.getDescription() || "";
    const ok =
      d.indexOf("CRM_BLOCK_TIME") !== -1 ||
      d.indexOf("Blokada czasu dodana z CRM") !== -1;

    if (ok && cacheKey) {
      try { blockCache.put(cacheKey, "1", 21600); } catch (cacheError) {}
    }

    return ok;
  }

  if (eventId) {
    try {
      const ev = calendar.getEventById(eventId);

      if (ev) {
        if (!isBlock(ev, eventId)) {
          return createJsonResponse({
            success:false,
            error:"Event ID nie należy do blokady CRM"
          });
        }

        ev.deleteEvent();

        try {
          blockCache.remove("CRM_BLOCK_EVENT_V20_" + eventId);
        } catch (cacheError) {}

        return createJsonResponse({
          success:true,
          deletedBy:"eventId",
          eventId:eventId
        });
      }
    } catch(err) {
      Logger.log(err.toString());
    }
  }
  if (!start || !end || isNaN(start.getTime()) || isNaN(end.getTime())) return createJsonResponse({success:false,error:"Brak poprawnego zakresu fallback"});
  const matches=calendar.getEvents(new Date(start.getTime()-60000),new Date(end.getTime()+60000)).filter(ev =>
    isBlock(ev, ev.getId()) && (!title || ev.getTitle().trim()===title) && Math.abs(ev.getStartTime().getTime()-start.getTime())<60000 && Math.abs(ev.getEndTime().getTime()-end.getTime())<60000
  );
  if (matches.length !== 1) return createJsonResponse({success:false,error:matches.length?"Znaleziono kilka blokad. Usuwanie przerwano":"Nie znaleziono dokładnie pasującej blokady"});
  const deletedId=matches[0].getId(); matches[0].deleteEvent();
  return createJsonResponse({success:true,deletedBy:"exactFallback",eventId:deletedId});
}

