if (postData.action === "deleteExternalCalendarEvent") {
  const eventId = String(postData.eventId || "").trim();
  if (!eventId) {
    return createJsonResponse({
      success: false,
      error: "Brak Event ID"
    });
  }

  const lock = LockService.getScriptLock();
  if (!lock.tryLock(5000)) {
    return createJsonResponse({
      success: false,
      error: "Inna operacja Kalendarza jest w toku"
    });
  }

  try {
    // 1. Event zapisany w arkuszu Wizyty NIE jest wydarzeniem external.
    const bookingsSheet = ss.getSheetByName(SHEET_BOOKINGS);
    if (bookingsSheet && bookingsSheet.getLastRow() > 1) {
      const ids = bookingsSheet
        .getRange(2, 7, bookingsSheet.getLastRow() - 1, 1)
        .getDisplayValues();

      const belongsToCRM = ids.some(function(row) {
        return String(row[0] || "").trim() === eventId;
      });

      if (belongsToCRM) {
        return createJsonResponse({
          success: false,
          protected: true,
          error: "To wydarzenie należy do wizyty CRM i nie może być usunięte jako external"
        });
      }
    }

    const settings = getDynamicSettings(ss);
    const calendar = CalendarApp.getCalendarById(settings.calendar_id || "");
    if (!calendar) {
      return createJsonResponse({
        success: false,
        error: "Nie znaleziono kalendarza"
      });
    }

    let event = null;
    try {
      event = calendar.getEventById(eventId);
    } catch (lookupError) {
      const lookupText = String(lookupError || "");
      if (/nie istnieje|nie znaleziono|does not exist|not found|deleted/i.test(lookupText)) {
        return createJsonResponse({
          success: true,
          alreadyMissing: true,
          eventId: eventId
        });
      }
      throw lookupError;
    }

    if (!event) {
      return createJsonResponse({
        success: true,
        alreadyMissing: true,
        eventId: eventId
      });
    }

    const description = String(event.getDescription() || "");

    // 2. Grafik pracy jest tylko informacyjny i ma osobny mechanizm zarządzania.
    if (description.indexOf(WORK_SCHEDULE_CALENDAR_MARKER) === 0) {
      return createJsonResponse({
        success: false,
        protected: true,
        error: "Wydarzenie grafiku CRM_WORK_SHIFT jest chronione"
      });
    }

    // 3. Blokady CRM mają własny bezpieczny przepływ deleteBlockTime.
    const isCRMBlock =
      description.indexOf("CRM_BLOCK_TIME") !== -1 ||
      description.indexOf("Blokada czasu dodana z CRM") !== -1;

    if (isCRMBlock) {
      return createJsonResponse({
        success: false,
        protected: true,
        error: "To wydarzenie jest blokadą CRM i musi być usunięte przez funkcję blokady"
      });
    }

    // 4. Bez wyboru zakresu nie kasujemy serii wydarzeń cyklicznych.
    if (typeof event.isRecurringEvent === "function" && event.isRecurringEvent()) {
      return createJsonResponse({
        success: false,
        protected: true,
        recurring: true,
        error: "Wydarzenie cykliczne usuń bezpośrednio w Google Calendar"
      });
    }

    const title = String(event.getTitle() || "");
    event.deleteEvent();

    return createJsonResponse({
      success: true,
      deleted: true,
      alreadyMissing: false,
      eventId: eventId,
      title: title
    });
  } catch (error) {
    return createJsonResponse({
      success: false,
      error: error.toString()
    });
  } finally {
    lock.releaseLock();
  }
}
