    postData.client || {};

  const oldPhone =
    postData.oldPhone
      ? postData.oldPhone.toString().trim()
      : "";

  const newPhone =
    client.phone
      ? client.phone.toString().trim()
      : "";

  const name =
    client.name
      ? client.name.toString().trim()
      : "";

  if (!newPhone || !name) {
    return createJsonResponse({
      success: false,
      error: "Brak telefonu lub imienia klienta"
    });
  }

  const visits =
    parseInt(
      client.visits,
      10
    ) || 0;

  const cancelled =
    parseInt(
      client.cancelled,
      10
    ) || 0;

  const lastVisit =
    client.lastVisit
      ? new Date(client.lastVisit)
      : "";

  let foundRow =
    -1;

  if (sheet.getLastRow() > 1) {

    const values =
      sheet
        .getRange(
          2,
          1,
          sheet.getLastRow() - 1,
          5
        )
        .getValues();

    for (
      let i = 0;
      i < values.length;
      i++
    ) {

      const rowPhone =
        values[i][0]
          ? values[i][0].toString().trim()
          : "";

      if (
        (oldPhone && rowPhone === oldPhone) ||
        rowPhone === newPhone
      ) {
        foundRow =
          i + 2;
        break;
      }

    }

  }

  if (foundRow !== -1) {

    sheet
      .getRange(
        foundRow,
        1,
        1,
        5
      )
      .setValues([[
        newPhone,
        name,
        visits,
        cancelled,
        lastVisit
      ]]);

  } else {

