function updateOrInsertSetting(sheet, key, val) {
  const lastRow = sheet.getLastRow();
  let foundIndex = -1;
  if (lastRow > 1) {
    const range = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (let i = 0; i < range.length; i++) {
      if (range[i][0] && range[i][0].toString().trim() === key) { foundIndex = i + 2; break; }
    }
  }
  if (foundIndex !== -1) sheet.getRange(foundIndex, 2).setValue(val);
  else sheet.appendRow([key, val, "Zapisane przez system"]);
}

function deleteSettingKey(sheet, key) {
  const lastRow = sheet.getLastRow();
  if (lastRow > 1) {
    const range = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (let i = range.length - 1; i >= 0; i--) {
      if (range[i][0] && range[i][0].toString().trim() === key) {
        sheet.deleteRow(i + 2);
      }
    }
  }
}
