function normalizeCRMPhone(value) {
  const raw = (value || "").toString().trim();

  // Identyfikatory diagnostyczne muszą pozostać niezmienione,
  // aby tester mógł znaleźć i posprzątać utworzone dane.
  if (/^TEST-/i.test(raw)) {
    return raw.toUpperCase();
  }

  // Zwykłe numery klientów porównujemy bez spacji, myślników i nawiasów.
  return raw.replace(/[^0-9+]/g, "");
}

function ensureCustomerSheet(ss) {
  let sheet = ss.getSheetByName(SHEET_CUSTOMERS);
  let created = false;

  if (!sheet) {
    sheet = ss.insertSheet(SHEET_CUSTOMERS);
    created = true;
  }

  const headers = [
    "Telefon", "Imię i Nazwisko", "Wizyty", "Odwołane", "Ostatnia wizyta",
    "Data dodania", "Źródło pozyskania", "Klucz źródłowy", "Tryb rezerwacji"
  ];

  if (created || sheet.getLastRow() === 0 || sheet.getLastColumn() < headers.length) {
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
  }

  return sheet;
}

function synchronizeCustomerStatistics(ss, onlyPhone) {
  const customerSheet = ensureCustomerSheet(ss);
  const targetPhone = normalizeCRMPhone(onlyPhone || "");

  /*
   * PERFORMANCE V20:
   * najczęstszy przypadek po create/edit/cancel dotyczy jednej osoby.
   * Nie przeliczamy wtedy całej tabeli Klienci i nie formatujemy jej ponownie.
   */
  if (targetPhone) {
    const bookingsSheet = ss.getSheetByName(SHEET_BOOKINGS);
    let visits = 0;
    let lastVisit = null;
    let discoveredName = "";

    if (bookingsSheet && bookingsSheet.getLastRow() > 1) {
      const width = Math.max(4, Math.min(16, bookingsSheet.getLastColumn()));
      const rows = bookingsSheet
        .getRange(2, 1, bookingsSheet.getLastRow() - 1, width)
        .getValues();

      rows.forEach(row => {
        const rawPhone = (row[1] || "").toString().trim();
        if (rawPhone === "Google Calendar") return;

        const phone = normalizeCRMPhone(rawPhone);
        if (phone !== targetPhone) return;

        visits += 1;

        const bookingDate =
          row[0] instanceof Date ? row[0] : (row[0] ? new Date(row[0]) : null);

        if (bookingDate && !isNaN(bookingDate.getTime())) {
          if (!lastVisit || bookingDate.getTime() > lastVisit.getTime()) {
            lastVisit = bookingDate;
          }
        }

        if (!discoveredName && row[2]) {
          discoveredName = row[2].toString().trim();
        }
      });
    }

    let foundRow = -1;
    let existing = null;

    if (customerSheet.getLastRow() > 1) {
      const rows = customerSheet
        .getRange(2, 1, customerSheet.getLastRow() - 1, 7)
        .getValues();

      for (let i = 0; i < rows.length; i++) {
        if (normalizeCRMPhone(rows[i][0]) === targetPhone) {
          foundRow = i + 2;
          existing = rows[i];
          break;
        }
      }
    }

    if (foundRow !== -1) {
      const cancelledRaw = existing[3];
      const cancelled =
        typeof cancelledRaw === "number" && !(cancelledRaw instanceof Date)
          ? Math.max(0, Math.trunc(cancelledRaw))
          : 0;

      customerSheet
        .getRange(foundRow, 1, 1, 5)
        .setValues([[
          targetPhone,
          existing[1] || discoveredName || "Klient",
          visits,
          cancelled,
          lastVisit || ""
        ]]);
    } else if (visits > 0) {
      customerSheet.appendRow([
        targetPhone,
        discoveredName || "Klient",
        visits,
        0,
        lastVisit || "",
        new Date(),
        "UTWORZONY_Z_HISTORII_WIZYT",
        "",
        "WYMAGA_POTWIERDZENIA"
      ]);
    }

    return customerSheet;
  }

  /*
   * Pełna synchronizacja pozostaje dla narzędzi administracyjnych,
   * migracji i diagnostyki. Nie jest już wykonywana po zwykłej operacji
   * jednej klientki.
   */
  const stats = {};
  const bookingsSheet = ss.getSheetByName(SHEET_BOOKINGS);

  if (bookingsSheet && bookingsSheet.getLastRow() > 1) {
    const columnCount = Math.max(8, bookingsSheet.getLastColumn());
    const rows = bookingsSheet.getRange(
      2, 1, bookingsSheet.getLastRow() - 1, columnCount
    ).getValues();

    rows.forEach(row => {
      const rawPhone = (row[1] || "").toString().trim();
      if (rawPhone === "Google Calendar") return;

      const phone = normalizeCRMPhone(rawPhone);
      if (!phone) return;

      const bookingDate =
        row[0] instanceof Date ? row[0] : new Date(row[0]);

      if (!stats[phone]) {
        stats[phone] = {
          visits: 0,
          lastVisit: null,
          name: row[2] ? row[2].toString().trim() : ""
        };
      }

      stats[phone].visits += 1;

      if (bookingDate && !isNaN(bookingDate.getTime())) {
        if (
          !stats[phone].lastVisit ||
          bookingDate.getTime() > stats[phone].lastVisit.getTime()
        ) {
          stats[phone].lastVisit = bookingDate;
        }
      }

      if (!stats[phone].name && row[2]) {
        stats[phone].name = row[2].toString().trim();
      }
    });
  }

  let customerRows = [];
  if (customerSheet.getLastRow() > 1) {
    customerRows = customerSheet
      .getRange(2, 1, customerSheet.getLastRow() - 1, 7)
      .getValues();
  }

  const existingByPhone = {};
  customerRows.forEach((row, index) => {
    const phone = normalizeCRMPhone(row[0]);
    if (phone) existingByPhone[phone] = { row: index + 2, values: row };
  });

  Object.keys(existingByPhone).forEach(phone => {
    const ref = existingByPhone[phone];
    const item = stats[phone] || { visits: 0, lastVisit: null };
    const cancelledRaw = ref.values[3];
    const cancelled =
      typeof cancelledRaw === "number" && !(cancelledRaw instanceof Date)
        ? Math.max(0, Math.trunc(cancelledRaw))
        : 0;

    customerSheet
      .getRange(ref.row, 1, 1, 5)
      .setValues([[
        phone,
        ref.values[1] || (stats[phone] ? stats[phone].name : "") || "Klient",
        item.visits,
        cancelled,
        item.lastVisit || ""
      ]]);
  });

  Object.keys(stats).forEach(phone => {
    if (existingByPhone[phone]) return;

    customerSheet.appendRow([
      phone,
      stats[phone].name || "Klient",
      stats[phone].visits,
      0,
      stats[phone].lastVisit || "",
      new Date(),
      "UTWORZONY_Z_HISTORII_WIZYT",
      "",
      "WYMAGA_POTWIERDZENIA"
    ]);
  });

  /*
   * Sprzątanie tylko osieroconych danych diagnostycznych,
   * jak w poprzedniej wersji.
   */
  if (customerSheet.getLastRow() > 1) {
    const rows = customerSheet
      .getRange(2, 1, customerSheet.getLastRow() - 1, 5)
      .getValues();

    for (let index = rows.length - 1; index >= 0; index--) {
      const rowPhone = normalizeCRMPhone(rows[index][0]);
      const rowName = (rows[index][1] || "").toString();
      const isDiagnostic =
        /^TEST-/i.test(rowPhone) ||
        /^CRM_TEST_/i.test(rowName);

      if (isDiagnostic && !stats[rowPhone]) {
        customerSheet.deleteRow(index + 2);
      }
    }
  }

  return customerSheet;
}

function getClientsData() {
  const ss = getSpreadsheet();
  const sheet = synchronizeCustomerStatistics(ss);
  if (!sheet || sheet.getLastRow() < 2) return [];

  const values = sheet.getRange(2, 1, sheet.getLastRow() - 1, 5).getValues();
  const timeZone = ss.getSpreadsheetTimeZone();

  return values.map(row => {
    const visits = typeof row[2] === "number" && !(row[2] instanceof Date)
      ? Math.max(0, Math.trunc(row[2]))
      : 0;
    const cancelled = typeof row[3] === "number" && !(row[3] instanceof Date)
      ? Math.max(0, Math.trunc(row[3]))
      : 0;
    const lastVisitDate = row[4] instanceof Date ? row[4] : (row[4] ? new Date(row[4]) : null);

    return {
      phone: normalizeCRMPhone(row[0]),
      name: row[1] || "",
      visits: visits,
      cancelled: cancelled,
      lastVisit: lastVisitDate && !isNaN(lastVisitDate.getTime())
        ? Utilities.formatDate(lastVisitDate, timeZone, "yyyy-MM-dd HH:mm")
        : ""
    };
  });
}
