function findBookingRowByEventId(sheet, eventId) {
  if (!sheet || !eventId || sheet.getLastRow() < 2) return -1;
  const values = sheet.getRange(2, 1, sheet.getLastRow() - 1, Math.max(12, sheet.getLastColumn())).getValues();
  for (let i = 0; i < values.length; i++) {
    if ((values[i][6] || "").toString().trim() === eventId.toString().trim()) return i + 2;
  }
  return -1;
}

function findBookingRowForLifecycle(sheet, postData) {
  if (!sheet || sheet.getLastRow() < 2) return -1;

  const eventId = (postData.eventId || "").toString().trim();
  const byEventId = findBookingRowByEventId(sheet, eventId);
  if (byEventId !== -1) return byEventId;

  const oldDate = postData.oldDate ? new Date(postData.oldDate) : null;
  const wantedPhone = normalizeCRMPhone(postData.phone || "");
  const wantedName = (postData.clientName || "").toString().trim().toLowerCase();
  const wantedService = (postData.service || "").toString().trim().toLowerCase();
  const values = sheet.getRange(2, 1, sheet.getLastRow() - 1, Math.max(12, sheet.getLastColumn())).getValues();

  for (let i = 0; i < values.length; i++) {
    const row = values[i];
    const rowDate = row[0] instanceof Date ? row[0] : new Date(row[0]);
    if (!rowDate || isNaN(rowDate.getTime())) continue;

    const dateMatches = oldDate && !isNaN(oldDate.getTime())
      ? Math.abs(rowDate.getTime() - oldDate.getTime()) < 60000
      : false;
    if (!dateMatches) continue;

    const rowPhone = normalizeCRMPhone(row[1] || "");
    const rowName = (row[2] || "").toString().trim().toLowerCase();
    const rowService = (row[3] || "").toString().trim().toLowerCase();
    const identityMatches =
      (wantedPhone && rowPhone === wantedPhone) ||
      (wantedName && rowName === wantedName && (!wantedService || rowService === wantedService));

    if (identityMatches) return i + 2;
  }

  return -1;
}

function appendVisitHistory(ss, data) {
  const sheet = getOrCreateSheetWithHeaders(ss, SHEET_VISIT_HISTORY, [
    "ID operacji", "Data operacji", "ID wizyty", "Event ID", "Telefon", "Klient",
    "Usługa", "Operacja", "Status przed", "Status po", "Stary termin", "Nowy termin",
    "Inicjator", "Powód", "Różnica dni", "Przeniesienie później", "Przeniesienie i anulowanie"
  ]);
  sheet.appendRow([
    makeCRMId("OPERACJA"), new Date(), data.appointmentId || "", data.eventId || "",
    normalizeCRMPhone(data.phone || ""), data.clientName || "", data.service || "",
    data.operation || "", data.statusBefore || "", data.statusAfter || "",
    data.oldDate || "", data.newDate || "", data.initiator || "SYSTEM",
    data.reason || "", Number(data.differenceDays) || 0,
    data.movedLater ? "TAK" : "NIE", data.movedThenCancelled ? "TAK" : "NIE"
  ]);
}

function operationToStatus(operation, initiator) {
  if (operation === "ZREALIZOWANA") return "ZREALIZOWANA";
  if (operation === "NIEOBECNOSC") return "NIEOBECNOSC";
  if (operation === "PRZENIESIENIE") return "PRZENIESIONA";
  if (operation === "ANULOWANIE") return initiator === "KLIENT" ? "ANULOWANA_KLIENT" : "ANULOWANA_SALON";
  if (operation === "POTWIERDZENIE") return "POTWIERDZONA";
  if (operation === "ODRZUCENIE") return "ODRZUCONA";
  return operation || "POTWIERDZONA";
}

function recordAppointmentLifecycleAction(ss, postData) {
  const lifecycleLock = LockService.getScriptLock();
  let lifecycleLockAcquired = false;

  try {
    lifecycleLock.waitLock(20000);
    lifecycleLockAcquired = true;

    /* PERFORMANCE V20: nie dotykamy 5 technicznych arkuszy przy każdej zmianie. */
    const bookings = ensureExtendedBookingColumns(ss);
    const eventId = (postData.eventId || "").toString().trim();
    const operation = (postData.operation || "").toString().trim().toUpperCase();
    const initiator = (postData.initiator || "MISTRZYNI").toString().trim().toUpperCase();
    const row = findBookingRowForLifecycle(bookings, postData);

    if (row === -1) {
      return createJsonResponse({
        success: false,
        code: "CRM_APPOINTMENT_NOT_FOUND",
        error: "Nie znaleziono wizyty w arkuszu CRM"
      });
    }

    const appointmentIdFromRow = bookings.getRange(row, 10).getValue() || "";
    const operationKey = [
      appointmentIdFromRow || eventId || row,
      operation,
      postData.oldDate || "",
      postData.newDate || ""
    ].join("|");
    const operationCache = CacheService.getScriptCache();
    if (operationCache.get("CRM_LIFECYCLE_" + operationKey)) {
      return createJsonResponse({
        success: true,
        duplicatePrevented: true,
        operation: operation,
        status: operationToStatus(operation, initiator)
      });
    }

    const oldDate = postData.oldDate ? new Date(postData.oldDate) : null;
    const newDate = postData.newDate ? new Date(postData.newDate) : null;
    const differenceDays = oldDate && newDate && !isNaN(oldDate) && !isNaN(newDate)
      ? Math.round((newDate.getTime() - oldDate.getTime()) / 86400000)
      : 0;
    const movedLater = operation === "PRZENIESIENIE" && differenceDays > 0;
    const statusAfter = operationToStatus(operation, initiator);
    const statusBefore = bookings.getRange(row, 9).getValue() || "POTWIERDZONA";
    const appointmentId = appointmentIdFromRow || makeCRMId("WIZYTA");

    /* Najpierw zapisujemy trwały stan CRM. Brak wydarzenia Google nie może
       zablokować anulowania ani przywrócić wizyty po odświeżeniu. */
    bookings.getRange(row, 9).setValue(statusAfter);
    bookings.getRange(row, 10).setValue(appointmentId);
    if (newDate && !isNaN(newDate.getTime())) bookings.getRange(row, 1).setValue(newDate);

    let movedThenCancelled = false;
    if (operation === "ANULOWANIE" && eventId) {
      const history = ss.getSheetByName(SHEET_VISIT_HISTORY);
      if (history && history.getLastRow() > 1) {
        const rows = history.getRange(2, 1, history.getLastRow() - 1, 17).getValues();
        movedThenCancelled = rows.some(value =>
          (value[3] || "").toString() === eventId &&
          (value[7] || "").toString() === "PRZENIESIENIE" &&
          (value[12] || "").toString() === "KLIENT"
        );
      }
    }

    appendVisitHistory(ss, {
      appointmentId: appointmentId,
      eventId: eventId,
      phone: postData.phone,
      clientName: postData.clientName,
      service: postData.service,
      operation: operation,
      statusBefore: statusBefore,
      statusAfter: statusAfter,
      oldDate: postData.oldDate || "",
      newDate: postData.newDate || "",
      initiator: initiator,
      reason: postData.reason || "",
      differenceDays: differenceDays,
      movedLater: movedLater,
      movedThenCancelled: movedThenCancelled
    });

    let calendarEventDeleted = false;
    let calendarEventAlreadyMissing = false;
    let calendarWarning = "";

    if (postData.deleteCalendarEvent === true) {
      if (!eventId) {
        calendarEventAlreadyMissing = true;
      } else {
        try {
          const settings = getDynamicSettings(ss);
          const calendar = CalendarApp.getCalendarById(settings.calendar_id || "");
          const event = calendar ? calendar.getEventById(eventId) : null;
          if (event) {
            event.deleteEvent();
            calendarEventDeleted = true;
          } else {
            calendarEventAlreadyMissing = true;
          }
        } catch (calendarError) {
          /* Status CRM jest już zapisany. Błąd Google zwracamy jako ostrzeżenie,
             nie jako błąd całej operacji. */
          calendarEventAlreadyMissing = true;
          calendarWarning = calendarError.toString();
          Logger.log("Anulowanie CRM zapisane, problem Google Calendar: " + calendarWarning);
        }
      }
    }

    /* PERFORMANCE V20: zmieniła się tylko jedna klientka. */
    synchronizeCustomerStatistics(ss, postData.phone || "");
    updateClientRiskFromHistory(ss, postData.phone || "");
    operationCache.put("CRM_LIFECYCLE_" + operationKey, "1", 120);

    return createJsonResponse({
      success: true,
      status: statusAfter,
      movedLater: movedLater,
      movedThenCancelled: movedThenCancelled,
      differenceDays: differenceDays,
      calendarEventDeleted: calendarEventDeleted,
      calendarEventAlreadyMissing: calendarEventAlreadyMissing,
      calendarWarning: calendarWarning
    });
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  } finally {
    if (lifecycleLockAcquired) {
      try {
        lifecycleLock.releaseLock();
      } catch (releaseError) {
        Logger.log("Nie udało się zwolnić blokady lifecycle: " + releaseError.toString());
      }
    }
  }
}

function calculateClientRisk(ss, phone) {
  const normalized = normalizeCRMPhone(phone);
  const result = {
    cancellations: 0, reschedules: 0, movedLater: 0, noShows: 0,
    movedThenCancelled: 0, score: 0, level: "STANDARDOWY",
    suggestedMode: "STANDARDOWY"
  };
  const history = ss.getSheetByName(SHEET_VISIT_HISTORY);
  if (!history || history.getLastRow() < 2) return result;
  const rows = history.getRange(2, 1, history.getLastRow() - 1, 17).getValues();
  rows.forEach(row => {
    if (normalizeCRMPhone(row[4]) !== normalized) return;
    const operation = (row[7] || "").toString();
    const initiator = (row[12] || "").toString();
    if (initiator !== "KLIENT") return;
    if (operation === "ANULOWANIE") result.cancellations += 1;
    if (operation === "PRZENIESIENIE") result.reschedules += 1;
    if ((row[15] || "").toString() === "TAK") result.movedLater += 1;
    if (operation === "NIEOBECNOSC") result.noShows += 1;
    if ((row[16] || "").toString() === "TAK") result.movedThenCancelled += 1;
  });
  result.score = result.cancellations * 3 + result.noShows * 5 +
    result.movedLater + result.movedThenCancelled * 6;
  if (result.movedThenCancelled > 0 || result.noShows > 0 || result.cancellations >= 3) {
    result.level = "WYMAGA_POTWIERDZENIA";
    result.suggestedMode = "WYMAGA_POTWIERDZENIA";
  } else if (result.cancellations >= 2 || result.movedLater >= 3) {
    result.level = "OBSERWACJA";
  }
  if (result.cancellations >= 5 || result.movedThenCancelled >= 2) {
    result.level = "REZERWACJA_OGRANICZONA";
    result.suggestedMode = "REZERWACJA_OGRANICZONA";
  }
  return result;
}

function getCurrentClientRestriction(ss, phone) {
  const normalized = normalizeCRMPhone(phone);
  const sheet = getOrCreateSheetWithHeaders(ss, SHEET_CLIENT_RESTRICTIONS, [
    "Telefon", "Tryb rezerwacji", "Poziom ryzyka", "Powód", "Data zmiany",
    "Zmienił", "Poprzedni tryb", "Anulacje klienta", "Przeniesienia klienta",
    "Przeniesienia później", "Nieobecności", "Przeniesienie i anulowanie"
  ]);
  if (sheet.getLastRow() < 2) return null;
  const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, 12).getValues();
  for (let i = rows.length - 1; i >= 0; i--) {
    if (normalizeCRMPhone(rows[i][0]) === normalized) {
      return { mode: rows[i][1] || "STANDARDOWY", level: rows[i][2] || "STANDARDOWY", reason: rows[i][3] || "" };
    }
  }
  return null;
}

function updateClientRiskFromHistory(ss, phone) {
  if (!phone) return;
  const risk = calculateClientRisk(ss, phone);
  const current = getCurrentClientRestriction(ss, phone);
  if (!current && risk.suggestedMode !== "STANDARDOWY") {
    setClientBookingModeInternal(ss, phone, risk.suggestedMode, "Automatyczna ocena historii", "SYSTEM", risk);
  }
}

function crmSyncCustomerBookingModeCellV42(ss, phone, mode) {
  const normalized = normalizeCRMPhone(phone || "");
  if (!normalized) return;
  const sh = ensureCustomerSheet(ss);
  if (sh.getLastRow() < 2) return;
  const rows = sh.getRange(2, 1, sh.getLastRow() - 1, Math.max(9, sh.getLastColumn())).getValues();
  for (let i = 0; i < rows.length; i++) {
    if (normalizeCRMPhone(rows[i][0]) !== normalized) continue;
    sh.getRange(i + 2, 9).setValue(String(mode || "STANDARDOWY").toUpperCase());
    return;
  }
}

function setClientBookingModeInternal(ss, phone, mode, reason, changedBy, risk) {
  const normalized = normalizeCRMPhone(phone);
  const current = getCurrentClientRestriction(ss, normalized);
  const metrics = risk || calculateClientRisk(ss, normalized);
  const sheet = getOrCreateSheetWithHeaders(ss, SHEET_CLIENT_RESTRICTIONS, [
    "Telefon", "Tryb rezerwacji", "Poziom ryzyka", "Powód", "Data zmiany",
    "Zmienił", "Poprzedni tryb", "Anulacje klienta", "Przeniesienia klienta",
    "Przeniesienia później", "Nieobecności", "Przeniesienie i anulowanie"
  ]);
  sheet.appendRow([
    normalized, mode || "STANDARDOWY", metrics.level, reason || "", new Date(),
    changedBy || "MISTRZYNI", current ? current.mode : "STANDARDOWY",
    metrics.cancellations, metrics.reschedules, metrics.movedLater,
    metrics.noShows, metrics.movedThenCancelled
  ]);
  crmSyncCustomerBookingModeCellV42(ss, normalized, mode || "STANDARDOWY");
}

function setClientBookingModeAction(ss, postData) {
  try {
    initializeCRMExtensions(ss);
    const allowed = ["STANDARDOWY", "WYMAGA_POTWIERDZENIA", "REZERWACJA_OGRANICZONA", "TYLKO_KONTAKT", "ZABLOKOWANY"];
    const mode = (postData.mode || "STANDARDOWY").toString().toUpperCase();
    if (allowed.indexOf(mode) === -1) return createJsonResponse({ success: false, error: "Nieprawidłowy tryb rezerwacji" });

    const customer = crmFindCustomerByPhoneV4(ss, postData.phone || "");
    if (customer && crmSourceHasV4(customer.source, "BOOKSY") && mode !== "TYLKO_KONTAKT" && mode !== "ZABLOKOWANY") {
      return createJsonResponse({
        success: false,
        code: "BOOKSY_CONTACT_ONLY",
        error: "Klient Booksy nie może mieć włączonej samodzielnej rezerwacji przez CRM."
      });
    }

    setClientBookingModeInternal(ss, postData.phone, mode, postData.reason, postData.changedBy, null);
    return createJsonResponse({ success: true, mode: mode });
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  }
}

function getClientCRMProfileAction(ss, phone) {
  try {
    const normalized = normalizeCRMPhone(phone);

    let client = {
      phone: normalized,
      name: "",
      visits: 0,
      cancelled: 0,
      lastVisit: ""
    };

    const customerSheet = ss.getSheetByName(SHEET_CUSTOMERS);
    const timeZone = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";

    if (customerSheet && customerSheet.getLastRow() > 1) {
      const rows = customerSheet
        .getRange(2, 1, customerSheet.getLastRow() - 1, Math.max(8, customerSheet.getLastColumn()))
        .getValues();

      for (let i = 0; i < rows.length; i++) {
        if (normalizeCRMPhone(rows[i][0]) !== normalized) continue;

        const lastVisitDate =
          rows[i][4] instanceof Date
            ? rows[i][4]
            : (rows[i][4] ? new Date(rows[i][4]) : null);

        client = {
          phone: normalized,
          name: rows[i][1] || "",
          visits:
            typeof rows[i][2] === "number"
              ? Math.max(0, Math.trunc(rows[i][2]))
              : 0,
          cancelled:
            typeof rows[i][3] === "number"
              ? Math.max(0, Math.trunc(rows[i][3]))
              : 0,
          lastVisit:
            lastVisitDate && !isNaN(lastVisitDate.getTime())
              ? Utilities.formatDate(
                  lastVisitDate,
                  timeZone,
                  "yyyy-MM-dd HH:mm"
                )
              : "",
          source: String(rows[i][6] || "").trim(),
          sourceKey: String(rows[i][7] || "").trim()
        };
        break;
      }
    }

    const risk = {
      cancellations: 0,
      reschedules: 0,
      movedLater: 0,
      noShows: 0,
      movedThenCancelled: 0,
      score: 0,
      level: "STANDARDOWY",
      suggestedMode: "STANDARDOWY"
    };

    const history = [];
    const historySheet = ss.getSheetByName(SHEET_VISIT_HISTORY);

    if (historySheet && historySheet.getLastRow() > 1) {
      const rows = historySheet
        .getRange(2, 1, historySheet.getLastRow() - 1, 17)
        .getValues();

      rows.forEach(row => {
        if (normalizeCRMPhone(row[4]) !== normalized) return;

        const operation = (row[7] || "").toString();
        const initiator = (row[12] || "").toString();

        history.push({
          date: row[1],
          operation: operation,
          oldDate: row[10],
          newDate: row[11],
          initiator: initiator,
          reason: row[13]
        });

        if (initiator !== "KLIENT") return;

        if (operation === "ANULOWANIE") risk.cancellations += 1;
        if (operation === "PRZENIESIENIE") risk.reschedules += 1;
        if ((row[15] || "").toString() === "TAK") risk.movedLater += 1;
        if (operation === "NIEOBECNOSC") risk.noShows += 1;
        if ((row[16] || "").toString() === "TAK") {
          risk.movedThenCancelled += 1;
        }
      });
    }

    risk.score =
      risk.cancellations * 3 +
      risk.noShows * 5 +
      risk.movedLater +
      risk.movedThenCancelled * 6;

    if (
      risk.movedThenCancelled > 0 ||
      risk.noShows > 0 ||
      risk.cancellations >= 3
    ) {
      risk.level = "WYMAGA_POTWIERDZENIA";
      risk.suggestedMode = "WYMAGA_POTWIERDZENIA";
    } else if (
      risk.cancellations >= 2 ||
      risk.movedLater >= 3
    ) {
      risk.level = "OBSERWACJA";
    }

    if (
      risk.cancellations >= 5 ||
      risk.movedThenCancelled >= 2
    ) {
      risk.level = "REZERWACJA_OGRANICZONA";
      risk.suggestedMode = "REZERWACJA_OGRANICZONA";
    }

    let restriction = null;
    const restrictionSheet =
      ss.getSheetByName(SHEET_CLIENT_RESTRICTIONS);

    if (
      restrictionSheet &&
      restrictionSheet.getLastRow() > 1
    ) {
      const rows = restrictionSheet
        .getRange(
          2,
          1,
          restrictionSheet.getLastRow() - 1,
          Math.min(12, Math.max(4, restrictionSheet.getLastColumn()))
        )
        .getValues();

      for (let i = rows.length - 1; i >= 0; i--) {
        if (normalizeCRMPhone(rows[i][0]) !== normalized) continue;

        restriction = {
          mode: rows[i][1] || "STANDARDOWY",
          level: rows[i][2] || "STANDARDOWY",
          reason: rows[i][3] || ""
        };
        break;
      }
    }

    return createJsonResponse({
      success: true,
      profile: {
        client: client,
        risk: risk,
        bookingMode:
          (function(){
            const effective = crmEffectiveBookingModeV4(ss, client);
            return effective.mode || risk.suggestedMode || "STANDARDOWY";
          })(),
        restrictionReason:
          (function(){
            const effective = crmEffectiveBookingModeV4(ss, client);
            return effective.reason || (restriction ? restriction.reason : "");
          })(),
        history: history.slice(-50).reverse()
      }
    });

  } catch (error) {
    return createJsonResponse({
      success: false,
      error: error.toString()
    });
  }
}

function getServiceRecommendation(ss, serviceName) {
  const sheet = ss.getSheetByName(SHEET_PUBLIC) || ss.getSheetByName(SHEET_DRAFT);
  const fallback = { minDays: 21, defaultDays: 24, maxDays: 28 };
  if (!sheet || sheet.getLastRow() < 2) return fallback;
  const columns = Math.max(10, sheet.getLastColumn());
  const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, columns).getValues();
  for (let i = 0; i < rows.length; i++) {
    if ((rows[i][1] || "").toString().trim() === (serviceName || "").toString().trim()) {
      return {
        minDays: parseInt(rows[i][7], 10) || fallback.minDays,
        defaultDays: parseInt(rows[i][8], 10) || fallback.defaultDays,
        maxDays: parseInt(rows[i][9], 10) || fallback.maxDays
      };
    }
  }
  return fallback;
}

function familyAvailabilityForDate(ss, date) {
  const sheet = ss.getSheetByName(SHEET_FAMILY_SCHEDULE);
  const key = Utilities.formatDate(date, ss.getSpreadsheetTimeZone(), "yyyy-MM-dd");
  const result = { blocked: false, availableFrom: "", availableTo: "", reason: "", shift: "WOLNE" };
  if (!sheet || sheet.getLastRow() < 2) return result;
  const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, 16).getValues();
  for (let i = rows.length - 1; i >= 0; i--) {
    const rowKey = rows[i][0] instanceof Date
      ? Utilities.formatDate(rows[i][0], ss.getSpreadsheetTimeZone(), "yyyy-MM-dd")
      : (rows[i][0] || "").toString().substring(0, 10);
    if (rowKey === key && (rows[i][15] || "TAK").toString() !== "NIE") {
      result.blocked = (rows[i][12] || "").toString().toUpperCase() === "TAK";
      result.availableFrom = rows[i][10] || "";
      result.availableTo = rows[i][11] || "";
      result.reason = rows[i][13] || "";
      result.shift = rows[i][2] || "WOLNE";
      return result;
    }
  }
  return result;
}

function getSmartNextVisitAction(ss, postData) {
  try {
    initializeCRMExtensions(ss);
    const recommendation = getServiceRecommendation(ss, postData.service || "");
    const base = postData.baseDate ? new Date(postData.baseDate) : new Date();
    const preference = (postData.preference || "REKOMENDOWANY").toString();
    let days = recommendation.defaultDays;
    if (preference === "WCZESNIEJ") days = recommendation.minDays;
    if (preference === "POZNIEJ") days = recommendation.maxDays;
    const recommended = new Date(base);
    recommended.setDate(recommended.getDate() + days);
    recommended.setHours(0, 0, 0, 0);

    const settings = getDynamicSettings(ss);
    const availableSlots = [];
    let selectedDate = null;
    for (let offset = 0; offset < 21 && !selectedDate; offset++) {
      const day = new Date(recommended);
      day.setDate(day.getDate() + offset);
      const family = familyAvailabilityForDate(ss, day);
      if (family.blocked) continue;
      const workStart = family.availableFrom || settings.work_start_hour;
      const workEnd = family.availableTo || settings.work_end_hour;
      const startMinutes = parseTimeToMinutes(workStart, settings.work_start_hour) + (parseInt(settings.start_offset_minutes, 10) || 0);
      const endMinutes = parseTimeToMinutes(workEnd, settings.work_end_hour);
      const step = parseInt(settings.slot_interval_minutes, 10) || 45;
      const duration = parseInt(postData.duration, 10) || step;
      const daySlots = [];
      for (let minute = startMinutes; minute + duration <= endMinutes; minute += step) {
        const candidate = new Date(day);
        candidate.setHours(Math.floor(minute / 60), minute % 60, 0, 0);
        const validation = validateBookingCandidate(ss, settings, { start: candidate, duration: duration, excludeEventId: "" });
        if (validation.success) daySlots.push(Utilities.formatDate(candidate, ss.getSpreadsheetTimeZone(), "HH:mm"));
      }
      if (daySlots.length > 0) {
        selectedDate = day;
        Array.prototype.push.apply(availableSlots, daySlots);
      }
    }

    return createJsonResponse({
      success: true,
      minDays: recommendation.minDays,
      defaultDays: recommendation.defaultDays,
      maxDays: recommendation.maxDays,
      recommendedDate: Utilities.formatDate(selectedDate || recommended, ss.getSpreadsheetTimeZone(), "yyyy-MM-dd"),
      availableSlots: availableSlots,
      manualSelectionAllowed: true
    });
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  }
}

