function formatScheduleTimeValue(value, ss) {
  if (value === "" || value === null || value === undefined) return "";
  if (value instanceof Date) return Utilities.formatDate(value, ss.getSpreadsheetTimeZone(), "HH:mm");
  const text = value.toString().trim();
  if (/^\d{2}:\d{2}$/.test(text)) return text;
  return normalizeTimeValue(value, ss);
}
function legacyShiftToCode(value) {
  const code=(value||"").toString().trim().toUpperCase();
  if(code==="DZIENNA")return "1";
  if(code==="NOCNA")return "2";
  if(code==="WOLNE")return "W";
  return code;
}
function getFamilyScheduleAction(ss, fromDate, toDate) {
  try {
    initializeCRMExtensions(ss);
    const sheet = ss.getSheetByName(SHEET_FAMILY_SCHEDULE);
    if (!sheet || sheet.getLastRow() < 2) return createJsonResponse({ success: true, entries: [] });
    const today = new Date();
    const defaultFrom = new Date(today.getFullYear(), today.getMonth() - 1, 1);
