function normalizeScheduleCode(code) {
  const value=(code||"").toString().trim().toUpperCase().replace("Ś","S");
  if(value==="1") return {code:"1",type:"PRACA",from:"07:00",to:"19:00"};
  if(value==="2") return {code:"2",type:"PRACA",from:"19:00",to:"07:00"};
  if(["W","WH","WN"].indexOf(value)>=0) return {code:value,type:"WOLNE",from:"",to:""};
  if(value==="UW") return {code:"UW",type:"WOLNE",from:"",to:""};
  if(value==="OP") return {code:"OP",type:"WOLNE",from:"",to:""};
  if(value==="SW") return {code:"SW",type:"SWIETO",from:"",to:""};
