function normalizeOCRScheduleCell(value){
  let raw=(value||"").toString().trim().toUpperCase().replace(/Ś/g,"S").replace(/[^A-Z0-9+]/g,"");
  const exact={"1":"1","I":"1","L":"1","+":"1","2":"2","Z":"2","W":"W","WH":"WH","WN":"WN","UW":"UW","OP":"OP","SW":"SW","BHP":"BHP","OW":"W"};
  if(exact[raw]) return exact[raw];
  if(raw==="WW"||raw==="WWW") return "W";
  return "?";
}
function normalizeOCRName(value){
  return (value||"").toString().toLowerCase().replace(/[^a-z0-9ąćęłńóśźż]/g,"");
}
function levenshteinDistance(a,b){
  a=normalizeOCRName(a);b=normalizeOCRName(b);const matrix=[];
  for(let i=0;i<=b.length;i++)matrix[i]=[i];
  for(let j=0;j<=a.length;j++)matrix[0][j]=j;
  for(let i=1;i<=b.length;i++)for(let j=1;j<=a.length;j++)matrix[i][j]=b.charAt(i-1)===a.charAt(j-1)?matrix[i-1][j-1]:Math.min(matrix[i-1][j-1]+1,matrix[i][j-1]+1,matrix[i-1][j]+1);
  return matrix[b.length][a.length];
}
function findEmployeeOCRLine(lines,employeeName){
  const expected=(employeeName||"").split(/\s+/).filter(Boolean),expectedFirst=expected[0]||"oleksandr",expectedLast=expected[expected.length-1]||"strelnikov";
  const surnameVariants=[expectedLast,"strelnikov","strelnkov","strelnlkov","streinikov","strelniikov"];
  let best=null;
  lines.forEach((line,index)=>{
    const lower=(line||"").toLowerCase(),words=lower.split(/[^a-z0-9ąćęłńóśźż]+/).filter(Boolean);
    const firstScore=words.reduce((m,w)=>Math.min(m,levenshteinDistance(w,expectedFirst)),99);
    const lastScore=words.reduce((m,w)=>Math.min(m,...surnameVariants.map(v=>levenshteinDistance(w,v))),99);
    let score=firstScore+lastScore;
    if(lower.indexOf("oleks")>=0)score-=2;
    if(lower.indexOf("strel")>=0)score-=2;
    if(!best||score<best.score)best={line:line,index:index,score:score};
  });
  return best&&best.score<=4?best:null;
}
function extractEmployeeScheduleCodes(ocrText,employeeName,days){
  const lines=(ocrText||"").split(/\r?\n/).filter(x=>x.trim()),match=findEmployeeOCRLine(lines,employeeName);
  if(!match)return{employeeFound:false,line:"",codes:Array(days).fill("?"),recognized:0,matchScore:null};
  const line=match.line;
  let after=line;
  const pipeIndex=line.indexOf("|");
  if(pipeIndex>=0)after=line.slice(pipeIndex+1);
  else {
    const strel=line.toLowerCase().indexOf("strel");
    if(strel>=0){const tail=line.slice(strel);const boundary=tail.search(/[|\t]/);after=boundary>=0?tail.slice(boundary+1):tail.replace(/^\S+/,'');}
  }
  let rawCells=after.indexOf("|")>=0?after.split("|"):after.split(/\s+/);
  rawCells=rawCells.map(x=>x.trim()).filter(Boolean);
  // Usuń przypadkowe fragmenty nazwiska pozostałe po OCR.
  rawCells=rawCells.filter(x=>!/^oleks/i.test(x)&&!/^strel/i.test(x));
  const codes=rawCells.map(normalizeOCRScheduleCell).slice(0,days);
  while(codes.length<days)codes.push("?");
  return{employeeFound:true,line:line,codes:codes,recognized:codes.filter(x=>x!=="?").length,matchScore:match.score};
}

