    if(codes.length!==days) return createJsonResponse({success:false,error:"Liczba kodów nie odpowiada liczbie dni miesiąca"});
    const invalid=codes.map((c,i)=>({day:i+1,code:(c||"").toString().toUpperCase()})).filter(x=>!["1","2","W","WH","WN","UW","OP","SW","BHP"].includes(x.code));
    if(invalid.length) return createJsonResponse({success:false,error:"Popraw nierozpoznane dni: "+invalid.map(x=>x.day).join(", ")});
    const sh=scheduleSheet(ss),existing=sh.getLastRow()>1?sh.getRange(2,1,sh.getLastRow()-1,18).getValues():[],keep=[];
    existing.forEach(row=>{
