    if(all.length)sh.getRange(2,1,all.length,18).setValues(all);
    scheduleHistorySheet(ss).appendRow([new Date(),"","OFICJALNY","ZATWIERDZENIE_IMPORTU","","","","NIE",month,version]);
    const imp=importSheet(ss); if(imp.getLastRow()>1){const rows=imp.getRange(2,1,imp.getLastRow()-1,9).getValues();for(let i=0;i<rows.length;i++)if((rows[i][0]||"").toString()===importId){imp.getRange(i+2,6).setValue("ZATWIERDZONY");break;}}
