function correctedScheduleCodeForDate(cur,ref) {
  const seq=["1","1","2","2","W","W","W","W"];
  const diff=Math.round((cur-ref)/86400000),idx=((diff%8)+8)%8,base=seq[idx];
  if(cur.getDay()!==0) return {code:base,reason:"Prognoza 4×4"};
  if(idx===0) return {code:"W",reason:"Niedziela: początek bloku pracy przesunięty"};
  const tuesday=new Date(cur); tuesday.setDate(tuesday.getDate()+2);
  const tdiff=Math.round((tuesday-ref)/86400000),tidx=((tdiff%8)+8)%8;
  if(idx>=4 && tidx===0) return {code:"1",reason:"Niedziela robocza przed blokiem zaczynającym się we wtorek"};
  return {code:base,reason:"Prognoza 4×4"};
}
