    for(let d=new Date(rangeStart);d<=rangeEnd;d.setDate(d.getDate()+1)){
      const cur=new Date(d.getFullYear(),d.getMonth(),d.getDate()),fixed=correctedScheduleCodeForDate(cur,ref),code=fixed.code,type=code==="W"?"WOLNE":"PRACA";
      forecast.push([cur,type,code,code==="1"?"07:00":code==="2"?"19:00":"",code==="1"?"19:00":code==="2"?"07:00":"",60,60,"08:00","16:00",30,"","","NIE",fixed.reason,"AUTOMATYCZNY","TAK","PROGNOZA",version]);
