function syncWorkScheduleToGoogleCalendarAction(ss,month) {
  const lock=LockService.getScriptLock();
  if(!lock.tryLock(5000)) return createJsonResponse({success:false,error:"Synchronizacja już trwa"});
  let created=0,removed=0,duplicates=0,adoptedLegacy=0;
  try {
    if(!/^\d{4}-\d{2}$/.test(String(month||""))) throw new Error("Nieprawidłowy miesiąc RRRR-MM");
    const effective=JSON.parse(getEffectiveScheduleAction(ss,month).getContent()).entries||[];
    const settings=getDynamicSettings(ss),tz=ss.getSpreadsheetTimeZone()||Session.getScriptTimeZone();
    const calendar=CalendarApp.getCalendarById(settings.work_schedule_calendar_id||"");
    if(!calendar) throw new Error("Nie znaleziono kalendarza grafiku pracy");
    const first=workScheduleNoonDate(month+"-01",tz),last=workScheduleNoonDate(Utilities.formatDate(new Date(first.getFullYear(),first.getMonth()+1,1),tz,"yyyy-MM-dd"),tz);
    const wanted={};
    effective.forEach(item=>{const code=String(item.code||"").trim().toUpperCase();if(!["1","2"].includes(code))return;const title=code==="1"?"Brak":"BRAK",day=String(item.date).slice(0,10);wanted[day+"|"+title]={day,title,code,date:workScheduleNoonDate(day,tz)};});
    const existing={};
    /* Zarządzamy wyłącznie eventami technicznie należącymi do grafiku.
       Nie adoptujemy i nie usuwamy prywatnych całodniowych wydarzeń tylko
       dlatego, że ktoś nazwał je „Brak” albo „BRAK”. */
    calendar.getEvents(first,last).forEach(ev=>{
      if(!isOwnedWorkScheduleEvent(ev)) return;
      const title=(ev.getTitle()||"").trim();
      if(!["Brak","BRAK"].includes(title)) { ev.deleteEvent(); removed++; return; }
      const key=workScheduleActualDay(ev,tz)+"|"+title;
      (existing[key]||(existing[key]=[])).push(ev);
    });
    Object.keys(existing).forEach(key=>{const list=existing[key],need=wanted[key];if(!need){list.forEach(ev=>{ev.deleteEvent();removed++;});return;}const keep=list[0];list.slice(1).forEach(ev=>{ev.deleteEvent();removed++;duplicates++;});const marker=WORK_SCHEDULE_CALENDAR_MARKER+"|"+need.day+"|"+need.code+"|"+need.title;try{keep.setDescription(marker);}catch(e){}try{keep.setColor(CalendarApp.EventColor.YELLOW);}catch(e){}try{keep.setTransparency(CalendarApp.EventTransparency.TRANSPARENT);}catch(e){}delete wanted[key];});
    Object.keys(wanted).forEach(key=>{const x=wanted[key],ev=calendar.createAllDayEvent(x.title,x.date,{description:WORK_SCHEDULE_CALENDAR_MARKER+"|"+x.day+"|"+x.code+"|"+x.title});try{ev.setColor(CalendarApp.EventColor.YELLOW);}catch(e){}try{ev.setTransparency(CalendarApp.EventTransparency.TRANSPARENT);}catch(e){}created++;});
    calendarSyncLog(ss,{operation:"SYNC_GRAFIKU_BRAK_SAFE",month,status:"OK",created,removed,duplicates,details:{timeZone:tz,safeNoonDate:true,adoptedLegacy:0,externalEventsProtected:true}});
    return createJsonResponse({success:true,created,removed,duplicates,adoptedLegacy:0,externalEventsProtected:true,mode:"BRAK_ALL_DAY_SAFE",timeZone:tz});
  } catch(e) {calendarSyncLog(ss,{operation:"SYNC_GRAFIKU_BRAK_SAFE",month,status:"BLAD",created,removed,duplicates,error:e.toString()});return createJsonResponse({success:false,error:e.toString(),created,removed,duplicates});}
  finally {lock.releaseLock();}
}

