const SCHEDULE_XLSX_FILE_NAME = "Grafik_Oleksandr.xlsx";
const SCHEDULE_XLSX_DATA_SHEET = "Dane CRM";
function scheduleFileMatches(name,mimeType){
  const normalized=(name||"").toString().trim().toLowerCase().replace(/\s+/g,"_");
  const acceptedNames=["grafik_oleksandr.xlsx","grafik_oleksandr","grafik-oleksandr.xlsx","grafik-oleksandr"];
  const acceptedMime=[MimeType.MICROSOFT_EXCEL,MimeType.GOOGLE_SHEETS,"application/vnd.google-apps.spreadsheet","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","application/vnd.ms-excel"];
  return acceptedNames.indexOf(normalized)!==-1 || (normalized.indexOf("grafik_oleksandr")===0 && acceptedMime.indexOf(mimeType)!==-1);
}
function listAllScheduleFolderFilesXlsx(folder){
  const result=[],files=folder.getFiles();
  while(files.hasNext()){
    const file=files.next();
    result.push({id:file.getId(),name:file.getName(),mimeType:file.getMimeType(),updatedAt:file.getLastUpdated().toISOString(),size:file.getSize()});
  }
  return result;
}
function parseScheduleDateOnly(rawValue,displayValue,sourceTimeZone,targetTimeZone){
  const text=(displayValue||"").toString().trim();
  let y=0,m=0,d=0,match=null;
  if((match=text.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/))){
    y=Number(match[1]);m=Number(match[2]);d=Number(match[3]);
  }else if((match=text.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/))){
    d=Number(match[1]);m=Number(match[2]);y=Number(match[3]);
  }else if(rawValue instanceof Date&&!isNaN(rawValue.getTime())){
    const key=Utilities.formatDate(rawValue,sourceTimeZone||Session.getScriptTimeZone(),"yyyy-MM-dd");
    const parts=key.split("-").map(Number);y=parts[0];m=parts[1];d=parts[2];
  }
  if(!y||!m||!d)return null;
  // Południe w strefie arkusza docelowego zabezpiecza datę przed zmianą dnia
  // przy konwersji XLSX i różnych strefach czasowych projektu/arkusza.
  return Utilities.parseDate(
    Utilities.formatString("%04d-%02d-%02d 12:00",y,m,d),
    targetTimeZone||Session.getScriptTimeZone(),
    "yyyy-MM-dd HH:mm"
  );
}
function familyScheduleCodeMap(ss,fromDate,toDate){
  const sh=scheduleSheet(ss),map={};
  if(sh.getLastRow()<2)return map;
  sh.getRange(2,1,sh.getLastRow()-1,18).getValues().forEach(row=>{
    const date=row[0] instanceof Date?row[0]:new Date(row[0]);
    if(isNaN(date.getTime())||date<fromDate||date>toDate||(row[16]||"").toString()!=="OFICJALNY")return;
    map[Utilities.formatDate(date,ss.getSpreadsheetTimeZone(),"yyyy-MM-dd")]=legacyShiftToCode(row[2]||row[1]);
  });
  return map;
}
function importScheduleXlsxAction(ss,fileId){
  let temporaryId="";
  try{
    if(!fileId)return createJsonResponse({success:false,error:"Brak identyfikatora pliku XLSX"});
    if(typeof Drive==="undefined"||!Drive.Files)return createJsonResponse({success:false,error:"Włącz zaawansowaną usługę Google Drive API"});
    const source=DriveApp.getFileById(fileId);
    if(!scheduleFileMatches(source.getName(),source.getMimeType()))return createJsonResponse({success:false,error:"Oczekiwany plik Excel: Grafik_Oleksandr.xlsx. Znaleziono: "+source.getName()});
    let book=null;
    if(source.getMimeType()==="application/vnd.google-apps.spreadsheet"){
      book=SpreadsheetApp.openById(source.getId());
    }else{
      const resource={name:"TEMP_IMPORT_"+Date.now(),mimeType:"application/vnd.google-apps.spreadsheet"};
      const converted=Drive.Files.create(resource,source.getBlob(),{fields:"id,name"});
      temporaryId=converted.id;
      book=SpreadsheetApp.openById(temporaryId);
    }
    const dataSheet=book.getSheetByName(SCHEDULE_XLSX_DATA_SHEET);
    if(!dataSheet)throw new Error("Brak arkusza '"+SCHEDULE_XLSX_DATA_SHEET+"' w pliku XLSX");
    const dataRange=dataSheet.getDataRange();
    const values=dataRange.getValues();
    const displayValues=dataRange.getDisplayValues();
    const sourceTimeZone=book.getSpreadsheetTimeZone()||Session.getScriptTimeZone();
    const targetTimeZone=ss.getSpreadsheetTimeZone()||Session.getScriptTimeZone();
    if(values.length<2)throw new Error("Arkusz Dane CRM nie zawiera danych");
    const normalizeHeader=value=>(value||"").toString().trim().toLowerCase()
      .replace(/ą/g,"a").replace(/ć/g,"c").replace(/ę/g,"e").replace(/ł/g,"l")
      .replace(/ń/g,"n").replace(/ó/g,"o").replace(/ś/g,"s").replace(/[źż]/g,"z")
      .replace(/\s+/g," ");
    let headerRow=-1,dateCol=-1,codeCol=-1;
    for(let i=0;i<Math.min(values.length,25);i++){
      const headers=values[i].map(normalizeHeader);
      const d=headers.indexOf("data");
      let c=headers.indexOf("kod koncowy");
      if(c<0)c=headers.findIndex(h=>h.indexOf("kod")===0&&h.indexOf("koncow")!==-1);
      if(d>=0&&c>=0){headerRow=i;dateCol=d;codeCol=c;break;}
    }
    if(headerRow<0)throw new Error("Nie znaleziono wiersza nagłówków Data i Kod końcowy w pierwszych 25 wierszach arkusza Dane CRM");
    const imported=[],expectedByDate={},version="XLSX-"+Date.now();
    values.slice(headerRow+1).forEach((row,index)=>{
      const d=parseScheduleDateOnly(row[dateCol],displayValues[headerRow+1+index][dateCol],sourceTimeZone,targetTimeZone);
      const code=(row[codeCol]||"").toString().trim().toUpperCase().replace("Ś","S");
      if(!d||!code)return;
      const n=normalizeScheduleCode(code),key=Utilities.formatDate(d,targetTimeZone,"yyyy-MM-dd");
      expectedByDate[key]=legacyShiftToCode(n.code);
      imported.push([d,n.type,n.code,n.from,n.to,60,60,"08:00","16:00",30,"","","NIE","Import z "+SCHEDULE_XLSX_FILE_NAME,"XLSX","TAK","OFICJALNY",version]);
    });
    if(!imported.length)throw new Error("Nie znaleziono poprawnych wierszy Data/Kod końcowy");
    const minDate=new Date(Math.min.apply(null,imported.map(r=>r[0].getTime()))),maxDate=new Date(Math.max.apply(null,imported.map(r=>r[0].getTime())));
    const sh=scheduleSheet(ss),old=sh.getLastRow()>1?sh.getRange(2,1,sh.getLastRow()-1,18).getValues():[],keep=[];
    old.forEach(row=>{
      const d=row[0] instanceof Date?row[0]:new Date(row[0]),src=(row[16]||"").toString();
      const replace=!isNaN(d.getTime())&&d>=minDate&&d<=maxDate&&src==="OFICJALNY";
      if(!replace)keep.push(row);
    });
    if(sh.getLastRow()>1)sh.getRange(2,1,sh.getLastRow()-1,18).clearContent();
    const all=keep.concat(imported);if(sh.getMaxRows()<all.length+1)sh.insertRowsAfter(sh.getMaxRows(),all.length+1-sh.getMaxRows());
    sh.getRange(2,1,all.length,18).setValues(all);
    sh.getRange(2,1,all.length,1).setNumberFormat("yyyy-mm-dd");
    SpreadsheetApp.flush();
    const actualByDate=familyScheduleCodeMap(ss,minDate,maxDate),differences=[];
    Object.keys(expectedByDate).sort().forEach(key=>{
      const expected=expectedByDate[key]||"",actual=actualByDate[key]||"";
      if(expected!==actual)differences.push({date:key,expected:expected,actual:actual});
    });
    scheduleHistorySheet(ss).appendRow([new Date(),"","OFICJALNY","IMPORT_XLSX","","","","NIE",source.getName(),version+"; różnice="+differences.length]);
    if(differences.length)throw new Error("Import grafiku rodzinnego niezgodny ze źródłem: "+JSON.stringify(differences.slice(0,20)));
    return createJsonResponse({success:true,fileName:source.getName(),rows:imported.length,headerRow:headerRow+1,from:Utilities.formatDate(minDate,targetTimeZone,"yyyy-MM-dd"),to:Utilities.formatDate(maxDate,targetTimeZone,"yyyy-MM-dd"),differences:[],dateMode:"DISPLAY_DATE_NOON",sourceTimeZone:sourceTimeZone,targetTimeZone:targetTimeZone,version:version});
  }catch(e){return createJsonResponse({success:false,error:e.toString()});}
  finally{if(temporaryId){try{DriveApp.getFileById(temporaryId).setTrashed(true);}catch(ignore){}}}
}
