  const props=smartScheduleProperties(),last=props.getProperty("SMART_SCHEDULE_LAST_CHECK");
  const now=new Date(),code=smartScheduleCurrentCode(ss,now),working=code==="1"||code==="2";
  if(!last) return true;
  const elapsed=(now.getTime()-new Date(last).getTime())/86400000;
  return working ? elapsed>=0.75 : elapsed>=4;
}
