  const known=new Set(); existing.forEach(r=>{const d=r[0] instanceof Date?r[0]:new Date(r[0]);if(!isNaN(d.getTime()))known.add(Utilities.formatDate(d,ss.getSpreadsheetTimeZone(),"yyyy-MM-dd"));});
