const AUTO_COMPLETE_TRIGGER_FUNCTION = "automaticVisitCompletionTrigger";
const AUTO_COMPLETE_STATUS = "ZREALIZOWANA";
const AUTO_COMPLETE_ALLOWED_STATUSES = ["", "POTWIERDZONA", "CONFIRMED"];
const AUTO_COMPLETE_EXCLUDED_STATUSES = [
  "OCZEKUJE", "OCZEKUJE_POTWIERDZENIA", "PENDING",
  "TERMIN_ALTERNATYWNY", "ALTERNATIVE", "WYMAGA_KONTAKTU", "CONTACT",
  "ANULOWANA_KLIENT", "ANULOWANA_SALON", "ANULOWANA", "CANCELLED_CLIENT", "CANCELLED_SALON",
  "NIEOBECNOSC", "PRZENIESIONA", "ODRZUCONA", "ZREALIZOWANA", "COMPLETED"
];
function normalizeAutomaticVisitStatus(value) {
  return (value || "").toString().trim().toUpperCase().replace(/\s+/g, "_");
}
function automaticVisitHistoryExists(ss, appointmentId, eventId) {
  const history = ss.getSheetByName(SHEET_VISIT_HISTORY);
  if (!history || history.getLastRow() < 2) return false;
  const rows = history.getRange(2, 1, history.getLastRow() - 1, 10).getValues();
  return rows.some(row => {
    const sameAppointment = appointmentId && (row[2] || "").toString().trim() === appointmentId;
    const sameEvent = eventId && (row[3] || "").toString().trim() === eventId;
    const operation = normalizeAutomaticVisitStatus(row[7]);
    const statusAfter = normalizeAutomaticVisitStatus(row[9]);
    return (sameAppointment || sameEvent) && (operation === AUTO_COMPLETE_STATUS || statusAfter === AUTO_COMPLETE_STATUS);
  });
}
function automaticVisitCompletionCore(ss, options) {
  options = options || {};
  const dryRun = options.dryRun === true;
  const now = options.now instanceof Date ? options.now : new Date();
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(15000)) {
    return { success: false, error: "Automatyczne zakończenie jest już wykonywane." };
  }
  try {
    initializeCRMExtensions(ss);
    const sheet = ensureExtendedBookingColumns(ss);
    if (!sheet || sheet.getLastRow() < 2) {
      return { success: true, checked: 0, completed: 0, skipped: 0, dryRun: dryRun, completedRows: [] };
    }
    const columnCount = Math.max(12, sheet.getLastColumn());
    const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, columnCount).getValues();
    const completedRows = [];
    let skipped = 0;
    rows.forEach((row, index) => {
      const sheetRow = index + 2;
      const start = row[0] instanceof Date ? new Date(row[0]) : new Date(row[0]);
      if (!start || isNaN(start.getTime())) { skipped++; return; }
      const phone = (row[1] || "").toString().trim();
      const clientName = (row[2] || "").toString().trim();
      const service = (row[3] || "").toString().trim();
      const eventId = (row[6] || "").toString().trim();
      const duration = Math.max(1, parseInt(row[7], 10) || 45);
      const status = normalizeAutomaticVisitStatus(row[8]);
      const appointmentId = (row[9] || "").toString().trim() || makeCRMId("WIZYTA");
      const end = new Date(start.getTime() + duration * 60000);
      if (end.getTime() > now.getTime()) { skipped++; return; }
      if (AUTO_COMPLETE_EXCLUDED_STATUSES.indexOf(status) !== -1) { skipped++; return; }
      if (AUTO_COMPLETE_ALLOWED_STATUSES.indexOf(status) === -1) { skipped++; return; }
      if (phone === "Google Calendar" || !clientName || !service) { skipped++; return; }
      if (automaticVisitHistoryExists(ss, appointmentId, eventId)) { skipped++; return; }
      completedRows.push({
        row: sheetRow,
        appointmentId: appointmentId,
        eventId: eventId,
        phone: phone,
        clientName: clientName,
        service: service,
        start: start,
        end: end,
        statusBefore: status || "POTWIERDZONA"
      });
    });
    if (!dryRun) {
      completedRows.forEach(item => {
        sheet.getRange(item.row, 9).setValue(AUTO_COMPLETE_STATUS);
        sheet.getRange(item.row, 10).setValue(item.appointmentId);
        appendVisitHistory(ss, {
          appointmentId: item.appointmentId,
          eventId: item.eventId,
          phone: item.phone,
          clientName: item.clientName,
          service: item.service,
          operation: AUTO_COMPLETE_STATUS,
          statusBefore: item.statusBefore,
          statusAfter: AUTO_COMPLETE_STATUS,
          oldDate: item.start,
          newDate: "",
          initiator: "SYSTEM",
          reason: "Automatyczne zakończenie po upływie czasu wizyty",
          differenceDays: 0,
          movedLater: false,
          movedThenCancelled: false
        });
      });
      if (completedRows.length) synchronizeCustomerStatistics(ss);
    }
    return {
      success: true,
      checked: rows.length,
      completed: completedRows.length,
      skipped: skipped,
      dryRun: dryRun,
      completedRows: completedRows.map(item => ({
        row: item.row,
        appointmentId: item.appointmentId,
        eventId: item.eventId,
        clientName: item.clientName,
        service: item.service,
        start: item.start,
        end: item.end
      }))
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  } finally {
    lock.releaseLock();
  }
}
function automaticVisitCompletionTrigger() {
  const result = automaticVisitCompletionCore(getSpreadsheet(), { dryRun: false });
  if (!result.success) Logger.log("Automatyczne zakończenie wizyt: " + result.error);
  else Logger.log("Automatyczne zakończenie wizyt: sprawdzono=" + result.checked + ", zakończono=" + result.completed);
}
function runAutomaticVisitCompletionAction(ss, dryRun) {
  return createJsonResponse(automaticVisitCompletionCore(ss || getSpreadsheet(), { dryRun: dryRun === true }));
}
function installAutomaticVisitCompletionTriggerAction(ss) {
  try {
    const triggers = ScriptApp.getProjectTriggers();
    let removed = 0;
    triggers.forEach(trigger => {
      if (trigger.getHandlerFunction() === AUTO_COMPLETE_TRIGGER_FUNCTION) {
        ScriptApp.deleteTrigger(trigger);
        removed++;
      }
    });
    ScriptApp.newTrigger(AUTO_COMPLETE_TRIGGER_FUNCTION).timeBased().everyMinutes(5).create();
    const test = automaticVisitCompletionCore(ss || getSpreadsheet(), { dryRun: true });
    return createJsonResponse({
      success: true,
      handler: AUTO_COMPLETE_TRIGGER_FUNCTION,
      intervalMinutes: 5,
      replacedTriggers: removed,
      dryRun: test
    });
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  }
}
function removeAutomaticVisitCompletionTriggerAction(ss) {
  try {
    let removed = 0;
    ScriptApp.getProjectTriggers().forEach(trigger => {
      if (trigger.getHandlerFunction() === AUTO_COMPLETE_TRIGGER_FUNCTION) {
        ScriptApp.deleteTrigger(trigger);
        removed++;
      }
    });
    return createJsonResponse({ success: true, removed: removed });
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  }
}
