    return createJsonResponse({
      success: false,
      error: "Blad zapisu raportu: " + error.toString()
    });
  }
}

function getCRMTestReportsFromSheet(ss, requestedLimit) {
  try {
    const sheet = ss.getSheetByName(SHEET_TEST_REPORTS);
    if (!sheet || sheet.getLastRow() < 2) {
      return createJsonResponse({ success: true, reports: [] });
    }
    let limit = parseInt(requestedLimit, 10) || 10;
    limit = Math.max(1, Math.min(limit, 50));
    const lastRow = sheet.getLastRow();
    const startRow = Math.max(2, lastRow - limit + 1);
    const rowCount = lastRow - startRow + 1;
    const values = sheet.getRange(startRow, 1, rowCount, 13).getValues();
    const timeZone = ss.getSpreadsheetTimeZone();
    const reports = values.reverse().map(row => ({
      date: row[0] instanceof Date
        ? Utilities.formatDate(row[0], timeZone, "yyyy-MM-dd HH:mm:ss")
        : String(row[0] || ""),
      testId: row[1] || "",
      testerVersion: row[2] || "",
      testType: row[3] || "",
      status: row[4] || "",
      passed: Number(row[5]) || 0,
      warnings: Number(row[6]) || 0,
      errors: Number(row[7]) || 0,
      durationSeconds: Number(row[8]) || 0,
      startedAt: row[9] || "",
      finishedAt: row[10] || "",
      currentStage: row[11] || ""
    }));
    return createJsonResponse({ success: true, reports: reports });
  } catch (error) {
    return createJsonResponse({
      success: false,
      error: "Blad odczytu raportow: " + error.toString()
    });
  }
}
