function getBookingRequestsAction(ss) {
  const sh = bookingRequestsSheet(ss);
  const tz = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
  const requests = [];

  if (sh.getLastRow() >= 2) {
    const rows = sh.getRange(2, 1, sh.getLastRow() - 1, 13).getValues();
    rows.forEach((r, i) => {
      if (String(r[9] || "") !== "OCZEKUJE") return;
      requests.push({
        row: i + 2,
        id: r[0],
        phone: r[2],
        client: r[3],
        service: r[4],
        duration: Number(r[5]) || 45,
        main: r[6] instanceof Date
          ? Utilities.formatDate(r[6], tz, "dd.MM.yyyy HH:mm")
          : r[6],
        alternative: r[7] instanceof Date
          ? Utilities.formatDate(r[7], tz, "dd.MM.yyyy HH:mm")
          : r[7],
        reason: r[8] || ""
      });
    });
  }

  /*
   * Statystyka anulowanych wizyt wedlug pierwotnego dnia wizyty.
   * Rekordy anulowane pozostaja poza aktywnym Kalendarzem, ale ich liczba
   * jest zwracana razem z prosbami, aby prawy panel nie wykonywal osobnego,
   * wolnego zapytania.
   */
  const cancelledByDate = {};
  const bookings = ss.getSheetByName(SHEET_BOOKINGS);
  if (bookings && bookings.getLastRow() >= 2) {
    const columnCount = Math.max(9, bookings.getLastColumn());
    const bookingRows = bookings
      .getRange(2, 1, bookings.getLastRow() - 1, columnCount)
      .getValues();

    bookingRows.forEach(row => {
      const status = normalizeActiveAppointmentStatus(row[8]);
      if (!["ANULOWANA", "ANULOWANA_KLIENT", "ANULOWANA_SALON"].includes(status)) {
        return;
      }

      const appointmentDate = row[0] instanceof Date ? row[0] : new Date(row[0]);
      if (!appointmentDate || isNaN(appointmentDate.getTime())) return;

      const dayKey = Utilities.formatDate(appointmentDate, tz, "yyyy-MM-dd");
      cancelledByDate[dayKey] = (cancelledByDate[dayKey] || 0) + 1;
    });
  }

  return createJsonResponse({
    success: true,
    requests: requests,
    pendingCount: requests.length,
    cancelledByDate: cancelledByDate
  });
}
