function markAdminInboxReadAction(ss, postData) {
  const type = String(postData.inboxType || "").trim().toUpperCase();
  const id = String(postData.requestId || "").trim();
  if (!id) return createJsonResponse({ success: false, error: "Brak ID wpisu" });

  try {
    if (type === "CONTACT_FORM") {
      const sheet = ensureContactRequestsSheet(ss);
      if (sheet.getLastRow() < 2) return createJsonResponse({ success: false, error: "Nie znaleziono wpisu" });
      const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, 6).getValues();
      for (let i = 0; i < rows.length; i++) {
        if (String(rows[i][0] || "") !== id) continue;
        const status = String(rows[i][5] || "NOWE").trim().toUpperCase();
        if (status === "NOWE") sheet.getRange(i + 2, 6).setValue("PRZECZYTANE");
        return createJsonResponse({ success: true, status: status === "NOWE" ? "PRZECZYTANE" : status });
      }
