    if (type === "BOOKING_REQUEST") {
      const sheet = ensureBookingRequestInboxColumn(ss);
      if (sheet.getLastRow() < 2) return createJsonResponse({ success: false, error: "Nie znaleziono wpisu" });
      const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, 14).getValues();
      for (let i = 0; i < rows.length; i++) {
        if (String(rows[i][0] || "") !== id) continue;
        const current = crmInboxReadState(rows[i][13]);
        if (current === "NOWE") sheet.getRange(i + 2, 14).setValue("PRZECZYTANE");
        return createJsonResponse({ success: true, status: current === "NOWE" ? "PRZECZYTANE" : current });
      }
    }

