// ==========================================================================
// ADMIN INBOX V4 2026-08-12
// SZYBKI ODCZYT: czysty odczyt arkuszy, bez ensure*, bez FormApp, bez Calendar.
// ==========================================================================
function buildAdminInboxDataFastV4(ss) {
  const tz = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
  const items = [];

  // Prośby INDEX — tylko odczyt istniejącego arkusza.
  const bookingSheet = ss.getSheetByName("Prośby o wizytę");

  if (bookingSheet && bookingSheet.getLastRow() > 1) {
    const rowCount = bookingSheet.getLastRow() - 1;
    const width = Math.max(22, bookingSheet.getLastColumn());

    const rows =
      bookingSheet
        .getRange(2, 1, rowCount, width)
        .getValues();

    rows.forEach(function(row, index) {
      const requestStatus =
        String(row[9] || "OCZEKUJE")
          .trim()
          .toUpperCase();

      let readState =
        crmInboxReadState(row[13]);

      const handledAt =
        row[12] instanceof Date
          ? row[12]
          : null;

      if (requestStatus !== "OCZEKUJE") {
        readState = "OBSŁUŻONE";

        /*
         * Główna Skrzynka nadal pozostaje lekka:
         * stare obsłużone wpisy nie są tu trzymane.
         * Pełna Historia Klientów ma osobny endpoint V26.9
         * ładowany dopiero po kliknięciu zakładki Historia.
         */
        if (
          !handledAt ||
          (Date.now() - handledAt.getTime()) >
            2 * 60 * 60 * 1000
        ) {
          return;
        }
      }

      const rawCreated = row[1];

      const createdAt =
        rawCreated instanceof Date
          ? Utilities.formatDate(
              rawCreated,
              tz,
              "dd.MM.yyyy HH:mm"
            )
          : String(rawCreated || "");

      const requestType =
        String(row[14] || "STANDARD")
          .trim()
          .toUpperCase();

      let proposals = [];

      if (requestType === "FIRST_VISIT") {
        try {
          proposals =
            JSON.parse(
              String(row[16] || "[]")
            );

          if (!Array.isArray(proposals)) {
            proposals = [];
          }
        } catch (proposalError) {
          proposals = [];
        }
      }

      items.push({
        type: "BOOKING_REQUEST",
        requestType: requestType,
        id: String(row[0] || ""),
        createdAt: createdAt,
        timestamp:
          rawCreated instanceof Date
            ? rawCreated.getTime()
            : 0,
        name: String(row[3] || ""),
        phone: String(row[2] || ""),
        email: String(row[15] || ""),
        service: String(row[4] || ""),
        category: String(
          row[19] ||
          (
            requestType === "FIRST_VISIT"
              ? row[4]
              : ""
          ) ||
          ""
        ),
        preferredWindow:
          String(row[20] || ""),
        contactMethod:
          String(row[21] || "")
            .trim()
            .toUpperCase(),
        duration:
          Number(row[5]) || 45,
        proposals: proposals,
        contactConsent:
          String(row[17] || "")
            .trim()
            .toUpperCase() === "TAK",
        title:
          requestType === "FIRST_VISIT"
            ? "Pierwsza wizyta - zapytanie online"
            : "Prośba o termin przez stronę",
        message:
          requestType === "FIRST_VISIT"
            ? String(row[18] || "")
            : String(row[8] || ""),
        main:
          row[6] instanceof Date
            ? Utilities.formatDate(
                row[6],
                tz,
                "dd.MM.yyyy HH:mm"
              )
            : String(row[6] || ""),
        alternative:
          row[7] instanceof Date
            ? Utilities.formatDate(
                row[7],
                tz,
                "dd.MM.yyyy HH:mm"
              )
            : String(row[7] || ""),
        status: requestStatus,
        readState: readState,
        row: index + 2
      });
    });
  }

  // Google Form — tylko lokalny arkusz CRM.
  const contactSheet =
    ss.getSheetByName(
      SHEET_CONTACT_REQUESTS
    );

  if (
    contactSheet &&
    contactSheet.getLastRow() > 1
  ) {
    const rowCount =
      contactSheet.getLastRow() - 1;

    const rows =
      contactSheet
        .getRange(
          2,
          1,
          rowCount,
          8
        )
        .getValues();

    rows.forEach(function(row, index) {
      const status =
        String(row[5] || "NOWE")
          .trim()
          .toUpperCase();

      const readState =
        status === "NOWE"
          ? "NOWE"
          : (
              status === "PRZECZYTANE"
                ? "PRZECZYTANE"
                : "OBSŁUŻONE"
            );

      const handledAt =
        row[6] instanceof Date
          ? row[6]
          : null;

      if (
        readState === "OBSŁUŻONE" &&
        (
          !handledAt ||
          (Date.now() - handledAt.getTime()) >
            2 * 60 * 60 * 1000
        )
      ) {
        return;
      }

      const rawCreated = row[1];

      const createdAt =
        rawCreated instanceof Date
          ? Utilities.formatDate(
              rawCreated,
              tz,
              "dd.MM.yyyy HH:mm"
            )
          : String(rawCreated || "");

      items.push({
        type: "CONTACT_FORM",
        id: String(row[0] || ""),
        createdAt: createdAt,
        timestamp:
          rawCreated instanceof Date
            ? rawCreated.getTime()
            : 0,
        name: String(row[2] || ""),
        phone: String(row[3] || ""),
        title: "Pierwsza wizyta - formularz",
        message: String(row[4] || ""),
        status: status,
        readState: readState,
        note: String(row[7] || ""),
        row: index + 2
      });
    });
  }

  items.sort(function(a, b) {
    return (
      Number(b.timestamp || 0) -
      Number(a.timestamp || 0)
    );
  });

  const counts = {
    total: items.length,
    new: 0,
    read: 0,
    handled: 0
  };

  items.forEach(function(item) {
    if (item.readState === "NOWE") {
      counts.new++;
    } else if (
      item.readState === "PRZECZYTANE"
    ) {
      counts.read++;
    } else {
      counts.handled++;
    }
  });

  return {
    success: true,
    items: items,
    counts: counts,
    generatedAt:
      Utilities.formatDate(
        new Date(),
        tz,
        "dd.MM.yyyy HH:mm:ss"
      )
  };
}

