        "OCZEKUJE",
        "",
        "",
        "",
        "NOWE",
        "FIRST_VISIT",
        String(postData.email || ("e2e+" + Date.now() + "@example.com")),
        JSON.stringify(proposals),
        postData.contactConsent === false ? "NIE" : "TAK",
        String(postData.message || (marker + " wiadomosc pierwszej wizyty")),
