      marker
    ]);

    return createJsonResponse({ success: true, requestId: requestId, requestType: "STANDARD" });
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  }
}

function updateExternalReviewAnnotationV4713Action(ss, postData){
  try{
    const sourceId=String(postData.sourceId||"").trim();
    const eventId=String(postData.eventId||"").trim().replace(/@google\.com$/i,"");
    if(!sourceId||!eventId)return createJsonResponse({success:false,error:"Brak SourceId lub Event ID"});

    const review=ss.getSheetByName("Do weryfikacji TEST");
    if(!review)return createJsonResponse({success:false,error:"Brak arkusza Do weryfikacji TEST"});
    let rowNo=0,oldReason="",raw="",start="";
    if(review.getLastRow()>1){
      const rows=review.getRange(2,1,review.getLastRow()-1,Math.max(9,review.getLastColumn())).getValues();
      const wanted=crmV4713NormSourceId(sourceId);
      for(let i=0;i<rows.length;i++){
        if(crmV4713NormSourceId(rows[i][2])===wanted){rowNo=i+2;oldReason=String(rows[i][3]||"");start=rows[i][7]||"";raw=String(rows[i][8]||"");break;}
      }
    }
    if(!rowNo)return createJsonResponse({success:false,error:"Nie znaleziono rekordu do sprawdzenia dla SourceId"});

    const client=String(postData.clientName||"").trim();
    const service=String(postData.service||"").trim();
    const note=String(postData.note||"").trim();
    let reason=oldReason.replace(/\s*\|\s*Notatka CRM:.*$/i,"").trim();
    if(note)reason+=(reason?" | ":"")+"Notatka CRM: "+note;
    review.getRange(rowNo,4).setValue(reason);
    review.getRange(rowNo,5).setValue(client);
    review.getRange(rowNo,7).setValue(service);

    const settings=getDynamicSettings(ss);
    const calendar=CalendarApp.getCalendarById(settings.calendar_id||"");
    if(!calendar)return createJsonResponse({success:false,error:"Brak kalendarza CRM TEST"});
    const ev=calendar.getEventById(eventId);
    if(!ev)return createJsonResponse({success:false,error:"Nie znaleziono kopii wydarzenia CRM"});
    const desc=String(ev.getDescription()||"");
    const meta=crmV4713CalendarMeta(desc);
    if(String(meta.sourceType||"").toUpperCase()!=="WIFE_CALENDAR_BLOCK")return createJsonResponse({success:false,error:"Odmowa: edycja dozwolona tylko dla kopii WIFE_CALENDAR_BLOCK"});
    if(crmV4713NormSourceId(meta.sourceId)!==crmV4713NormSourceId(sourceId))return createJsonResponse({success:false,error:"Odmowa: SourceId wydarzenia nie pasuje"});

    const fallback=crmV4713MeaningfulExternalName(ev.getTitle(),meta,{client:client,raw:raw});
    const titleBits=[client||fallback,service].filter(Boolean);
    ev.setTitle("⚠️ "+(titleBits.join(" — ")||"Do sprawdzenia"));
    const cleanDesc=desc.replace(/\n?CRM edycja:[\s\S]*$/i,"").trim();
    ev.setDescription(cleanDesc+"\nCRM edycja:\nKlient: "+client+"\nUsługa: "+service+"\nNotatka CRM: "+note);

    return createJsonResponse({
      success:true,readOnlySource:true,sourceCalendarTouched:false,
      sourceId:sourceId,eventId:ev.getId(),clientName:client,service:service,note:note,
      reviewReason:reason,rawText:raw,start:start,title:ev.getTitle()
    });
  }catch(error){return createJsonResponse({success:false,error:error.toString(),readOnlySource:true,sourceCalendarTouched:false});}
}

