function crmV4715FindReviewRow(ss, sourceId){
  const sh=ss.getSheetByName("Do weryfikacji TEST");
  if(!sh||sh.getLastRow()<2)return null;
  const wanted=crmV4713NormSourceId(sourceId);
  const width=Math.max(9,sh.getLastColumn());
  const rows=sh.getRange(2,1,sh.getLastRow()-1,width).getValues();
  for(let i=0;i<rows.length;i++){
    if(crmV4713NormSourceId(rows[i][2])!==wanted)continue;
    return {sheet:sh,rowNo:i+2,data:rows[i]};
  }
  return null;
}

function crmV4715FindWifeVisitBySourceId(ss, sourceId){
  const sh=ss.getSheetByName(SHEET_BOOKINGS);
  if(!sh||sh.getLastRow()<2)return null;
  const wanted=crmV4713NormSourceId(sourceId);
  const width=Math.max(22,sh.getLastColumn());
  const rows=sh.getRange(2,1,sh.getLastRow()-1,width).getValues();
  for(let i=0;i<rows.length;i++){
    if(String(rows[i][12]||"").trim().toUpperCase()!=="WIFE_CALENDAR")continue;
    if(crmV4713NormSourceId(rows[i][13])!==wanted)continue;
    return {sheet:sh,rowNo:i+2,data:rows[i],appointmentId:String(rows[i][9]||""),eventId:String(rows[i][6]||"")};
  }
  return null;
}

function crmV4715ExactDomService(ss, serviceName){
  const wanted=testFoldV47(serviceName||"");
  if(!wanted)return null;
  const hits=testServiceCatalogV47(ss).filter(function(item){
    return Boolean(item&&item.hasCrmEntry)&&testFoldV47(item.name||"")===wanted;
  });
  if(!hits.length)return null;
  hits.sort(function(a,b){return (Number(b.priority)||0)-(Number(a.priority)||0);});
  return hits[0];
}

function crmV4715UpdateImportLogResolved(ss, sourceId, visitResult, clientName, service, price){
  const sh=testImportLogSheet(ss);
  if(!sh||sh.getLastRow()<2)return 0;
  const wanted=crmV4713NormSourceId(sourceId);
  const width=Math.max(15,sh.getLastColumn());
  const rows=sh.getRange(2,1,sh.getLastRow()-1,width).getValues();
  let updated=0;
  rows.forEach(function(row,index){
    if(String(row[1]||"").trim().toUpperCase()!=="WIFE_CALENDAR")return;
    if(crmV4713NormSourceId(row[2])!==wanted)return;
    const rowNo=index+2;
    sh.getRange(rowNo,4).setValue("POTWIERDZONE_CRM");
    sh.getRange(rowNo,6).setValue(visitResult&&visitResult.appointmentId||"");
    sh.getRange(rowNo,7).setValue(visitResult&&visitResult.eventId||"");
    sh.getRange(rowNo,8).setValue(clientName||row[7]||"");
    sh.getRange(rowNo,10).setValue(service||row[9]||"");
    sh.getRange(rowNo,13).setValue(Number(price)||0);
    sh.getRange(rowNo,15).setValue("NIE");
    updated++;
  });
  return updated;
}

