function crmV4721ClientNameCounts(ss){
  const out={};
  crmAllCustomerRecordsV4718(ss).forEach(function(customer){
    const key=crmNormIdentityTextV4718(customer.name||"");
    if(key)out[key]=(out[key]||0)+1;
  });
  return out;
}

function crmV4721ReviewClass(parsed, oldClient, clientCounts){
  parsed=parsed||{};
  const services=Array.isArray(parsed.services)?parsed.services:[];
  const exactServices=services.filter(function(service){
    return Boolean(service&&service.hasCrmEntry) &&
      String(service.catalogSource||"").toUpperCase()!=="BOOKSY_REF" &&
      String(service.catalogSource||"").toUpperCase()!=="RAW" &&
      String(service.catalogSource||"").toUpperCase()!=="WIFE_GENERIC" &&
      String(service.confidence||"").toUpperCase()!=="RAW";
  });
  const allServicesExact=services.length>0&&exactServices.length===services.length;
  const name=String(parsed.name||"").trim();
  const nameParts=name.split(/\s+/).filter(Boolean);
  const nameKey=crmNormIdentityTextV4718(name||oldClient||"");
  const exactClientCount=nameKey?Number((clientCounts||{})[nameKey]||0):0;

  let code="DO_SPRAWDZENIA";
  if(!name) code="DO_ZIDENTYFIKOWANIA_KLIENTA";
  else if(nameParts.length===1 && exactClientCount===0) code="DO_ZIDENTYFIKOWANIA_KLIENTA";
  else if(Boolean(parsed.uncertainTimeNote) && allServicesExact) code="DO_UZUPELNIENIA_TERMINU";
  else if(!parsed.serviceRaw || !services.length || !allServicesExact) code="DO_UZUPELNIENIA_USLUGI";
  else if(parsed.matchReview || parsed.skipAutoImport || Number(parsed.titleTimeMismatchMinutes||0)>0) code="DO_SPRAWDZENIA";
  else code="DO_SPRAWDZENIA"; // rekord historycznie pozostaje w kolejce do świadomej rekonsyliacji

  const labels={
    DO_ZIDENTYFIKOWANIA_KLIENTA:"Do zidentyfikowania klienta",
    DO_UZUPELNIENIA_USLUGI:"Do uzupełnienia procedury",
    DO_UZUPELNIENIA_TERMINU:"Do sprawdzenia terminu",
    DO_SPRAWDZENIA:"Do sprawdzenia"
  };
  return {code:code,label:labels[code]||"Do sprawdzenia",allServicesExact:allServicesExact,exactClientCount:exactClientCount};
}

function getExternalReviewQueueStatusV4715Action(ss, postData){
  try{
    const review=ss.getSheetByName("Do weryfikacji TEST");
    if(!review||review.getLastRow()<2){
      return createJsonResponse({success:true,version:"4.7.22",toIdentify:0,toComplete:0,toCheck:0,pendingTotal:0,wifeReviewRows:0,booksyReviewRows:0,totalReviewRows:0,items:[]});
    }
    testResetRuntimeCacheV473();
    const settings=getDynamicSettings(ss);
    const sourceCalendarId=String(settings.wife_calendar_id||"").trim();
    const sourceCal=sourceCalendarId?CalendarApp.getCalendarById(sourceCalendarId):null;
    const bookingIds=new Set();
    const visits=ss.getSheetByName(SHEET_BOOKINGS);
    if(visits&&visits.getLastRow()>1){
      const rows=visits.getRange(2,1,visits.getLastRow()-1,Math.max(22,visits.getLastColumn())).getValues();
      rows.forEach(function(row){
        if(String(row[12]||"").trim().toUpperCase()!=="WIFE_CALENDAR")return;
        const key=crmV4713NormSourceId(row[13]);
        if(key)bookingIds.add(key);
      });
    }
    const clientCounts=crmV4721ClientNameCounts(ss);
    const timeZone=ss.getSpreadsheetTimeZone()||"Europe/Warsaw";
    const rows=review.getRange(2,1,review.getLastRow()-1,Math.max(9,review.getLastColumn())).getValues();
    let toIdentify=0,toComplete=0,toCheck=0,wifeReviewRows=0,booksyReviewRows=0,hardBlocks=0,alreadyVisits=0;
    const items=[];
    rows.forEach(function(row){
      const type=String(row[1]||"").trim().toUpperCase();
      if(type==="BOOKSY_GMAIL"){booksyReviewRows++;return;}
      if(type!=="WIFE_CALENDAR")return;
      wifeReviewRows++;
      const raw=String(row[8]||row[4]||"").trim();
      if(crmV4714HardBlockLabel(raw)){hardBlocks++;return;}
      const sourceId=String(row[2]||"").trim();
      const key=crmV4713NormSourceId(sourceId);
      if(key&&bookingIds.has(key)){alreadyVisits++;return;}

      const queueItem={sourceId:sourceId,client:String(row[4]||"").trim(),service:String(row[6]||"").trim(),start:row[7]||"",raw:raw};
      const sourceLookup=crmV4722GetSourceEventReadOnly(sourceCal,sourceId);
      const parseEvent=sourceLookup.event||crmV4720FakeEventFromReview(ss,queueItem);
      const parsed=testParseExternalCalendarEvent(parseEvent,ss);
      const resolvedClient=crmV4722ResolveClient(parsed,queueItem.client,clientCounts);
      const classInfo=crmV4721ReviewClass(parsed,queueItem.client,clientCounts);
      if(classInfo.code==="DO_ZIDENTYFIKOWANIA_KLIENTA")toIdentify++;
      else if(classInfo.code==="DO_UZUPELNIENIA_USLUGI"||classInfo.code==="DO_UZUPELNIENIA_TERMINU")toComplete++;
      else toCheck++;

      const sourceStart=sourceLookup.event?sourceLookup.event.getStartTime():(row[7]||"");
      let startIso="";
      if(sourceStart instanceof Date && !isNaN(sourceStart.getTime())) startIso=formatDateToISOString(sourceStart,timeZone);
      else if(sourceStart){
        const dt=new Date(sourceStart);
        if(!isNaN(dt.getTime())) startIso=formatDateToISOString(dt,timeZone);
        else startIso=String(sourceStart||"").trim();
      }
      items.push({
        sourceId:sourceId,
        clientName:String(resolvedClient.name||parsed.name||row[4]||"").trim(),
        service:String(parsed.service||row[6]||"").trim(),
        reason:String(parsed.matchReason||row[3]||"").trim(),
        rawText:raw,startIso:startIso,
        queueClass:classInfo.code,queueLabel:classInfo.label,
        parsedName:String(parsed.name||""),parsedServiceRaw:String(parsed.serviceRaw||""),
        sourceNote:String(parsed.sourceNote||""),relationNote:String(parsed.relationNote||""),
        parserRule:String(parsed.parserRuleV4721||""),clientIdentitySource:String(resolvedClient.source||""),
        sourceEventFound:Boolean(sourceLookup.event),sourceEventLookupError:String(sourceLookup.error||""),
        sourceDurationMinutes:sourceLookup.event?Math.max(0,Math.round((sourceLookup.event.getEndTime()-sourceLookup.event.getStartTime())/60000)):0
      });
    });
    items.sort(function(a,b){
      const at=Date.parse(a.startIso||"")||0,bt=Date.parse(b.startIso||"")||0;
      return at-bt || String(a.clientName||a.rawText||"").localeCompare(String(b.clientName||b.rawText||""),"pl");
    });
    const pendingTotal=toIdentify+toComplete+toCheck;
    return createJsonResponse({
      success:true,version:"4.7.22",toIdentify:toIdentify,toComplete:toComplete,toCheck:toCheck,pendingTotal:pendingTotal,
      wifeReviewRows:wifeReviewRows,booksyReviewRows:booksyReviewRows,totalReviewRows:rows.length,
      hardBlocks:hardBlocks,alreadyVisits:alreadyVisits,sourceCalendarReadOnly:true,items:items
    });
  }catch(error){return createJsonResponse({success:false,error:error.toString(),version:"4.7.22",items:[]});}
}

function confirmExternalReviewAsVisitV4715Action(ss, postData){
  const lock=LockService.getScriptLock();
  if(!lock.tryLock(5000))return createJsonResponse({success:false,busy:true,error:"Inna operacja review jest w toku"});
  try{
    const sourceId=String(postData.sourceId||"").trim();
    const eventId=String(postData.eventId||"").trim().replace(/@google\.com$/i,"");
    const clientName=testNormalizeName(postData.clientName||"");
    const serviceName=testNormalizeName(postData.service||"");
    const note=String(postData.note||"").trim();
    if(!sourceId||!eventId)return createJsonResponse({success:false,error:"Brak SourceId lub Event ID"});
    if(!clientName)return createJsonResponse({success:false,error:"Wybierz lub wpisz klienta przed potwierdzeniem"});
    if(!serviceName)return createJsonResponse({success:false,error:"Wybierz procedurę z Cennika DOM przed potwierdzeniem"});

    const reviewHit=crmV4715FindReviewRow(ss,sourceId);
    if(!reviewHit)return createJsonResponse({success:false,error:"Ten wpis nie znajduje się już w kolejce do sprawdzenia"});
    const reviewRow=reviewHit.data;
    if(String(reviewRow[1]||"").trim().toUpperCase()!=="WIFE_CALENDAR")return createJsonResponse({success:false,error:"Potwierdzenie dotyczy tylko wpisów Google Calendar/WIFE"});
    const raw=String(reviewRow[8]||"");
    const hard=crmV4714HardBlockLabel(raw);
    if(hard)return createJsonResponse({success:false,error:"To jest rozpoznana blokada czasu ("+hard+"), a nie wizyta do potwierdzenia"});

    const service=crmV4715ExactDomService(ss,serviceName);
    if(!service)return createJsonResponse({success:false,error:"Procedura musi być wybrana dokładnie z Cennika DOM"});

    const settings=getDynamicSettings(ss);
    const calendar=CalendarApp.getCalendarById(settings.calendar_id||"");
    if(!calendar)return createJsonResponse({success:false,error:"Brak kalendarza CRM TEST"});
    const blockEvent=calendar.getEventById(eventId);
    if(!blockEvent)return createJsonResponse({success:false,error:"Nie znaleziono kopii blokady CRM"});
    const meta=crmV4713CalendarMeta(String(blockEvent.getDescription()||""));
    if(String(meta.sourceType||"").trim().toUpperCase()!=="WIFE_CALENDAR_BLOCK")return createJsonResponse({success:false,error:"Wybrane wydarzenie nie jest kopią WIFE_CALENDAR_BLOCK"});
    if(crmV4713NormSourceId(meta.sourceId)!==crmV4713NormSourceId(sourceId))return createJsonResponse({success:false,error:"SourceId wydarzenia nie pasuje do rekordu review"});

    const existing=crmV4715FindWifeVisitBySourceId(ss,sourceId);
    if(existing){
      try{blockEvent.deleteEvent();}catch(ignore){}
      try{reviewHit.sheet.deleteRow(reviewHit.rowNo);}catch(ignore){}
      return createJsonResponse({success:true,alreadyConfirmed:true,appointmentId:existing.appointmentId,eventId:existing.eventId,sourceCalendarTouched:false,readOnlySource:true});
    }

    const start=blockEvent.getStartTime();
    const end=blockEvent.getEndTime();
    const booksyOverlaps=testBooksyOverlapsV475(ss,start,end);
    if(booksyOverlaps&&booksyOverlaps.length){
      return createJsonResponse({
        success:false,criticalConflict:true,
        error:"Konflikt z Booksy — nie można automatycznie potwierdzić tej wizyty.",
        conflicts:booksyOverlaps.map(function(x){return {name:x.name||"",start:x.start||"",service:x.service||""};})
      });
    }

    const serviceObj={
      name:service.name,serviceId:service.serviceId||"",category:service.category||"",
      price:Number(service.price)||0,duration:Number(service.duration)||0,
      confidence:"RĘCZNE_POTWIERDZENIE",rawFragment:serviceName,
      returnDays:Number(service.returnDays)||0,catalogSource:"CRM",hasCrmEntry:true
    };
    const sourceNote=[raw,note?"Notatka CRM: "+note:"","Potwierdzono ręcznie w ADMINIE z kolejki DO SPRAWDZENIA."].filter(Boolean).join("\n");
    const result=testCreateVisit(ss,{
      name:clientName,phone:String(reviewRow[5]||""),sourceType:"WIFE_CALENDAR",sourceId:sourceId,
      start:start,end:end,services:[serviceObj],service:service.name,category:service.category||"",
      price:Number(service.price)||0,priceSource:"CENNIK_CRM",status:"POTWIERDZONA",
      operationType:"REVIEW_CONFIRMED",sourceNote:sourceNote
    },true);
    if(!result||!result.appointmentId||!result.eventId)throw new Error("Nie udało się utworzyć kompletnej wizyty CRM");

    const bookings=ss.getSheetByName(SHEET_BOOKINGS);
    if(bookings&&bookings.getLastRow()>1){
      const ids=bookings.getRange(2,10,bookings.getLastRow()-1,1).getValues().flat().map(String);
      const idx=ids.indexOf(String(result.appointmentId));
      if(idx>=0){
        const rowNo=idx+2;
        bookings.getRange(rowNo,9).setValue("POTWIERDZONA");
        bookings.getRange(rowNo,11).setValue("NIE");
      }
    }

    crmV4715UpdateImportLogResolved(ss,sourceId,result,clientName,service.name,service.price);
    try{blockEvent.deleteEvent();}catch(ignore){}
    try{reviewHit.sheet.deleteRow(reviewHit.rowNo);}catch(ignore){}

    return createJsonResponse({
      success:true,version:"4.7.19",confirmed:true,appointmentId:result.appointmentId,eventId:result.eventId,
      clientName:clientName,service:service.name,category:service.category||"",price:Number(service.price)||0,
      start:start,end:end,sourceId:sourceId,readOnlySource:true,sourceCalendarTouched:false,
      clientCreatedOrLinked:true,reviewRemoved:true
