function crmE2EInspectAction(ss, postData) {
  try {
    const marker = crmE2EValidateMarker(postData.marker);
    const sheetNames = [
      SHEET_BOOKINGS,
      SHEET_CUSTOMERS,
      "Prośby o wizytę",
      SHEET_VISIT_HISTORY,
      SHEET_CLIENT_RESTRICTIONS,
      SHEET_CONTACT_REQUESTS,
      "Do weryfikacji TEST"
    ];
    const sheets = {};
    let totalRows = 0;

    sheetNames.forEach(function(name) {
      const sheet = ss.getSheetByName(name);
      const matches = [];
      if (sheet && sheet.getLastRow() > 1) {
        const width = Math.max(1, sheet.getLastColumn());
        const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, width).getValues();
        rows.forEach(function(row, index) {
          if (!crmE2ERowContainsMarker(row, marker)) return;
          matches.push({
            row: index + 2,
            values: row.map(function(value) {
              if (value instanceof Date) return crmE2EFormatLocal(ss, value);
              return value;
            }).slice(0, 20)
          });
        });
      }
      sheets[name] = { count: matches.length, rows: matches.slice(0, 20) };
      totalRows += matches.length;
    });

    const settings = getDynamicSettings(ss);
    const calendar = CalendarApp.getCalendarById(settings.calendar_id || "");
    const calendarEvents = [];
    if (calendar) {
      const now = new Date();
      const from = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 2, 0, 0, 0);
      const to = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 130, 23, 59, 59);
      calendar.getEvents(from, to).forEach(function(event) {
        const text = String(event.getTitle() || "") + "\n" + String(event.getDescription() || "");
        if (text.indexOf(marker) === -1) return;
        calendarEvents.push({
          eventId: event.getId(),
          title: event.getTitle(),
          start: crmE2EFormatLocal(ss, event.getStartTime()),
          end: crmE2EFormatLocal(ss, event.getEndTime())
        });
      });
    }

    return createJsonResponse({
      success: true,
      marker: marker,
      totalRows: totalRows,
      sheets: sheets,
      calendarEvents: calendarEvents,
      calendarEventCount: calendarEvents.length
    });
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  }
}

function crmE2ECleanupAction(ss, postData) {
  try {
    const marker = crmE2EValidateMarker(postData.marker);
    const lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try {
      const deleted = { rows: {}, calendarEvents: 0 };
      const eventIds = new Set();
      const sheetNames = [
        SHEET_BOOKINGS,
        SHEET_CUSTOMERS,
        "Prośby o wizytę",
        SHEET_VISIT_HISTORY,
        SHEET_CLIENT_RESTRICTIONS,
        SHEET_CONTACT_REQUESTS,
        "Do weryfikacji TEST"
      ];

      sheetNames.forEach(function(name) {
        const sheet = ss.getSheetByName(name);
        let count = 0;
        if (sheet && sheet.getLastRow() > 1) {
          const width = Math.max(1, sheet.getLastColumn());
          const rows = sheet.getRange(2, 1, sheet.getLastRow() - 1, width).getValues();
          for (let i = rows.length - 1; i >= 0; i--) {
            if (!crmE2ERowContainsMarker(rows[i], marker)) continue;

            // V4.7.17: cleanup E2E nigdy nie usuwa klienta Booksy.
            // Gdyby wskutek błędu testera marker trafił do istniejącego rekordu Booksy,
            // test ma zgłosić pozostałość zamiast skasować prawdziwe dane klienta.
            if (name === SHEET_CUSTOMERS) {
              const testPhone = String(rows[i][0] || "");
              const testName = String(rows[i][1] || "");
              const source = String(rows[i][6] || "").trim().toUpperCase();
              const explicitlyOwned = testPhone.indexOf(marker) !== -1 || testName.indexOf(marker) !== -1;
              if (!explicitlyOwned || source.indexOf("BOOKSY") !== -1) continue;
            }

            if (name === SHEET_BOOKINGS && rows[i][6]) eventIds.add(String(rows[i][6]).trim());
            sheet.deleteRow(i + 2);
            count++;
          }
        }
        deleted.rows[name] = count;
      });

      const settings = getDynamicSettings(ss);
      const calendar = CalendarApp.getCalendarById(settings.calendar_id || "");
      if (calendar) {
        eventIds.forEach(function(eventId) {
          if (!eventId) return;
          try {
            const event = calendar.getEventById(eventId);
            if (event) {
              const text = String(event.getTitle() || "") + "\n" + String(event.getDescription() || "");
              if (text.indexOf(marker) !== -1) {
                event.deleteEvent();
                deleted.calendarEvents++;
              }
            }
          } catch (ignore) {}
        });

        const now = new Date();
        const from = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 2, 0, 0, 0);
        const to = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 130, 23, 59, 59);
        calendar.getEvents(from, to).forEach(function(event) {
          const text = String(event.getTitle() || "") + "\n" + String(event.getDescription() || "");
          if (text.indexOf(marker) === -1) return;
          try {
            event.deleteEvent();
            deleted.calendarEvents++;
          } catch (ignore) {}
        });
      }

      try { synchronizeCustomerStatistics(ss); } catch (ignore) {}

      return createJsonResponse({ success: true, marker: marker, deleted: deleted });
    } finally {
      try { lock.releaseLock(); } catch (ignore) {}
    }
  } catch (error) {
    return createJsonResponse({ success: false, error: error.toString() });
  }
}
