function testMeaningfulTokensV47(v){
  const stop=new Set(["i","oraz","z","ze","na","do","lub","albo","sama","sam","same","tylko","plus"]);
  return testFoldV47(v).split(" ").filter(x=>x.length>1&&!stop.has(x));
}

function testMatchServicesV47(ss,rawService){
  const raw=String(rawService||"").trim();
  const folded=testFoldV47(raw);
  const catalog=testServiceCatalogV47(ss);
  const hits=[];
  catalog.forEach(item=>{
    (item.aliases||[item.name]).forEach(alias=>{
      const a=testFoldV47(alias);if(!a||a.length<2)return;
      const hay=" "+folded+" ",needle=" "+a+" ";
      let pos=hay.indexOf(needle);
      if(pos>=0)hits.push({
        start:Math.max(0,pos-1),end:Math.max(0,pos-1)+a.length,item,alias:a,len:a.length,
        priority:item.priority||0,
        sourceRank:item.hasCrmEntry?3:(item.catalogSource==="MAP"?2:(item.catalogSource==="BOOKSY_REF"?0:1))
      });
    });
  });
  hits.sort((a,b)=>b.sourceRank-a.sourceRank||b.priority-a.priority||b.len-a.len||a.start-b.start);
  const chosen=[],spans=[];
  hits.forEach(h=>{
    if(chosen.some(x=>testFoldV47(x.item.name)===testFoldV47(h.item.name)))return;
    if(spans.some(s=>h.start<s.end&&h.end>s.start))return;
    chosen.push({item:h.item,alias:h.alias,confidence:"DOKLADNE",start:h.start});spans.push({start:h.start,end:h.end});
  });
  chosen.sort((a,b)=>a.start-b.start);

  if(!chosen.length&&folded){
    const rawTokens=testMeaningfulTokensV47(raw);let best=null;
    catalog.forEach(item=>{
      const candidates=[item.name].concat(item.aliases||[]);
      candidates.forEach(a=>{
        const toks=testMeaningfulTokensV47(a);if(!toks.length)return;
        const overlap=toks.filter(t=>rawTokens.indexOf(t)!==-1).length;
        const score=overlap/Math.max(toks.length,rawTokens.length||1);
        if(overlap>=2&&score>=0.45&&(!best||score>best.score))best={item,score};
      });
    });
    if(best)chosen.push({item:best.item,alias:"",confidence:"PODOBNE",start:0});
  }

  const services=chosen.map(c=>({
    name:c.item.name,serviceId:c.item.serviceId||"",category:c.item.category||"",price:Number(c.item.price)||0,
    duration:Number(c.item.duration)||0,confidence:c.confidence,rawFragment:c.alias||raw,returnDays:Number(c.item.returnDays)||0,
    catalogSource:c.item.catalogSource||"",hasCrmEntry:Boolean(c.item.hasCrmEntry)
  }));
  let remainder=folded;
  chosen.forEach(c=>{if(c.alias)remainder=(" "+remainder+" ").replace(" "+c.alias+" "," ").trim();});
  const leftover=testMeaningfulTokensV47(remainder);
  return {services,unmatched:leftover.join(" "),matched:services.length>0,partial:services.length>0&&leftover.length>0};
}

