function testEnsureClient(ss,name,phone,sourceType,sourceId){
  name=testNormalizeName(name);
  phone=String(phone||"").trim();
  if(!name)return {phone:"",row:-1,source:"",sourceKey:""};

  const sh=ensureCustomerSheet(ss);
  const width=Math.max(9,sh.getLastColumn());
  const rows=sh.getLastRow()>1?sh.getRange(2,1,sh.getLastRow()-1,width).getValues():[];
  const source=crmSourceLabelV4(sourceType);
  const sourceKey=crmSourceKeyV4(sourceType,sourceId);
  const normalizedPhone=phone?normalizeCRMPhone(phone):"";
  let rowIndex=-1;

  for(let i=0;i<rows.length;i++){
    const rowPhone=normalizeCRMPhone(rows[i][0]||"");
    const keys=String(rows[i][7]||"").split("|").map(v=>v.trim()).filter(Boolean);
    if(sourceKey&&keys.indexOf(sourceKey)!==-1){rowIndex=i+2;break;}
    if(normalizedPhone&&rowPhone===normalizedPhone){rowIndex=i+2;break;}
    if(!normalizedPhone){
      const rowName=testNormalizeName(rows[i][1]).toLowerCase();
      const rowSources=String(rows[i][6]||"").toUpperCase().split("+").map(v=>v.trim());
      if(rowName===name.toLowerCase()&&rowSources.indexOf(source)!==-1){rowIndex=i+2;break;}
    }
  }

  const desiredMode = source==="BOOKSY" ? "TYLKO_KONTAKT" : "WYMAGA_POTWIERDZENIA";

  if(rowIndex<0){
    sh.appendRow([normalizedPhone,name,0,0,"",new Date(),source,sourceKey,desiredMode]);
    rowIndex=sh.getLastRow();
  }else{
    const current=sh.getRange(rowIndex,1,1,9).getValues()[0];
    const sources=String(current[6]||"").split("+").map(v=>v.trim()).filter(Boolean);
    if(source&&sources.indexOf(source)===-1)sources.push(source);
    const keys=String(current[7]||"").split("|").map(v=>v.trim()).filter(Boolean);
    if(sourceKey&&keys.indexOf(sourceKey)===-1)keys.push(sourceKey);
    const currentMode=String(current[8]||"").trim().toUpperCase();
    const nextMode=currentMode==="ZABLOKOWANY"
      ? "ZABLOKOWANY"
      : (sources.indexOf("BOOKSY")!==-1 ? "TYLKO_KONTAKT" : (currentMode||desiredMode));

    sh.getRange(rowIndex,1,1,9).setValues([[
      normalizedPhone||current[0]||"",
      name||current[1]||"Klient",
      Number(current[2])||0,
      Number(current[3])||0,
      current[4]||"",
      current[5]||new Date(),
      sources.join("+"),
      keys.join("|"),
      nextMode
    ]]);
  }

  if(source==="BOOKSY"&&normalizedPhone){
    try{
      setClientBookingModeInternal(
        ss,
        normalizedPhone,
        "TYLKO_KONTAKT",
        "Klient z Booksy — brak samodzielnej rezerwacji przez CRM",
        "SYSTEM",
        null
      );
    }catch(ignore){}
  }

  return {phone:normalizedPhone,row:rowIndex,source:source,sourceKey:sourceKey};
}

