      if(o.sourceNote)desc.push("Notatka źródłowa: "+o.sourceNote);
      if(o.relationNote)desc.push("Relacja/notatka: "+o.relationNote);
      if(softNoteOnly){
        desc.push("📝 Notatka z kalendarza: "+(o.softNoteText||o.serviceRaw||""));
        desc.push("⚑ Do uzupełnienia przez Darię — NIE jest to status DO_WERYFIKACJI.");
      }

      const ev=cal.createEvent(
        prefix+(o.name||"Klient")+" - "+(displayService||"Wizyta"),
        start,end,
        {description:desc.join("\n")}
      );
      eventId=ev.getId();
