  const wifeSource=String(o.sourceType||"").trim().toUpperCase()==="WIFE_CALENDAR";
  const visitStatus=o.status||(wifeSource?"WYMAGA_POTWIERDZENIA":"POTWIERDZONA");
  const requiresConfirmation=wifeSource?"TAK":"NIE";
