function testParsePolishDateTime(text){
  const re=/(?:poniedziałek|poniedzialek|wtorek|środa|sroda|czwartek|piątek|piatek|sobota|niedziela)?\s*,?\s*(\d{1,2})\s+(stycznia|lutego|marca|kwietnia|maja|czerwca|lipca|sierpnia|września|wrzesnia|października|pazdziernika|listopada|grudnia)\s+(\d{4})\s*,?\s*(\d{1,2}):(\d{2})/gi;
  const out=[];
  const seen=new Set();
  let m;
  while((m=re.exec(String(text||"")))){
    const d=new Date(Number(m[3]),TEST_PL_MONTHS[m[2].toLowerCase()],Number(m[1]),Number(m[4]),Number(m[5]),0,0);
    const key=String(d.getTime());
    if(!seen.has(key)){seen.add(key);out.push(d);}
  }
  return out;
}

