function testCyrillicManiPediV4721(value){
  const clean=testNormalizeName(value||"");
  const hasManicure=/ман[іи]кюр/i.test(clean);
  const hasPedicure=/педикюр/i.test(clean);
  if(!hasManicure&&!hasPedicure)return null;
  let person=clean
    .replace(/ман[іи]кюр/gi," ")
    .replace(/педикюр/gi," ")
    .replace(/[+,&/]/g," ")
    .replace(/\s+(?:і|и|та)\s+/gi," ")
    .replace(/\s+/g," ")
    .trim();
  person=testNormalizeName(person);
  const services=[];
  if(hasManicure)services.push({name:"Manicure",serviceId:"",category:"Manicure",price:0,duration:0,confidence:"KATEGORIA",rawFragment:"манікюр/маникюр",returnDays:0,catalogSource:"WIFE_GENERIC",hasCrmEntry:false});
  if(hasPedicure)services.push({name:"Pedicure",serviceId:"",category:"Pedicure",price:0,duration:0,confidence:"KATEGORIA",rawFragment:"педикюр",returnDays:0,catalogSource:"WIFE_GENERIC",hasCrmEntry:false});
  return {
