}

function testForcePedicureV4710(ss,raw){
  const f=testFoldV47(raw||"");
  if(f.indexOf("stop")===-1)return null;

  if(
    f.indexOf("bez malowania")!==-1 ||
    f.indexOf("bez hybryd")!==-1 ||
    f.indexOf("frezark")!==-1
  ){
    const exact=testSingleExactCrmMatchV4721(ss,"Pedicure - pielęgnacja stóp frezarką, bez hybrydy",raw);
    if(exact)return exact;
  }

  if(
    f.indexOf("hybryd")!==-1 &&
    (f.indexOf("oprac")!==-1 || f.indexOf("pielegn")!==-1)
  ){
    const exact=testSingleExactCrmMatchV4721(ss,"Pedicure - pielęgnacja stóp + hybryda",raw);
    if(exact)return exact;
  }
  return null;
}

function testServiceSuffixSplitV4710(ss,value){
  const words=testNormalizeName(value||"").split(/\s+/).filter(Boolean);
  if(words.length<2)return null;
  let best=null;

  for(let cut=1;cut<words.length;cut++){
    const personPart=testNormalizeName(words.slice(0,cut).join(" "));
    const servicePart=testNormalizeName(words.slice(cut).join(" "));
    const forced=testForcePedicureV4710(ss,servicePart);
    const matched=forced||(servicePart?testMatchServicesV47(ss,servicePart):null);
    if(!matched||!matched.services||!matched.services.length)continue;

    const exact=!matched.partial;
    const score=(exact?10000:0)+(cut*100)+(matched.services.length*10);
    if(!best||score>best.score){
      best={personPart:personPart,serviceRaw:servicePart,matched:matched,score:score};
    }
  }
  return best;
}

function testRelationClientV4710(ss,value){
  const clean=testNormalizeName(value||"");
  const m=clean.match(/^(mama|matka|córka|corka|syn|siostra|brat|żona|zona|mąż|maz)\s+(.+)$/i);
  if(!m)return null;

  const relationRaw=m[1];
  const relation=testFoldV47(relationRaw);
  const rest=testNormalizeName(m[2]);
  const split=testServiceSuffixSplitV4710(ss,rest);
  const personPart=testNormalizeName(split?split.personPart:rest);
  const serviceRaw=testNormalizeName(split?split.serviceRaw:"");
  if(!personPart)return null;

  const displayRelation =
    relation==="corka" ? "Córka" :
    relation==="zona" ? "Żona" :
    relation==="maz" ? "Mąż" :
    relation==="mama" ? "Mama" :
    relation==="matka" ? "Mama" :
    relation==="siostra" ? "Siostra" :
    relation==="brat" ? "Brat" :
    relation==="syn" ? "Syn" : relationRaw;

  const fullCandidate=testNormalizeName(displayRelation+" "+personPart);
  const fullExisting=testExistingClientExactV4710(ss,fullCandidate);
  if(fullExisting){
    return {name:fullExisting,serviceRaw:serviceRaw,relationNote:""};
  }

  if(relation==="mama"||relation==="matka"){
    if(personPart.indexOf(",")!==-1){
      const parts=personPart.split(",");
      const direct=testNormalizeName(parts.shift());
      const relationTail=testNormalizeName(parts.join(","));
      const directExisting=testExistingClientExactV4710(ss,direct);
      return {
        name:directExisting||direct||fullCandidate,
        serviceRaw:serviceRaw,
        relationNote:testNormalizeName("mama "+relationTail)
      };
    }
    // "mama Karoliny Rysiak" = osobny klient o nieznanym imieniu.
    return {name:fullCandidate,serviceRaw:serviceRaw,relationNote:""};
  }

  const underlyingExisting=testExistingClientExactV4710(ss,personPart);
  return {name:underlyingExisting||personPart,serviceRaw:serviceRaw,relationNote:""};
}

function testIsSoftCalendarNoteV4710(value){
  const f=testFoldV47(value||"");
  return /^onycholiza(?:\b|$)/.test(f);
}

function testPersonTailV4710(ss,value){
  const clean=testNormalizeName(value||"");
  const existing=testExistingClientNamesV473(ss);
  const folded=testFoldV47(clean);

  for(let i=0;i<existing.length;i++){
    const n=existing[i],fn=testFoldV47(n);
    if(folded.indexOf(fn+" ")===0){
      const tail=testNormalizeName(clean.slice(n.length));
      if(tail)return {name:n,tail:tail,soft:testIsSoftCalendarNoteV4710(tail)};
    }
  }

  const words=clean.split(/\s+/).filter(Boolean);
  const personWord=/^[A-ZĄĆĘŁŃÓŚŹŻ][A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż'’.-]*$/;
  let best=null;
  for(let cut=1;cut<Math.min(5,words.length);cut++){
    const nameWords=words.slice(0,cut);
    if(!nameWords.every(function(w){return personWord.test(w);} ))continue;
    const tail=testNormalizeName(words.slice(cut).join(" "));
    if(!tail)continue;
    const forced=testForcePedicureV4710(ss,tail);
    const matched=forced||testMatchServicesV47(ss,tail);
    const soft=testIsSoftCalendarNoteV4710(tail);
    if((matched&&matched.services&&matched.services.length)||soft){
      const score=(soft?20000:10000)+cut*100;
      if(!best||score>best.score)best={name:nameWords.join(" "),tail:tail,soft:soft,score:score};
    }
  }
  return best;
}

function testOdSuffixV4710(ss,value){
  const clean=testNormalizeName(value||"");
  const m=clean.match(/^(.+?)\s+od\s+(.+)$/i);
  if(!m)return null;

  const left=testNormalizeName(m[1]);
  const after=testNormalizeName(m[2]);
  const split=testPersonTailV4710(ss,left);

  // Osoba po "od" to notatka/źródło, a nie klient.
  if(!split)return {name:"",serviceRaw:left,sourceNote:"od "+after,softNoteOnly:false};

  return {
    name:split.name,
    serviceRaw:split.tail,
    sourceNote:"od "+after,
    softNoteOnly:Boolean(split.soft)
  };
}

function testParseExternalCalendarEvent(ev,ss){
  const title=testNormalizeName(ev.getTitle()),desc=String(ev.getDescription()||""),phone=testPhoneFromText(desc),start=ev.getStartTime(),end=ev.getEndTime(),raw=title+"\n"+desc;
  const allDay=Boolean(ev.isAllDayEvent&&ev.isAllDayEvent());
  let clean=title,titleTime="";
  const tm=clean.match(/^(\d{1,2}:\d{2})/);
  if(tm){titleTime=tm[1];clean=testNormalizeName(clean.slice(tm[0].length));}
  // Żona czasem zaczyna wpis od 📍/📌/innego symbolu. Nie może to psuć klasyfikacji.
  clean=testNormalizeName(clean.replace(/^[^0-9A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż\u0400-\u04FF]+/,""));
  // V4.7.14: „może być na rano …” oznacza NIEPEWNY TERMIN. Dane klienta/usługi parsujemy,
  // ale wpis pozostaje blokadą do sprawdzenia i nigdy nie staje się automatycznie wizytą.
  const uncertainTimeNote=/^(?:może być na rano|moze byc na rano|może być rano|moze byc rano)\b/i.test(clean);
  clean=testNormalizeName(clean.replace(/^(?:może być na rano|moze byc na rano|może być rano|moze byc rano)\s+/i,""));

  if(/^brak$/i.test(clean)){
    return {name:"",phone:"",service:"",services:[],start:start,end:end,raw:raw,titleTime:titleTime,skipAutoImport:true,skipReason:"SCHEDULE_MARKER",blockAvailability:false};
  }

  if(allDay){
    return {name:"",phone:"",service:"",services:[],start:start,end:end,raw:raw,titleTime:titleTime,skipAutoImport:true,skipReason:"ALL_DAY_BLOCK",blockAvailability:true};
  }

  if(/^(blokada|wolne|urlop|przerwa|prywatne|nieczynne|stomatolog|dentysta|lekarz|szkolenie|kurs|warsztat)\b/i.test(clean)){
    return {name:"",phone:"",service:"",services:[],start:start,end:end,raw:raw,titleTime:titleTime,skipAutoImport:true,skipReason:"NON_CLIENT_BLOCK",blockAvailability:true};
  }

  let name="",serviceRaw="",nameReview=false,nameReviewReason="";
  let sourceNote="",relationNote="",softNoteOnly=false;
  let forcedServicesV4721=null,forceReviewOnlyV4721=false,parserRuleV4721="";

  const separated=clean.split(/\s+-\s+/);
  if(separated.length>=2){
    name=testNormalizeName(separated.shift());
    serviceRaw=testNormalizeName(separated.join(" - "));
  }else{
    const prefixed=testServicePrefixClientV4721(ss,clean);
    if(prefixed){
      name=prefixed.name||"";
      serviceRaw=prefixed.serviceRaw||"";
      parserRuleV4721=prefixed.rule||"";
    }

    if(!name){
      const cyr=testCyrillicManiPediV4721(clean);
      if(cyr&&cyr.name){
        name=cyr.name||"";
        serviceRaw=cyr.serviceRaw||"";
        forcedServicesV4721=cyr.services||[];
        forceReviewOnlyV4721=true; // rozpoznaj dane, ale nie łącz automatycznie klientki zapisanej cyrylicą
        parserRuleV4721=cyr.rule||"";
        if(cyr.onePartName){
          nameReview=true;
          nameReviewReason="Klient zapisany tylko jednym członem nazwy — bez automatycznego łączenia";
        }
      }
    }

    if(!name){
      const rel=testRelationClientV4710(ss,clean);
      if(rel){
        name=rel.name||"";
        serviceRaw=rel.serviceRaw||"";
        relationNote=rel.relationNote||"";
      }
    }

    if(!name){
      const existing=testExistingClientNamesV473(ss);
      const folded=testFoldV47(clean);
      for(let i=0;i<existing.length;i++){
        const fn=testFoldV47(existing[i]);
        if(folded===fn||folded.indexOf(fn+" ")===0){
          name=existing[i];
          serviceRaw=testNormalizeName(clean.slice(existing[i].length));
          break;
        }
      }
    }

    if(!name && /\s+od\s+/i.test(clean)){
      const od=testOdSuffixV4710(ss,clean);
      if(od){
        name=od.name||"";
        serviceRaw=od.serviceRaw||"";
        sourceNote=od.sourceNote||"";
        softNoteOnly=Boolean(od.softNoteOnly);
      }
    }

    if(!name){
      const pt=testPersonTailV4710(ss,clean);
      if(pt&&pt.soft){
        name=pt.name||"";
        serviceRaw=pt.tail||"";
        softNoteOnly=true;
      }
    }

    if(!name && testLooksLikePersonOnlyV474(clean)){
      name=testNormalizeName(clean);
      serviceRaw="";
      nameReview=true;
      nameReviewReason="Wpis wygląda jak sam klient bez podanej usługi";
    }

    if(!name){
      const words=clean.split(/\s+/).filter(Boolean);
      const personWord=/^[A-ZĄĆĘŁŃÓŚŹŻ][A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż'’.-]*$/;
      const serviceStarts=new Set([
        "hybryda","zel","żel","pedicure","manicure","laminacja","brwi","rzesy","rzęsy",
        "uzupelnienie","uzupełnienie","set","rece","ręce","stopy","henna","regulacja",
        "depilacja","ibx","masaz","masaż","lifting","naprawa"
      ].map(testFoldV47));
      let cut=0;
      while(cut<Math.min(4,words.length-1)){
        if(cut>0&&serviceStarts.has(testFoldV47(words[cut])))break;
        if(!personWord.test(words[cut]))break;
        cut++;
      }
      if(cut>=2){
        name=testNormalizeName(words.slice(0,cut).join(" "));
        serviceRaw=testNormalizeName(words.slice(cut).join(" "));
      }else if(cut===1&&words.length>=2){
        name=testNormalizeName(words[0]);
        serviceRaw=testNormalizeName(words.slice(1).join(" "));
        nameReview=true;
        nameReviewReason="Klient zapisany tylko jednym członem nazwy";
      }
    }
  }

  const sm=desc.match(/(?:Usługa|Usluga|Zabieg|Service)\s*:\s*([^\n]+)/i);
  if(sm){
    serviceRaw=testNormalizeName(sm[1]);
    softNoteOnly=false;
  }

  if(testIsSoftCalendarNoteV4710(serviceRaw)){
    softNoteOnly=true;
  }

  let services=[],matchReview=false,matchReason="";

  if(!softNoteOnly){
    if(forcedServicesV4721&&forcedServicesV4721.length){
      services=forcedServicesV4721;
      matchReview=true;
      matchReason="Rozpoznano kategorie Manicure/Pedicure z wpisu cyrylicą — wybierz dokładne procedury DOM";
    }else{
      const forcedPedicure=testForcePedicureV4710(ss,serviceRaw||"");
      const multi=forcedPedicure&&forcedPedicure.services&&forcedPedicure.services.length
        ? null
        : (serviceRaw?testMatchServiceFragmentsV474(ss,serviceRaw):null);
      const matched=forcedPedicure&&forcedPedicure.services&&forcedPedicure.services.length
        ? forcedPedicure
        : (!multi&&serviceRaw?testMatchServicesV47(ss,serviceRaw):{services:[],unmatched:"",matched:false,partial:false});

      services=multi?multi.services:(matched.services||[]);
      matchReview=Boolean(multi&&multi.review);
      matchReason=multi&&multi.reasons?multi.reasons.join("; "):"";

      if(serviceRaw&&!services.length){
      const rawParts=testRawServiceFragmentsV472(serviceRaw);
      services=rawParts.map(function(part){
        return {
          name:part,serviceId:"",category:"DO_WERYFIKACJI",price:0,
          duration:rawParts.length===1?Math.max(5,Math.round((end-start)/60000)):0,
          confidence:"RAW",rawFragment:part,returnDays:0,catalogSource:"RAW",hasCrmEntry:false
        };
      });
      matchReview=true;
      matchReason=rawParts.length>1
        ?"Rozpoznano kilka fragmentów usługi, ale nie dopasowano ich do Cennik CRM"
        :"Nie dopasowano usługi do Cennik CRM";
      }else if(!multi&&matched.partial){
        matchReview=true;
        matchReason="Dopasowano tylko część opisu usługi: "+matched.unmatched;
      }
    }

    if(services.some(function(s){return !s.hasCrmEntry&&s.catalogSource!=="RAW"&&s.catalogSource!=="WIFE_GENERIC";})){
      matchReview=true;
      matchReason+=(matchReason?"; ":"")+"Usługa rozpoznana referencyjnie, ale brak jej w głównym Cennik CRM — cena DOM pozostaje 0 do uzupełnienia";
    }
  }

  if(nameReview && !softNoteOnly){
    matchReview=true;
    matchReason+=(matchReason?"; ":"")+nameReviewReason;
  }

  const combined=softNoteOnly
    ? ("📝 "+testNormalizeName(serviceRaw||"notatka"))
    : (services.map(function(s){return s.name;}).join(" + ")||serviceRaw);

  const softNoteText=softNoteOnly
    ? [testNormalizeName(serviceRaw||""),testNormalizeName(sourceNote||""),testNormalizeName(relationNote||"")].filter(Boolean).join(" ")
    : "";

  const totalPrice=softNoteOnly?0:services.reduce(function(a,s){return a+(Number(s.price)||0);},0);
  const catalogDuration=softNoteOnly?0:services.reduce(function(a,s){return a+(Number(s.duration)||0);},0);
  const actualDuration=Math.max(5,Math.round((end-start)/60000));
  if(!softNoteOnly&&catalogDuration>0&&Math.abs(catalogDuration-actualDuration)>5){
    matchReview=true;
    matchReason+=(matchReason?"; ":"")+("Czas wydarzenia "+actualDuration+" min różni się od sumy cennika "+catalogDuration+" min");
  }

  let titleTimeMismatchMinutes=0;
  if(titleTime&&start instanceof Date&&!isNaN(start)){
    const hm=titleTime.split(":").map(Number);
    titleTimeMismatchMinutes=Math.abs((start.getHours()*60+start.getMinutes())-(hm[0]*60+hm[1]));
  }

  if(uncertainTimeNote){
    matchReview=true;
    matchReason+=(matchReason?"; ":"")+"Niepewny termin: wpis zawiera „może być na rano” — zachowano dane, ale czas wymaga sprawdzenia";
  }
  const skipAutoImport=Boolean(forceReviewOnlyV4721||uncertainTimeNote||!name||(!serviceRaw&&!softNoteOnly));
  if(skipAutoImport && name && !serviceRaw){
    matchReview=true;
    matchReason+=(matchReason?"; ":"")+"Brak usługi — czas zostanie tylko zablokowany";
  }

  return {
    name:name,phone:phone,service:combined,serviceRaw:serviceRaw,services:services,totalPrice:totalPrice,catalogDuration:catalogDuration,start:start,end:end,raw:raw,titleTime:titleTime,
    titleTimeMismatchMinutes:titleTimeMismatchMinutes,matchReview:matchReview,matchReason:matchReason,skipAutoImport:skipAutoImport,
    skipReason:skipAutoImport?(uncertainTimeNote?"UNCERTAIN_TIME_NOTE":(name?"MISSING_SERVICE":"UNPARSED_CLIENT")):"",
    blockAvailability:skipAutoImport,uncertainTimeNote:Boolean(uncertainTimeNote),
    sourceNote:sourceNote,relationNote:relationNote,softNoteOnly:softNoteOnly,softNoteText:softNoteText,
    parserRuleV4721:parserRuleV4721,forceReviewOnlyV4721:Boolean(forceReviewOnlyV4721)
  };
}

