function testBooksyOverlapsV475(ss,start,end){
  const out=[];
  if(!(start instanceof Date)||isNaN(start)||!(end instanceof Date)||isNaN(end))return out;
  const sh=ss.getSheetByName(SHEET_BOOKINGS);
  if(!sh||sh.getLastRow()<2)return out;
  const rows=sh.getRange(2,1,sh.getLastRow()-1,Math.max(22,sh.getLastColumn())).getValues();
  rows.forEach(r=>{
    if(String(r[12]||"").trim()!=="BOOKSY_GMAIL")return;
    if(String(r[8]||"").toUpperCase().indexOf("ANULOWANA")===0)return;
    const s=r[0] instanceof Date?r[0]:new Date(r[0]);
    if(isNaN(s))return;
    const e=new Date(s.getTime()+(Number(r[7])||45)*60000);
    if(start<e&&end>s){
      out.push({
        appointmentId:String(r[9]||""),
        calendarEventId:String(r[6]||""),
        name:String(r[2]||""),
        service:String(r[3]||""),
        start:s,end:e
      });
    }
  });
  return out;
}

