          const ambiguous=o.skipReason==="UNPARSED_CLIENT"||o.skipReason==="MISSING_SERVICE"||o.skipReason==="AMBIGUOUS_NAME"||o.skipReason==="UNCERTAIN_TIME_NOTE";
          const knownBits=[String(o.name||"").trim(),String(o.service||"").trim()].filter(Boolean);
          const originalTitle=String(ev.getTitle()||"").replace(/^\s*\d{1,2}:\d{2}\s*/,"").trim();
          const meaningful=knownBits.length?knownBits.join(" — "):originalTitle;
          const blockLabel=ambiguous
            ?("⚠️ "+(meaningful||"Do sprawdzenia"))
            :(o.skipReason==="NON_CLIENT_BLOCK"?("▲ "+(originalTitle||"Blokada czasu")):("▲ "+(meaningful||"Blokada czasu")));
          const br=testMirrorWifeBusyBlockV472(ss,ev,sid,blockLabel);
          blocked++;
          if(ambiguous)review++;
          const blockReviewReason=ambiguous
            ?(o.matchReason|| (o.skipReason==="UNCERTAIN_TIME_NOTE"?"Niepewny termin — czas został zablokowany do sprawdzenia":"Nie rozpoznano bezpiecznie klienta/usługi — czas został tylko zablokowany w CRM"))
            :"";
          testLogImport(ss,{
            type:"WIFE_CALENDAR",id:sid,status:ambiguous?"WYMAGA_WERYFIKACJI":"OK",
            action:"MIRROR_BUSY_READ_ONLY",calendarEventId:br.eventId,name:o.name,phone:o.phone,service:o.service,
            start:o.start,end:o.end,raw:o.raw,review:ambiguous,reviewReason:blockReviewReason
          });
          processed.add(String(sid));
        }
        return;
      }
      const mismatch=Number(o.titleTimeMismatchMinutes)||0;if(mismatch>0)timeMismatch++;if((o.services||[]).length>1)multiService++;

      const booksy=testBooksyOverlapsV475(ss,o.start,o.end);
      if(booksy.length){
        const same=booksy.find(b=>testFoldV47(b.name)===testFoldV47(o.name));
        if(same){
          booksyPrioritySkipped++;
          testLogImport(ss,{
            type:"WIFE_CALENDAR",id:sid,status:"POMINIETO_BOOKSY_PRIORYTET",
            action:"SKIP_DUPLICATE_BOOKSY_PRIORITY",appointmentId:same.appointmentId,calendarEventId:same.calendarEventId,
            name:o.name,phone:o.phone,service:o.service,start:o.start,end:o.end,price:o.totalPrice,raw:o.raw,review:false,
            reviewReason:"Ta sama klientka ma już wizytę Booksy w tym czasie; Booksy jest źródłem nadrzędnym."
          });
          processed.add(String(sid));
          return;
        }
        booksy.forEach(b=>testLogWifeBooksyConflictV475(ss,sid,o,b));
        booksyConflicts+=booksy.length;
        review++;
        testLogImport(ss,{
          type:"WIFE_CALENDAR",id:sid,status:"WYMAGA_WERYFIKACJI",
          action:"CONFLICT_BOOKSY_PRIORITY",name:o.name,phone:o.phone,service:o.service,
          start:o.start,end:o.end,price:o.totalPrice,raw:o.raw,review:true,
          reviewReason:"W tym czasie istnieje inna aktywna wizyta Booksy. Booksy ma priorytet; nie utworzono drugiej wizyty."
        });
        processed.add(String(sid));
        return;
      }

      const needsReview=Boolean(mismatch>0||o.matchReview);if(needsReview)review++;
      const allCrmServices=(o.services||[]).length>0&&(o.services||[]).every(s=>Boolean(s.hasCrmEntry)&&String(s.catalogSource||"").toUpperCase()!=="BOOKSY_REF"&&String(s.confidence||"")!=="RAW");
      const wifePriceSource=o.softNoteOnly?"NOTATKA_KALENDARZA":(allCrmServices&&!o.matchReview?"CENNIK_CRM":"DO_WERYFIKACJI");
      const r=testCreateVisit(ss,{...o,sourceType:"WIFE_CALENDAR",sourceId:sid,price:o.totalPrice,priceSource:wifePriceSource},true);created++;
      const reasons=[];if(mismatch>0)reasons.push("Godzina wpisana w tytule różni się od rzeczywistej godziny wydarzenia");if(o.matchReview&&o.matchReason)reasons.push(o.matchReason);
      testLogImport(ss,{type:"WIFE_CALENDAR",id:sid,status:needsReview?"WYMAGA_WERYFIKACJI":"OK",action:"IMPORT_READ_ONLY",appointmentId:r.appointmentId,calendarEventId:r.eventId,name:o.name,phone:o.phone,service:o.service,start:o.start,end:o.end,price:o.totalPrice,raw:o.raw,review:needsReview,reviewReason:reasons.join("; ")});
      processed.add(String(sid));
    });
    return createJsonResponse({success:true,created,skipped,ignored,blocked,review,timeMismatch,multiService,booksyPrioritySkipped,booksyConflicts,from,to,readOnly:true,mirroredToCrmCalendar:true,version:"4.7.13"});
  }catch(e){return createJsonResponse({success:false,error:e.toString()});}
}

