  try{
    testResetRuntimeCacheV473();
    const settings=getDynamicSettings(ss);
    const sourceId=String((p&&p.calendarId)||settings.wife_calendar_id||"");
    if(!sourceId)throw new Error("Brak wife_calendar_id");
    const sourceCal=CalendarApp.getCalendarById(sourceId);
    if(!sourceCal)throw new Error("Nie znaleziono źródłowego kalendarza żony");
    const crmCal=settings.calendar_id?CalendarApp.getCalendarById(settings.calendar_id):null;

    const sh=ensureExtendedBookingColumns(ss);
    if(sh.getLastRow()<2)return createJsonResponse({success:true,repaired:0,removedBlocks:0,duplicatesBooksy:0,conflicts:0});

    const rows=sh.getRange(2,1,sh.getLastRow()-1,Math.max(22,sh.getLastColumn())).getValues();
    const toDelete=[];
    let repaired=0,removedBlocks=0,duplicatesBooksy=0,conflicts=0,missingSource=0,calendarUpdated=0,review=0;

    rows.forEach(function(row,idx){
      if(String(row[12]||"").trim()!=="WIFE_CALENDAR")return;
      const sheetRow=idx+2;
      const sid=String(row[13]||"").trim();
      const appointmentId=String(row[9]||"").trim();
      const oldEventId=String(row[6]||"").replace(/@google\.com$/,"");
      let ev=null;
      try{if(sid)ev=sourceCal.getEventById(String(sid).replace(/@google\.com$/,""));}catch(ignore){}
      if(!ev){
        missingSource++;
        sh.getRange(sheetRow,18).setValue("DO_WERYFIKACJI");
        return;
      }

      const parsed=testParseExternalCalendarEvent(ev,ss);

      // Marker Brak/BRAK albo wpis niekliencki: usuń błędną wizytę z DB,
      // usuń tylko jej kopię w CRM i ewentualnie utwórz techniczną blokadę CRM.
      if(parsed.skipAutoImport){
        try{
          if(oldEventId&&crmCal){
            const old=crmCal.getEventById(oldEventId);
            if(old)old.deleteEvent();
          }
        }catch(ignore){}
        testRecordVisitItemsV47(ss,appointmentId,[],"WIFE_CALENDAR");

        if(parsed.blockAvailability){
          const repairBits=[String(parsed.name||"").trim(),String(parsed.service||"").trim()].filter(Boolean);
          const repairOriginal=String(ev.getTitle()||"").replace(/^\s*\d{1,2}:\d{2}\s*/,"").trim();
          testMirrorWifeBusyBlockV472(
            ss,ev,sid,
            parsed.skipReason==="NON_CLIENT_BLOCK"?("▲ "+(repairOriginal||"Blokada czasu")):("⚠️ "+(repairBits.join(" — ")||repairOriginal||"Do sprawdzenia"))
          );
        }
        toDelete.push(sheetRow);
        removedBlocks++;
        return;
      }

      // Booksy ma pierwszeństwo.
      const overlaps=testBooksyOverlapsV475(ss,parsed.start,parsed.end);
      if(overlaps.length){
        const same=overlaps.find(b=>testFoldV47(b.name)===testFoldV47(parsed.name));
        overlaps.forEach(b=>testLogWifeBooksyConflictV475(ss,sid,parsed,b));
        conflicts+=overlaps.length;
        try{
          if(oldEventId&&crmCal){
            const old=crmCal.getEventById(oldEventId);
            if(old)old.deleteEvent();
          }
        }catch(ignore){}
        testRecordVisitItemsV47(ss,appointmentId,[],"WIFE_CALENDAR");
        toDelete.push(sheetRow);
        if(same)duplicatesBooksy++;
        return;
      }

      const services=Array.isArray(parsed.services)?parsed.services.filter(s=>s&&s.name):[];
      const service=services.map(s=>s.name).join(" + ")||parsed.service||"";
      const categories=Array.from(new Set(services.map(s=>String(s.category||"").trim()).filter(Boolean)));
      const totalPrice=services.reduce((sum,s)=>sum+(Number(s.price)||0),0);
      const actualDuration=Math.max(5,Math.round((parsed.end-parsed.start)/60000));
      const allCrm=services.length>0&&services.every(s=>Boolean(s.hasCrmEntry)&&String(s.catalogSource||"").toUpperCase()!=="BOOKSY_REF"&&String(s.confidence||"")!=="RAW");
      const needsReview=Boolean(parsed.matchReview||Number(parsed.titleTimeMismatchMinutes)||!allCrm);
      const priceSource=allCrm&&!parsed.matchReview?"CENNIK_CRM":"DO_WERYFIKACJI";
      const recommended=testRecommendedDateV47(parsed.start,services)||"";

      sh.getRange(sheetRow,1).setValue(parsed.start);
      sh.getRange(sheetRow,3).setValue(parsed.name||row[2]||"");
      sh.getRange(sheetRow,4).setValue(service);
      sh.getRange(sheetRow,8).setValue(actualDuration);
      sh.getRange(sheetRow,9).setValue("WYMAGA_POTWIERDZENIA");
      sh.getRange(sheetRow,11).setValue("TAK");
      sh.getRange(sheetRow,12).setValue(recommended);
      sh.getRange(sheetRow,17).setValue(totalPrice||"");
      sh.getRange(sheetRow,18).setValue(priceSource);
      sh.getRange(sheetRow,19).setValue(categories.join(" + "));

      testRecordVisitItemsV47(
        ss,appointmentId,
        services.map(s=>Object.assign({},s,{priceSource:priceSource})),
        "WIFE_CALENDAR"
      );

      if(crmCal){
        const title=`🏠 ${parsed.name||row[2]||"Klient"} - ${service||"Wizyta"}`;
        const desc=[
          "CRM TEST",
          "Źródło: DOM",
          "SourceId: "+sid,
          "Status: WYMAGA_POTWIERDZENIA",
          "Tryb źródła: WIFE_CALENDAR READ_ONLY",
          "Oryginału w kalendarzu żony nie zmieniono."
        ].join("\n");
        try{
          let crmEvent=oldEventId?crmCal.getEventById(oldEventId):null;
          if(crmEvent){
            crmEvent.setTime(parsed.start,parsed.end);
            crmEvent.setTitle(title);
            crmEvent.setDescription(desc);
