    toDelete.sort((a,b)=>b-a).forEach(r=>sh.deleteRow(r));

    return createJsonResponse({
      success:true,version:"4.7.9",readOnlySource:true,
      repaired,removedBlocks,duplicatesBooksy,conflicts,missingSource,calendarUpdated,review
    });
  }catch(e){
    return createJsonResponse({success:false,error:e.toString(),version:"4.7.9"});
  }finally{
    try{lock.releaseLock();}catch(ignore){}
  }
}
