function testWifeSourceIdFromDescriptionV4710(desc){
  const m=String(desc||"").match(/SourceId:\s*([^\n]+)/i);
  return m?String(m[1]||"").trim():"";
}

function testDeleteCrmEventsV4710(events){
  let count=0;
  (events||[]).forEach(function(ev){
    try{ev.deleteEvent();count++;}catch(ignore){}
  });
  return count;
}

function repairWifeCalendarImportsV4710Action(ss,p){
  const lock=LockService.getScriptLock();
