    const bookingBySid={};
    rows.forEach(function(row,idx){
      if(String(row[12]||"").trim()!=="WIFE_CALENDAR")return;
      const sid=String(row[13]||"").trim();
      if(!sid)return;
      if(!bookingBySid[sid])bookingBySid[sid]=[];
      bookingBySid[sid].push({row:idx+2,data:row});
    });

    const crmEventsBySid={};
    if(crmCal){
      crmCal.getEvents(from,to).forEach(function(ev){
        const desc=String(ev.getDescription()||"");
        if(desc.indexOf("Źródło: WIFE_CALENDAR_BLOCK")===-1 && desc.indexOf("Tryb źródła: WIFE_CALENDAR READ_ONLY")===-1)return;
        const sid=testWifeSourceIdFromDescriptionV4710(desc);
        if(!sid)return;
        if(!crmEventsBySid[sid])crmEventsBySid[sid]=[];
        crmEventsBySid[sid].push(ev);
      });
    }

    const toDeleteRows=[];
    let parsedCount=0,created=0,updated=0,deletedBlocks=0,createdBlocks=0;
    let ignoredMarkers=0,nonClientBlocks=0,ambiguousBlocks=0,softNotes=0;
    let booksySkipped=0,conflicts=0,review=0;

    sourceCal.getEvents(from,to).slice(0,max).forEach(function(ev){
      const sid=String(ev.getId()||"");
      if(!sid)return;
      parsedCount++;

      const parsed=testParseExternalCalendarEvent(ev,ss);
      const existingList=bookingBySid[sid]||[];
      const existing=existingList.length?existingList[0]:null;
      existingList.slice(1).forEach(function(x){toDeleteRows.push(x.row);});
      const crmLinked=crmEventsBySid[sid]||[];

