        if(!existing)return;
        const appointmentId=String(existing.data[9]||"");
        const oldEventId=String(existing.data[6]||"").replace(/@google\.com$/,"");
        if(oldEventId&&crmCal){
          try{
            const oldEvent=crmCal.getEventById(oldEventId);
            if(oldEvent)oldEvent.deleteEvent();
          }catch(ignore){}
        }
        testRecordVisitItemsV47(ss,appointmentId,[],"WIFE_CALENDAR");
        toDeleteRows.push(existing.row);
      }

      function removeCrmCopies(){
        deletedBlocks+=testDeleteCrmEventsV4710(crmLinked);
      }

      if(parsed.skipAutoImport){
        removeExistingVisitRow();
        removeCrmCopies();

        if(parsed.skipReason==="SCHEDULE_MARKER"){
          ignoredMarkers++;
          return;
        }

        if(parsed.blockAvailability&&crmCal){
          const ambiguous=parsed.skipReason==="UNPARSED_CLIENT"||parsed.skipReason==="MISSING_SERVICE"||parsed.skipReason==="AMBIGUOUS_NAME"||parsed.skipReason==="UNCERTAIN_TIME_NOTE";
          const knownBits=[String(parsed.name||"").trim(),String(parsed.service||"").trim()].filter(Boolean);
          const originalTitle=String(ev.getTitle()||"").replace(/^\s*\d{1,2}:\d{2}\s*/,"").trim();
          const meaningful=knownBits.length?knownBits.join(" — "):originalTitle;
