            ?("⚠️ "+(meaningful||"Do sprawdzenia"))
            :(parsed.skipReason==="NON_CLIENT_BLOCK"?("▲ "+(originalTitle||"Blokada czasu")):("▲ "+(meaningful||"Blokada czasu")));
          testMirrorWifeBusyBlockV472(ss,ev,sid,blockLabel);
          createdBlocks++;
          if(ambiguous){ambiguousBlocks++;review++;}
          else nonClientBlocks++;
        }
        return;
      }

      const overlaps=testBooksyOverlapsV475(ss,parsed.start,parsed.end);
      if(overlaps.length){
        removeExistingVisitRow();
        removeCrmCopies();
        const same=overlaps.find(function(b){return testFoldV47(b.name)===testFoldV47(parsed.name);});
        if(same)booksySkipped++;
        else{
          overlaps.forEach(function(b){testLogWifeBooksyConflictV475(ss,sid,parsed,b);});
          conflicts+=overlaps.length;
          review++;
        }
        return;
      }

      removeCrmCopies();

      const services=Array.isArray(parsed.services)?parsed.services.filter(function(s){return s&&s.name;}):[];
      const softNoteOnly=Boolean(parsed.softNoteOnly);
      const displayService=softNoteOnly
        ? ("📝 "+testNormalizeName(parsed.serviceRaw||parsed.softNoteText||"notatka"))
        : (services.map(function(s){return s.name;}).join(" + ")||parsed.service||"");
      const categories=softNoteOnly?[]:Array.from(new Set(services.map(function(s){return String(s.category||"").trim();}).filter(Boolean)));
      const totalPrice=softNoteOnly?0:services.reduce(function(sum,s){return sum+(Number(s.price)||0);},0);
      const actualDuration=Math.max(5,Math.round((parsed.end-parsed.start)/60000));
      const allCrm=services.length>0&&services.every(function(s){
        return Boolean(s.hasCrmEntry)&&String(s.catalogSource||"").toUpperCase()!=="BOOKSY_REF"&&String(s.confidence||"")!=="RAW";
      });
      const needsReview=softNoteOnly
        ? Boolean(Number(parsed.titleTimeMismatchMinutes))
        : Boolean(parsed.matchReview||Number(parsed.titleTimeMismatchMinutes)||!allCrm);
      const priceSource=softNoteOnly?"NOTATKA_KALENDARZA":(allCrm&&!parsed.matchReview?"CENNIK_CRM":"DO_WERYFIKACJI");
      const recommended=softNoteOnly?"":(testRecommendedDateV47(parsed.start,services)||"");

      if(existing){
        const r=existing.row;
        const appointmentId=String(existing.data[9]||"");
        const oldEventId=String(existing.data[6]||"").replace(/@google\.com$/,"");
        if(oldEventId&&crmCal){
          try{
            const oldEvent=crmCal.getEventById(oldEventId);
            if(oldEvent)oldEvent.deleteEvent();
          }catch(ignore){}
