        sh.getRange(r,8).setValue(actualDuration);
        sh.getRange(r,9).setValue("WYMAGA_POTWIERDZENIA");
        sh.getRange(r,11).setValue("TAK");
        sh.getRange(r,12).setValue(recommended);
        sh.getRange(r,17).setValue(totalPrice||"");
        sh.getRange(r,18).setValue(priceSource);
        sh.getRange(r,19).setValue(categories.join(" + "));
        testRecordVisitItemsV47(
          ss,appointmentId,
          softNoteOnly?[]:services.map(function(s){return Object.assign({},s,{priceSource:priceSource});}),
          "WIFE_CALENDAR"
        );

        if(crmCal){
          const desc=[
            "CRM TEST",
            "Źródło: DOM",
            "SourceId: "+sid,
            "Status: WYMAGA_POTWIERDZENIA",
            "Tryb źródła: WIFE_CALENDAR READ_ONLY",
            "Oryginału w kalendarzu żony nie zmieniono."
          ];
          if(parsed.sourceNote)desc.push("Notatka źródłowa: "+parsed.sourceNote);
          if(parsed.relationNote)desc.push("Relacja/notatka: "+parsed.relationNote);
          if(softNoteOnly){
            desc.push("📝 Notatka z kalendarza: "+(parsed.softNoteText||parsed.serviceRaw||""));
            desc.push("⚑ Do uzupełnienia przez Darię — NIE jest to status DO_WERYFIKACJI.");
          }
          const crmEvent=crmCal.createEvent(
            "🏠 "+(parsed.name||existing.data[2]||"Klient")+" - "+(displayService||"Wizyta"),
            parsed.start,parsed.end,{description:desc.join("\n")}
          );
          sh.getRange(r,7).setValue(crmEvent.getId());
        }
        updated++;
      }else{
        testCreateVisit(ss,{
          ...parsed,
          sourceType:"WIFE_CALENDAR",
          sourceId:sid,
          price:totalPrice,
          priceSource:priceSource
        },true);
        created++;
      }

      if(softNoteOnly)softNotes++;
      if(needsReview)review++;
    });

    Array.from(new Set(toDeleteRows)).sort(function(a,b){return b-a;}).forEach(function(r){
      if(r>=2&&r<=sh.getLastRow())sh.deleteRow(r);
    });

    return createJsonResponse({
      success:true,version:"4.7.13",readOnlySource:true,
      from:from,to:to,parsed:parsedCount,created:created,updated:updated,
      deletedBlocks:deletedBlocks,createdBlocks:createdBlocks,ignoredMarkers:ignoredMarkers,
      nonClientBlocks:nonClientBlocks,ambiguousBlocks:ambiguousBlocks,
      softNotes:softNotes,booksySkipped:booksySkipped,conflicts:conflicts,review:review
    });
  }catch(e){
    return createJsonResponse({success:false,error:e.toString(),version:"4.7.13"});
  }finally{
    try{lock.releaseLock();}catch(ignore){}
  }
}

