function rebuildClientStatsTestV43Action(ss,p){
  try{
    const clients=ensureCustomerSheet(ss);
    const visits=ss.getSheetByName(SHEET_BOOKINGS);
    if(clients.getLastRow()<2){
      return createJsonResponse({success:true,updated:0,clients:0,visits:0});
    }

    const clientRows=clients.getRange(2,1,clients.getLastRow()-1,Math.max(9,clients.getLastColumn())).getValues();
    const stats=clientRows.map(()=>({visits:0,cancelled:0,last:null}));

    const findClientIndex=(row)=>{
      const phone=normalizeCRMPhone(row[1]||"");
      const name=testNormalizeName(row[2]||"").toLowerCase();
      const source=crmSourceLabelV4(row[12]||"");

      if(phone){
        for(let i=0;i<clientRows.length;i++){
          if(normalizeCRMPhone(clientRows[i][0]||"")===phone) return i;
        }
      }

      for(let i=0;i<clientRows.length;i++){
        const clientName=testNormalizeName(clientRows[i][1]||"").toLowerCase();
        const sources=String(clientRows[i][6]||"").toUpperCase().split("+").map(v=>v.trim());
        if(clientName===name && sources.indexOf(source)!==-1) return i;
      }
      return -1;
    };

    let visitCount=0;
    if(visits&&visits.getLastRow()>1){
      const rows=visits.getRange(2,1,visits.getLastRow()-1,Math.max(16,visits.getLastColumn())).getValues();
      rows.forEach(row=>{
        const idx=findClientIndex(row);
        if(idx<0) return;
        visitCount++;
        stats[idx].visits++;
        const status=String(row[8]||"").trim().toUpperCase();
        if(status.indexOf("ANULOWANA")===0) stats[idx].cancelled++;

        const d=row[0] instanceof Date ? row[0] : (row[0] ? new Date(row[0]) : null);
        if(d && !isNaN(d.getTime()) && (!stats[idx].last || d.getTime()>stats[idx].last.getTime())){
          stats[idx].last=d;
        }
      });
    }

    for(let i=0;i<stats.length;i++){
      clients.getRange(i+2,3,1,3).setValues([[
        stats[i].visits,
        stats[i].cancelled,
        stats[i].last||""
      ]]);
    }

    return createJsonResponse({
      success:true,
      updated:stats.length,
      clients:clientRows.length,
      visits:visitCount
    });
  }catch(e){
    return createJsonResponse({success:false,error:e.toString()});
  }
}

