function crmNormIdentityTextV4718(value) {
  return String(value || "").trim().toLowerCase().normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ");
}

function crmCustomerRecordFromRowV4718(row, rowNumber) {
  return {
    row: rowNumber,
    phone: normalizeCRMPhone(row[0] || ""),
    name: String(row[1] || "").trim(),
    visits: Number(row[2]) || 0,
    cancelled: Number(row[3]) || 0,
    lastVisit: row[4] || "",
    createdAt: row[5] || "",
    source: String(row[6] || "").trim(),
    sourceKey: String(row[7] || "").trim(),
