  };
}

function crmAllCustomerRecordsV4718(ss) {
  const sh = ss.getSheetByName(SHEET_CUSTOMERS);
  if (!sh || sh.getLastRow() < 2) return [];
  const width = Math.max(9, sh.getLastColumn());
  return sh.getRange(2, 1, sh.getLastRow() - 1, width).getValues()
    .map(function(row, index){ return crmCustomerRecordFromRowV4718(row, index + 2); });
}

function crmFindCustomerByIdentityV4718(ss, identity) {
  const data = identity && typeof identity === "object" ? identity : { phone: identity };
  const phone = normalizeCRMPhone(data.phone || "");
  const sourceKey = String(data.sourceKey || "").trim();
  const nameKey = crmNormIdentityTextV4718(data.name || "");
  const sourceKeyNorm = crmNormIdentityTextV4718(data.source || "");
  const rows = crmAllCustomerRecordsV4718(ss);

  if (phone) {
    const found = rows.find(function(row){ return row.phone === phone; });
    return found ? { found:true, ambiguous:false, customer:found } : { found:false, ambiguous:false, customer:null };
  }

  if (sourceKey) {
    const matches = rows.filter(function(row){ return String(row.sourceKey || "").trim() === sourceKey; });
    if (matches.length === 1) return { found:true, ambiguous:false, customer:matches[0] };
    if (matches.length > 1) return { found:false, ambiguous:true, customer:null, matches:matches };
  }

  if (nameKey && sourceKeyNorm) {
    const matches = rows.filter(function(row){
      return crmNormIdentityTextV4718(row.name) === nameKey &&
             crmNormIdentityTextV4718(row.source) === sourceKeyNorm;
    });
    if (matches.length === 1) return { found:true, ambiguous:false, customer:matches[0] };
    if (matches.length > 1) return { found:false, ambiguous:true, customer:null, matches:matches };
  }

  return { found:false, ambiguous:false, customer:null };
}

function crmClientHistoryByPhoneV4718(ss, phone) {
  const normalized = normalizeCRMPhone(phone || "");
  const history = [];
  if (!normalized) return history;
  const sh = ss.getSheetByName(SHEET_VISIT_HISTORY);
  if (!sh || sh.getLastRow() < 2) return history;
  const rows = sh.getRange(2, 1, sh.getLastRow() - 1, 17).getValues();
  rows.forEach(function(row){
    if (normalizeCRMPhone(row[4]) !== normalized) return;
    history.push({
      date: row[1], operation: String(row[7] || ""), oldDate: row[10], newDate: row[11],
      initiator: String(row[12] || ""), reason: String(row[13] || "")
    });
  });
  return history.slice(-50).reverse();
}

function getClientCRMProfileV4718Action(ss, postData) {
  try {
    const identity = postData.identity || {
      phone: postData.phone || "", sourceKey: postData.sourceKey || "",
      name: postData.name || "", source: postData.source || ""
    };
    const match = crmFindCustomerByIdentityV4718(ss, identity);
    if (match.ambiguous) return createJsonResponse({success:false,code:"AMBIGUOUS_CLIENT",error:"Niejednoznaczny klient — wybierz rekord ręcznie."});
    if (!match.found || !match.customer) return createJsonResponse({success:false,code:"CLIENT_NOT_FOUND",error:"Nie znaleziono klienta."});

    const customer = match.customer;
    let risk = {
      cancellations: Math.max(0, Number(customer.cancelled) || 0),
      reschedules: 0, movedLater: 0, noShows: 0, movedThenCancelled: 0,
      score: 0, level: "STANDARDOWY", suggestedMode: "STANDARDOWY"
    };
    let history = [];
    if (customer.phone) {
      risk = calculateClientRisk(ss, customer.phone);
      history = crmClientHistoryByPhoneV4718(ss, customer.phone);
    }
    const effective = crmEffectiveBookingModeV4(ss, customer);
    const timeZone = ss.getSpreadsheetTimeZone() || "Europe/Warsaw";
    const lastVisitDate = customer.lastVisit instanceof Date ? customer.lastVisit : (customer.lastVisit ? new Date(customer.lastVisit) : null);

