          lastVisit:lastVisitDate && !isNaN(lastVisitDate.getTime()) ? Utilities.formatDate(lastVisitDate,timeZone,"yyyy-MM-dd HH:mm") : "",
          source:customer.source, sourceKey:customer.sourceKey
        },
