      }
    });
  } catch (error) {
    return createJsonResponse({success:false,error:error.toString()});
  }
}

function setClientBookingModeV4718Action(ss, postData) {
  try {
    const allowed = ["STANDARDOWY","WYMAGA_POTWIERDZENIA","REZERWACJA_OGRANICZONA","TYLKO_KONTAKT","ZABLOKOWANY"];
    const mode = String(postData.mode || "").trim().toUpperCase();
    if (allowed.indexOf(mode) === -1) return createJsonResponse({success:false,error:"Nieprawidłowy tryb rezerwacji"});
    const match = crmFindCustomerByIdentityV4718(ss, postData.identity || postData);
    if (match.ambiguous) return createJsonResponse({success:false,code:"AMBIGUOUS_CLIENT",error:"Niejednoznaczny klient."});
    if (!match.found || !match.customer) return createJsonResponse({success:false,code:"CLIENT_NOT_FOUND",error:"Nie znaleziono klienta."});
    const customer = match.customer;

    if (crmSourceHasV4(customer.source, "BOOKSY")) {
      if (mode !== "TYLKO_KONTAKT" && mode !== "ZABLOKOWANY") {
        return createJsonResponse({success:false,code:"BOOKSY_CONTACT_ONLY",error:"Klient Booksy pozostaje w trybie TYLKO_KONTAKT."});
      }
    }

    if (customer.phone) {
      setClientBookingModeInternal(ss, customer.phone, mode, postData.reason || "Zmiana z listy Klienci", postData.changedBy || "MISTRZYNI", null);
    } else {
      const sh = ensureCustomerSheet(ss);
      sh.getRange(customer.row, 9).setValue(mode);
    }
    return createJsonResponse({success:true,mode:mode,row:customer.row,phone:customer.phone,sourceKey:customer.sourceKey});
  } catch (error) {
    return createJsonResponse({success:false,error:error.toString()});
  }
}

function saveClientV4718Action(ss, postData) {
  try {
    const sh = ensureCustomerSheet(ss);
    const client = postData.client || {};
    const name = String(client.name || "").trim();
    const newPhone = normalizeCRMPhone(client.phone || "");
    if (!name) return createJsonResponse({success:false,error:"Brak imienia i nazwiska klienta"});

    const identity = postData.identity || {
      phone:postData.oldPhone || "", sourceKey:postData.sourceKey || "",
      name:postData.oldName || "", source:postData.source || ""
    };
    const match = crmFindCustomerByIdentityV4718(ss, identity);
    if (match.ambiguous) return createJsonResponse({success:false,code:"AMBIGUOUS_CLIENT",error:"Niejednoznaczny klient — zapis przerwany."});

    if (match.found && match.customer) {
      const current = match.customer;
      if (!newPhone && current.phone && !current.sourceKey) {
        return createJsonResponse({success:false,code:"PHONE_REQUIRED",error:"Nie można usunąć jedynego identyfikatora klienta bez SourceKey."});
      }
      if (newPhone) {
        const existingByPhone = crmFindCustomerByPhoneV4(ss, newPhone);
        if (existingByPhone && existingByPhone.row !== current.row) {
          return createJsonResponse({success:false,code:"PHONE_EXISTS",error:"Inny klient ma już ten numer telefonu."});
        }
      }
      sh.getRange(current.row,1).setValue(newPhone);
      sh.getRange(current.row,2).setValue(name);
      return createJsonResponse({success:true,updated:true,customer:{phone:newPhone,name:name,source:current.source,sourceKey:current.sourceKey,bookingMode:current.bookingMode}});
    }

    if (!newPhone) return createJsonResponse({success:false,code:"PHONE_REQUIRED",error:"Nowy klient dodawany ręcznie musi mieć numer telefonu."});
    const duplicate = crmFindCustomerByPhoneV4(ss, newPhone);
    if (duplicate) return createJsonResponse({success:false,code:"PHONE_EXISTS",error:"Klient z takim telefonem już istnieje."});
    sh.appendRow([newPhone,name,0,0,"",new Date(),"DODANY_PRZEZ_SALON","","WYMAGA_POTWIERDZENIA"]);
    return createJsonResponse({success:true,created:true,customer:{phone:newPhone,name:name,source:"DODANY_PRZEZ_SALON",sourceKey:"",bookingMode:"WYMAGA_POTWIERDZENIA"}});
  } catch (error) {
    return createJsonResponse({success:false,error:error.toString()});
  }
}

