function crmSyncLinkedCustomerStatisticsV4718(ss, phone) {
  const normalized = normalizeCRMPhone(phone || "");
  if (!normalized) return null;
  const customer = crmFindCustomerByPhoneV4(ss, normalized);
  if (!customer) return null;

  const sourceTokens = String(customer.sourceKey || "").split("|")
    .map(function(x){ return String(x || "").trim(); })
    .filter(Boolean);
  const tokenSet = {};
  sourceTokens.forEach(function(token){ tokenSet[token] = true; });

  let counted = 0;
  let lastVisit = customer.lastVisit instanceof Date
    ? customer.lastVisit
    : (customer.lastVisit ? new Date(customer.lastVisit) : null);
  if (lastVisit && isNaN(lastVisit.getTime())) lastVisit = null;

  const bookings = ss.getSheetByName(SHEET_BOOKINGS);
  if (bookings && bookings.getLastRow() > 1) {
    const width = Math.max(14, Math.min(16, bookings.getLastColumn()));
    const rows = bookings.getRange(2,1,bookings.getLastRow()-1,width).getValues();
    rows.forEach(function(row){
      const bookingPhone = normalizeCRMPhone(row[1] || "");
      const sourceRequestId = String(row[13] || "").trim();
      const sourceCode = String(row[12] || "").trim().toUpperCase();
      let belongs = bookingPhone === normalized;
      if (!belongs && sourceRequestId && sourceCode === "WIFE_CALENDAR") {
        belongs = Boolean(
          tokenSet["DOM:" + sourceRequestId] ||
          tokenSet["WIFE:" + sourceRequestId] ||
          tokenSet[sourceRequestId]
        );
      }
      if (!belongs) return;
      counted += 1;
      const d = row[0] instanceof Date ? row[0] : (row[0] ? new Date(row[0]) : null);
      if (d && !isNaN(d.getTime()) && (!lastVisit || d.getTime() > lastVisit.getTime())) lastVisit = d;
    });
  }

  // Nigdy nie obniżamy historycznego licznika klienta przy ręcznym połączeniu.
  // Dla realnych klientów DOM SourceKey pozwala policzyć stare wizyty źródłowe,
  // a Math.max chroni starsze dane/migracje, które nie mają pełnego odwzorowania.
  counted = Math.max(counted, Math.max(0, Number(customer.visits) || 0));
  const sh = ensureCustomerSheet(ss);
  sh.getRange(customer.row,3).setValue(counted);
  sh.getRange(customer.row,5).setValue(lastVisit || "");
  return {visits:counted,lastVisit:lastVisit || "",row:customer.row};
}

