          operationType:"RECONCILE_REVIEW_V4722"
        },true);
        if(!result||!result.appointmentId)throw new Error("Nie udało się utworzyć wizyty podczas RECONCILE: "+item.sourceId);
        const blocks=crmV4722CrmBlocksBySource(ss,settings,item.sourceId,ev.getStartTime(),ev.getEndTime());
        deletedCrmBlocks+=testDeleteCrmEventsV4710(blocks);
        importLogUpdated+=crmV4722UpdateImportLog(ss,item.sourceId,result,String(item.current&&item.current.name||parsed.name||""),String(parsed.service||""),totalPrice);
        deleteRows.push(rowNo);createdVisits++;
        operations.push({sourceId:item.sourceId,action:"AUTO_CREATE_VISIT",result:"OK",appointmentId:result.appointmentId,eventId:result.eventId,deletedBlocks:blocks.length});
        return;
      }

      const sourceLookup=crmV4722GetSourceEventReadOnly(plan.sourceCal,item.sourceId);
      const ev=sourceLookup.event||crmV4720FakeEventFromReview(ss,{sourceId:item.sourceId,client:reviewHit.data[4],service:reviewHit.data[6],start:reviewHit.data[7],raw:reviewHit.data[8]});
      const parsed=testParseExternalCalendarEvent(ev,ss);
      const clientInfo=crmV4722ResolveClient(parsed,String(reviewHit.data[4]||""),crmV4721ClientNameCounts(ss));
      const classInfo=crmV4721ReviewClass(parsed,String(reviewHit.data[4]||""),crmV4721ClientNameCounts(ss));
      const reason=crmV4722ReviewReason(parsed,classInfo);
      review.getRange(rowNo,4).setValue(reason);
