      operations.push({sourceId:item.sourceId,action:"UPDATE_REVIEW",result:"OK",queueClass:classInfo.code,client:String(clientInfo.name||""),service:String(parsed.service||"")});
    });

    Array.from(new Set(deleteRows)).sort(function(a,b){return b-a;}).forEach(function(rowNo){
      if(rowNo>=2&&rowNo<=review.getLastRow())review.deleteRow(rowNo);
    });

    const after=crmV4720ReviewQueueRows(ss);
    return createJsonResponse({
      success:true,version:"4.7.22",operation:"WIFE_REVIEW_RECONCILE_APPLY",applied:true,testOnly:true,
