      booksyConflicts:booksyConflicts,deletedCrmBlocks:deletedCrmBlocks,importLogUpdated:importLogUpdated,operations:operations
    });
  }catch(error){
    return createJsonResponse({success:false,version:"4.7.22",operation:"WIFE_REVIEW_RECONCILE_APPLY",wifeCalendarReadOnly:true,wifeCalendarTouched:false,sourceCalendarTouched:false,error:error.toString()});
